INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('SrekYRvpLYA', 4, '{"title":"第20300520条・五变第四十六","description":"<p>6、黄帝曰。人之善病寒热者。何以候之。少俞答曰。小骨弱肉者。善病寒热。黄帝曰。何以候骨之小大。肉之坚脆。色之不一也。少俞答曰。颧骨者。骨之本也。颧大则骨大。颧小则骨小。皮肤薄而其肉无䐃。其臂懦懦然。其地色殆然。不与其天同色。污然独异。此其候也。然后臂薄者。其髓不满。故善病寒热也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300520,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '6、黄帝曰。人之善病寒热者。何以候之。少俞答曰。小骨弱肉者。善病寒热。黄帝曰。何以候骨之小大。肉之坚脆。色之不一也。少俞答曰。颧骨者。骨之本也。颧大则骨大。颧小则骨小。皮肤薄而其肉无䐃。其臂懦懦然。其地色殆然。不与其天同色。污然独异。此其候也。然后臂薄者。其髓不满。故善病寒热也。', '2024-09-26T13:54:48.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'cvZKnvxZCLH');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('KI3a9B5M50v', 4, '{"title":"第20300521条・五变第四十六","description":"<p>7、黄帝曰。何以候人之善病痹者。少俞答曰。粗理而肉不坚者。善病痹。黄帝曰。痹之高下有处乎。少俞答曰。欲知其高下者。各视其部。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300521,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '7、黄帝曰。何以候人之善病痹者。少俞答曰。粗理而肉不坚者。善病痹。黄帝曰。痹之高下有处乎。少俞答曰。欲知其高下者。各视其部。', '2024-09-26T13:54:48.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'cvZKnvxZCLH');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('G5Nr7nEOihu', 4, '{"title":"第20300522条・五变第四十六","description":"<p>8、黄帝曰。人之善病肠中积聚者。何以候之。少俞答曰。皮肤薄而不泽。肉不坚而淖泽。如此。则肠胃恶。恶则邪气留止。积聚乃伤脾胃之间。寒温不次。邪气稍至。蓄积留止。大聚乃起。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300522,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '8、黄帝曰。人之善病肠中积聚者。何以候之。少俞答曰。皮肤薄而不泽。肉不坚而淖泽。如此。则肠胃恶。恶则邪气留止。积聚乃伤脾胃之间。寒温不次。邪气稍至。蓄积留止。大聚乃起。', '2024-09-26T13:54:48.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'cvZKnvxZCLH');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('3gIyJNU6Wku', 4, '{"title":"第20300523条・五变第四十六","description":"<p>9、黄帝曰。余闻病形。已知之矣。愿闻其时。少俞答曰。先立其年。以知其时。时高则起。时下则殆。虽不陷下。当年有冲道。其病必起。是谓因形而生病。五变之纪也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300523,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '9、黄帝曰。余闻病形。已知之矣。愿闻其时。少俞答曰。先立其年。以知其时。时高则起。时下则殆。虽不陷下。当年有冲道。其病必起。是谓因形而生病。五变之纪也。', '2024-09-26T13:54:48.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'cvZKnvxZCLH');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('tY8AE820C07', 4, '{"title":"第20300524条・本藏第四十七","description":"<p>1、黄帝问于岐伯曰。人之血气精神者。所以奉生而周于性命者也。经脉者。所以行血气而营阴阳。濡筋骨。利关节者也。卫气者。所以温分肉。充皮肤。肥腠理。司开阖者也。志意者。所以御精神。收魂魄。适寒温。和喜怒者也。是故血和则经脉流行。营复阴阳。筋骨劲强。关节清利矣。卫气和则分肉解利。皮肤调柔。腠理致密矣。志意和则精神专直。魂魄不散。悔怒不起。五藏不受邪矣。寒温和则六府化谷。风痹不作。经脉通利。肢节得安矣。此人之常平也。五藏者。所以藏精神血气魂魄者也。六府者。所以化水谷而行津液者也。此人之所以具受于天也。无愚智贤不肖。无以相倚也。然有其独尽天寿。而无邪僻之病。百年不衰。虽犯风雨卒寒大暑。犹有弗能害也。有其不离屏蔽室内。无怵惕之恐。然犹不免于病。何也。愿闻其故。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300524,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '1、黄帝问于岐伯曰。人之血气精神者。所以奉生而周于性命者也。经脉者。所以行血气而营阴阳。濡筋骨。利关节者也。卫气者。所以温分肉。充皮肤。肥腠理。司开阖者也。志意者。所以御精神。收魂魄。适寒温。和喜怒者也。是故血和则经脉流行。营复阴阳。筋骨劲强。关节清利矣。卫气和则分肉解利。皮肤调柔。腠理致密矣。志意和则精神专直。魂魄不散。悔怒不起。五藏不受邪矣。寒温和则六府化谷。风痹不作。经脉通利。肢节得安矣。此人之常平也。五藏者。所以藏精神血气魂魄者也。六府者。所以化水谷而行津液者也。此人之所以具受于天也。无愚智贤不肖。无以相倚也。然有其独尽天寿。而无邪僻之病。百年不衰。虽犯风雨卒寒大暑。犹有弗能害也。有其不离屏蔽室内。无怵惕之恐。然犹不免于病。何也。愿闻其故。', '2024-09-26T13:54:48.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'B4MFDZ1qVRk');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Idh2666pIzI', 4, '{"title":"第20300525条・本藏第四十七","description":"<p>2、岐伯对曰。窘乎哉问也。五藏者。所以参天地。副阴阳。而运四时。化五节者也。五藏者。固有小大。高下。坚脆。端正。偏倾者。六府亦有小大。长短。厚薄。结直。缓急。凡此二十五者。各不同。或善或恶。或吉或凶。请言其方。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300525,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '2、岐伯对曰。窘乎哉问也。五藏者。所以参天地。副阴阳。而运四时。化五节者也。五藏者。固有小大。高下。坚脆。端正。偏倾者。六府亦有小大。长短。厚薄。结直。缓急。凡此二十五者。各不同。或善或恶。或吉或凶。请言其方。', '2024-09-26T13:54:48.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'B4MFDZ1qVRk');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('j7rZopGgX6W', 4, '{"title":"第20300526条・本藏第四十七","description":"<p>3、心小则安。邪弗能伤。易伤以忧。心大则忧。不能伤。易伤于邪。心高则满于肺中。悗而善忘。难开以言。心下。则藏外。易伤于寒。易恐以言。心坚。则藏安守固。心脆则善病消瘅热中。心端正。则和利难伤。心偏倾则操持不一。无守司也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300526,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '3、心小则安。邪弗能伤。易伤以忧。心大则忧。不能伤。易伤于邪。心高则满于肺中。悗而善忘。难开以言。心下。则藏外。易伤于寒。易恐以言。心坚。则藏安守固。心脆则善病消瘅热中。心端正。则和利难伤。心偏倾则操持不一。无守司也。', '2024-09-26T13:54:48.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'B4MFDZ1qVRk');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('SEsKB9uQjdG', 4, '{"title":"第20300527条・本藏第四十七","description":"<p>4、肺小。则少饮。不病喘喝。肺大则多饮。善病胸痹。喉痹。逆气。肺高。则上气。肩息咳。肺下则居贲迫肺。善胁下痛。肺坚则不病。咳上气。肺脆。则苦病消痹易伤。肺端正。则和利难伤。肺偏倾。则胸偏痛也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300527,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '4、肺小。则少饮。不病喘喝。肺大则多饮。善病胸痹。喉痹。逆气。肺高。则上气。肩息咳。肺下则居贲迫肺。善胁下痛。肺坚则不病。咳上气。肺脆。则苦病消痹易伤。肺端正。则和利难伤。肺偏倾。则胸偏痛也。', '2024-09-26T13:54:48.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'B4MFDZ1qVRk');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('vGH140YdfXF', 4, '{"title":"第20300528条・本藏第四十七","description":"<p>5、肺小则藏安。无胁下之病。肝大则逼胃迫咽。迫咽则苦膈中。且胁下痛。肝高。则上支贲切。胁挽为息贲。肝下则逼胃胁下空。胁下空则易受邪。肝坚则藏安难伤。肝脆则善病消痹。易伤。肝端正。则和利难伤。肝偏倾。则胁下痛也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300528,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '5、肺小则藏安。无胁下之病。肝大则逼胃迫咽。迫咽则苦膈中。且胁下痛。肝高。则上支贲切。胁挽为息贲。肝下则逼胃胁下空。胁下空则易受邪。肝坚则藏安难伤。肝脆则善病消痹。易伤。肝端正。则和利难伤。肝偏倾。则胁下痛也。', '2024-09-26T13:54:48.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'B4MFDZ1qVRk');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('9Z2VkQa7BFW', 4, '{"title":"第20300529条・本藏第四十七","description":"<p>6、脾小。则藏安。难伤于邪也。脾大。则苦凑䏚而痛。不能疾行。脾高。则䏚引季胁而痛。脾下则下归于大肠。下加于大肠。则藏苦受邪。脾坚。则藏安难伤。脾脆。则善病消痹易伤。脾端正。则和利难伤。脾偏倾。则善满善胀也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300529,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '6、脾小。则藏安。难伤于邪也。脾大。则苦凑䏚而痛。不能疾行。脾高。则䏚引季胁而痛。脾下则下归于大肠。下加于大肠。则藏苦受邪。脾坚。则藏安难伤。脾脆。则善病消痹易伤。脾端正。则和利难伤。脾偏倾。则善满善胀也。', '2024-09-26T13:54:48.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'B4MFDZ1qVRk');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('52YJysrcfON', 4, '{"title":"第20300530条・本藏第四十七","description":"<p>7、肾小。则藏安难伤。肾大。则善病腰痛。不可以俛仰。易伤以邪。肾高。则苦背膂痛。不可以俛仰。肾下则腰尻痛。不可以俛仰。为狐疝。肾坚。则不病腰背痛。肾脆。则善病消瘅。易伤。肾端正。则和利难伤。肾偏倾。则苦腰尻痛也。凡此二十五变者。人之所苦常病。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300530,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '7、肾小。则藏安难伤。肾大。则善病腰痛。不可以俛仰。易伤以邪。肾高。则苦背膂痛。不可以俛仰。肾下则腰尻痛。不可以俛仰。为狐疝。肾坚。则不病腰背痛。肾脆。则善病消瘅。易伤。肾端正。则和利难伤。肾偏倾。则苦腰尻痛也。凡此二十五变者。人之所苦常病。', '2024-09-26T13:54:48.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'B4MFDZ1qVRk');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('RruQirwWt0I', 4, '{"title":"第20300531条・本藏第四十七","description":"<p>8、黄帝曰。何以知其然也。岐伯曰。赤色小理者。心小。粗理者。心大。无𩩲骬者。心高。𩩲骬小。短。举者。心下。𩩲骬长者。心下坚。𩩲骬弱小以薄者。心脆。𩩲骬直下不举者。心端正。𩩲骬倚一方者。心偏倾也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300531,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '8、黄帝曰。何以知其然也。岐伯曰。赤色小理者。心小。粗理者。心大。无𩩲骬者。心高。𩩲骬小。短。举者。心下。𩩲骬长者。心下坚。𩩲骬弱小以薄者。心脆。𩩲骬直下不举者。心端正。𩩲骬倚一方者。心偏倾也。', '2024-09-26T13:54:48.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'B4MFDZ1qVRk');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('FE06dQNUlUO', 4, '{"title":"第20300532条・本藏第四十七","description":"<p>9、白色小理者。肺小。粗理者。肺大。巨肩反膺陷喉者。肺高。合腋张胁者。肺下。好肩背厚者。肺坚。肩背薄者。肺脆。背膺厚者。肺端正。胁偏疏者。肺偏倾也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300532,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '9、白色小理者。肺小。粗理者。肺大。巨肩反膺陷喉者。肺高。合腋张胁者。肺下。好肩背厚者。肺坚。肩背薄者。肺脆。背膺厚者。肺端正。胁偏疏者。肺偏倾也。', '2024-09-26T13:54:48.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'B4MFDZ1qVRk');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ebN2D1GUUGc', 4, '{"title":"第20300533条・本藏第四十七","description":"<p>10、青色小理者。肝小。粗理者。肝大。广胸反骹者。肝高。合胁兔骹者。肝下。胸胁好者。肝坚。胁骨弱者。肝脆。膺腹好相得者。肝端正。胁骨偏举者。肝偏倾也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300533,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '10、青色小理者。肝小。粗理者。肝大。广胸反骹者。肝高。合胁兔骹者。肝下。胸胁好者。肝坚。胁骨弱者。肝脆。膺腹好相得者。肝端正。胁骨偏举者。肝偏倾也。', '2024-09-26T13:54:48.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'B4MFDZ1qVRk');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('CuLhp8pMipS', 4, '{"title":"第20300534条・本藏第四十七","description":"<p>11、黄色小理者。脾小。粗理者。脾大。揭唇者。脾高。唇下纵者。脾下。唇坚者。脾坚。唇大而不坚者。脾脆。唇上下好者。脾端正。唇偏举者。脾偏倾也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300534,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '11、黄色小理者。脾小。粗理者。脾大。揭唇者。脾高。唇下纵者。脾下。唇坚者。脾坚。唇大而不坚者。脾脆。唇上下好者。脾端正。唇偏举者。脾偏倾也。', '2024-09-26T13:54:48.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'B4MFDZ1qVRk');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('t82r5FInLgQ', 4, '{"title":"第20300535条・本藏第四十七","description":"<p>12、黑色小理者。肾小。粗理者。肾大。高耳者。肾高。耳后陷者。肾下。耳坚者。肾坚。耳薄而不坚者。肾脆。耳好前居牙车者。肾端正。耳偏高者。肾偏倾也。凡此诸变者。持则安。减则病也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300535,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '12、黑色小理者。肾小。粗理者。肾大。高耳者。肾高。耳后陷者。肾下。耳坚者。肾坚。耳薄而不坚者。肾脆。耳好前居牙车者。肾端正。耳偏高者。肾偏倾也。凡此诸变者。持则安。减则病也。', '2024-09-26T13:54:48.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'B4MFDZ1qVRk');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('NhV4xyjmm1V', 4, '{"title":"第20300536条・本藏第四十七","description":"<p>13、帝曰。善。然非余之所问也。愿闻人之有不可病者。至尽天寿。虽有深扰大恐。怵惕之志。犹不能减也。甚寒大热。不能伤也。其有不离屏蔽室内。又无怵惕之恐。然不免于病者。何也。愿闻其故。岐伯曰。五藏六府。邪之舍也。请言其故。五藏皆小者。少病。苦憔心。大愁扰。五藏皆大者。缓于事。难使以扰。五藏皆高者。好高举措。五藏皆下者。好出人下。五藏皆坚者。无病。五藏皆脆者。不离于病。五藏皆端正者。和利得人心。五藏皆偏倾者。邪心而善盗。不可以为人平。反复言语也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300536,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '13、帝曰。善。然非余之所问也。愿闻人之有不可病者。至尽天寿。虽有深扰大恐。怵惕之志。犹不能减也。甚寒大热。不能伤也。其有不离屏蔽室内。又无怵惕之恐。然不免于病者。何也。愿闻其故。岐伯曰。五藏六府。邪之舍也。请言其故。五藏皆小者。少病。苦憔心。大愁扰。五藏皆大者。缓于事。难使以扰。五藏皆高者。好高举措。五藏皆下者。好出人下。五藏皆坚者。无病。五藏皆脆者。不离于病。五藏皆端正者。和利得人心。五藏皆偏倾者。邪心而善盗。不可以为人平。反复言语也。', '2024-09-26T13:54:48.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'B4MFDZ1qVRk');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('LUdLtp6mcYb', 4, '{"title":"第20300537条・本藏第四十七","description":"<p>14、黄帝曰。愿闻六府之应。岐伯答曰。肺合大肠。大肠者。皮其应。心合小肠。小肠者。脉其应。肝合胆。胆者。筋其应。脾合胃。胃者。肉其应。肾合三焦膀胱。三焦膀胱者。腠理毫毛其应。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300537,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '14、黄帝曰。愿闻六府之应。岐伯答曰。肺合大肠。大肠者。皮其应。心合小肠。小肠者。脉其应。肝合胆。胆者。筋其应。脾合胃。胃者。肉其应。肾合三焦膀胱。三焦膀胱者。腠理毫毛其应。', '2024-09-26T13:54:48.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'B4MFDZ1qVRk');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('eJzHkazpYnz', 4, '{"title":"第20300538条・本藏第四十七","description":"<p>15、黄帝曰。应之奈何。岐伯曰。肺应皮。皮厚者。大肠厚。皮薄者。大肠薄。皮缓。腹里大者。大肠大而长。皮急者。大肠急而短。皮滑者。大肠直。皮肉不相离者。大肠结。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300538,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '15、黄帝曰。应之奈何。岐伯曰。肺应皮。皮厚者。大肠厚。皮薄者。大肠薄。皮缓。腹里大者。大肠大而长。皮急者。大肠急而短。皮滑者。大肠直。皮肉不相离者。大肠结。', '2024-09-26T13:54:48.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'B4MFDZ1qVRk');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('L1eDqfZ2MQm', 4, '{"title":"第20300539条・本藏第四十七","description":"<p>16、心应脉。皮厚者。脉厚。脉厚者。小肠厚。皮薄者。脉薄。脉薄者。小肠薄。皮缓者。脉缓。脉缓者。小肠大而长。皮薄而脉冲小者。小肠小而短。诸阳经脉皆多纡屈者。小肠结。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300539,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '16、心应脉。皮厚者。脉厚。脉厚者。小肠厚。皮薄者。脉薄。脉薄者。小肠薄。皮缓者。脉缓。脉缓者。小肠大而长。皮薄而脉冲小者。小肠小而短。诸阳经脉皆多纡屈者。小肠结。', '2024-09-26T13:54:48.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'B4MFDZ1qVRk');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('v5wsC2cNJpc', 4, '{"title":"第20300540条・本藏第四十七","description":"<p>17、脾应肉。肉䐃坚大者。胃厚。肉䐃么者。胃薄。肉䐃小而么者。胃不坚。肉腘不称身者。胃下。胃下者。下管约不利。肉脾不坚者。胃缓。肉䐃无小里累者。胃急。肉䐃多少里累者。胃结。胃结者。上管约不利也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300540,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '17、脾应肉。肉䐃坚大者。胃厚。肉䐃么者。胃薄。肉䐃小而么者。胃不坚。肉腘不称身者。胃下。胃下者。下管约不利。肉脾不坚者。胃缓。肉䐃无小里累者。胃急。肉䐃多少里累者。胃结。胃结者。上管约不利也。', '2024-09-26T13:54:48.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'B4MFDZ1qVRk');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('34KhXIS9Suc', 4, '{"title":"第20300541条・本藏第四十七","description":"<p>18、肝应爪。爪厚色黄者。胆厚。爪薄色红者。胆薄。爪坚色青者。胆急。爪濡色赤者。胆缓。爪直色白无约者。胆直。爪恶色黑多纹者。胆结也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300541,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '18、肝应爪。爪厚色黄者。胆厚。爪薄色红者。胆薄。爪坚色青者。胆急。爪濡色赤者。胆缓。爪直色白无约者。胆直。爪恶色黑多纹者。胆结也。', '2024-09-26T13:54:48.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'B4MFDZ1qVRk');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('h4l7for2Vqn', 4, '{"title":"第20300542条・本藏第四十七","description":"<p>19、肾应骨。密理厚皮者。三焦膀胱厚。粗理薄皮者。三焦膀胱薄。疏腠理者。三焦膀胱缓。皮急而无毫毛者。三焦膀胱急。毫毛美而粗者。三焦膀胱直。稀毫毛者。三焦膀胱结也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300542,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '19、肾应骨。密理厚皮者。三焦膀胱厚。粗理薄皮者。三焦膀胱薄。疏腠理者。三焦膀胱缓。皮急而无毫毛者。三焦膀胱急。毫毛美而粗者。三焦膀胱直。稀毫毛者。三焦膀胱结也。', '2024-09-26T13:54:48.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'B4MFDZ1qVRk');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('cwhA817PHjR', 4, '{"title":"第20300543条・本藏第四十七","description":"<p>20、黄帝曰。厚薄美恶。皆有形。愿闻其所病。岐伯答曰。视其外应。以知其内藏。则知所病矣。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300543,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '20、黄帝曰。厚薄美恶。皆有形。愿闻其所病。岐伯答曰。视其外应。以知其内藏。则知所病矣。', '2024-09-26T13:54:48.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'B4MFDZ1qVRk');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('e20kDRu0Rph', 4, '{"title":"第20300544条・禁服第四十八","description":"<p>1、雷公问于黄帝曰。细子得受。通于九针六十篇。旦暮勤服之。近者编绝。久者简垢。然尚讽诵弗置。未尽解于意矣。「外揣」言浑束为一。未知所谓也。夫大则无外。小则无内。大小无极。高下无度。束之奈何。士之才力。或有厚薄。智虑褊浅。不能博大深奥。自强于学若细子。细子恐其散于后世。绝于子孙。敢问约之奈何。黄帝曰。善乎哉问也。此先师之所禁。坐私传之也。割臂歃血之盟也。子若欲得之。何不斋乎。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300544,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '1、雷公问于黄帝曰。细子得受。通于九针六十篇。旦暮勤服之。近者编绝。久者简垢。然尚讽诵弗置。未尽解于意矣。「外揣」言浑束为一。未知所谓也。夫大则无外。小则无内。大小无极。高下无度。束之奈何。士之才力。或有厚薄。智虑褊浅。不能博大深奥。自强于学若细子。细子恐其散于后世。绝于子孙。敢问约之奈何。黄帝曰。善乎哉问也。此先师之所禁。坐私传之也。割臂歃血之盟也。子若欲得之。何不斋乎。', '2024-09-26T13:54:48.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'QmL3mbiFMpy');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('FlqMz6VjY2g', 4, '{"title":"第20300545条・禁服第四十八","description":"<p>2、雷公再拜而起曰。请闻命于是也。乃斋宿三日而请曰。敢问今日正阳。细子愿以受盟。黄帝乃与俱入斋室。割臂歃血。黄帝亲祝曰。今日正阳。歃血传方。有敢背此言者。反受其殃。雷公再拜曰。细子受之。黄帝乃左握其手。右授之书曰。慎之慎之。吾为子言之。凡刺之理。经脉为始。营其所行。知其度量。内刺五藏。外刺六府。审察卫气。为百病母。调其虚实。虚实乃止。泻其血络。血尽不殆矣。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300545,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '2、雷公再拜而起曰。请闻命于是也。乃斋宿三日而请曰。敢问今日正阳。细子愿以受盟。黄帝乃与俱入斋室。割臂歃血。黄帝亲祝曰。今日正阳。歃血传方。有敢背此言者。反受其殃。雷公再拜曰。细子受之。黄帝乃左握其手。右授之书曰。慎之慎之。吾为子言之。凡刺之理。经脉为始。营其所行。知其度量。内刺五藏。外刺六府。审察卫气。为百病母。调其虚实。虚实乃止。泻其血络。血尽不殆矣。', '2024-09-26T13:54:48.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'QmL3mbiFMpy');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('88mwaXexf3W', 4, '{"title":"第20300546条・禁服第四十八","description":"<p>3、雷公曰。此皆细子之所以通。未知其所约也。黄帝曰。夫约方者。犹约囊也。囊满而弗约。则输泄。方成弗约。则神与弗俱。雷公曰。愿为下材者。勿满而约之。黄帝曰。未满而知约之以为工。不可以为天下师。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300546,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '3、雷公曰。此皆细子之所以通。未知其所约也。黄帝曰。夫约方者。犹约囊也。囊满而弗约。则输泄。方成弗约。则神与弗俱。雷公曰。愿为下材者。勿满而约之。黄帝曰。未满而知约之以为工。不可以为天下师。', '2024-09-26T13:54:48.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'QmL3mbiFMpy');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('iBrayEAD1FZ', 4, '{"title":"第20300547条・禁服第四十八","description":"<p>4、雷公曰。愿闻为工。黄帝曰。寸口主中。人迎主外。两者相应。俱往俱来。若引绳大小齐等。春夏人迎微大。秋冬寸口微大。如是者。名曰平人。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300547,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '4、雷公曰。愿闻为工。黄帝曰。寸口主中。人迎主外。两者相应。俱往俱来。若引绳大小齐等。春夏人迎微大。秋冬寸口微大。如是者。名曰平人。', '2024-09-26T13:54:48.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'QmL3mbiFMpy');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ouvMSYVaIGD', 4, '{"title":"第20300548条・禁服第四十八","description":"<p>5、人迎大一倍于寸口。病在足少阳。一倍而躁。在手少阳。人迎二倍。病在足太阳。二倍而躁。病在手太阳。人迎三倍。病在足阳明。三倍而躁。病在手阳明。盛则为热。虚则为寒。紧则为痛痹。代则乍甚乍间。盛则泻之。虚则补之。紧痛则取之分肉。代则取血络。且饮药。陷下则灸之。不盛不虚。以经取之。名曰经刺。人迎四倍者。且大且数。名曰溢阳。溢阳为外格。死不治。必审按其本末。察其寒热。以验其藏府之病。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300548,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '5、人迎大一倍于寸口。病在足少阳。一倍而躁。在手少阳。人迎二倍。病在足太阳。二倍而躁。病在手太阳。人迎三倍。病在足阳明。三倍而躁。病在手阳明。盛则为热。虚则为寒。紧则为痛痹。代则乍甚乍间。盛则泻之。虚则补之。紧痛则取之分肉。代则取血络。且饮药。陷下则灸之。不盛不虚。以经取之。名曰经刺。人迎四倍者。且大且数。名曰溢阳。溢阳为外格。死不治。必审按其本末。察其寒热。以验其藏府之病。', '2024-09-26T13:54:48.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'QmL3mbiFMpy');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('lYg1FTmsXm1', 4, '{"title":"第20300549条・禁服第四十八","description":"<p>6、寸口大于人迎一倍。病在足厥阴。一倍而躁。在手心主。寸口二倍。病在足少阴。二倍而躁。在手少阴。寸口三倍。病在足太阴。三倍而躁。在手太阴。盛则胀满。寒中。食不化。虚则热中。出糜。少气。溺色变。紧则痛痹。代则乍痛乍止。盛则泻之。虚则补之。紧则先刺而后灸之。代则取血络。而后调之。陷下则徒灸之。陷下者。脉血结于中。中有着血。血寒。故宜灸之。不盛不虚。以经取之。寸口四倍者。名曰内关。内关者。且大且数。死不治。必审察其本末之寒温。以验其藏府之病。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300549,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '6、寸口大于人迎一倍。病在足厥阴。一倍而躁。在手心主。寸口二倍。病在足少阴。二倍而躁。在手少阴。寸口三倍。病在足太阴。三倍而躁。在手太阴。盛则胀满。寒中。食不化。虚则热中。出糜。少气。溺色变。紧则痛痹。代则乍痛乍止。盛则泻之。虚则补之。紧则先刺而后灸之。代则取血络。而后调之。陷下则徒灸之。陷下者。脉血结于中。中有着血。血寒。故宜灸之。不盛不虚。以经取之。寸口四倍者。名曰内关。内关者。且大且数。死不治。必审察其本末之寒温。以验其藏府之病。', '2024-09-26T13:54:48.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'QmL3mbiFMpy');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('bLcI9TB0vVP', 4, '{"title":"第20300550条・禁服第四十八","description":"<p>7、通其营输。乃可传于大数。大数曰。盛则徒泻之。虚则徒补之。紧则灸刺。且饮药。陷下则徒灸之。不盛不虚。以经取之。所谓经治者。饮药。亦曰灸刺。脉急则引。脉大以弱。则欲安静。用力无劳也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300550,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '7、通其营输。乃可传于大数。大数曰。盛则徒泻之。虚则徒补之。紧则灸刺。且饮药。陷下则徒灸之。不盛不虚。以经取之。所谓经治者。饮药。亦曰灸刺。脉急则引。脉大以弱。则欲安静。用力无劳也。', '2024-09-26T13:54:48.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'QmL3mbiFMpy');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('8MCEcjzmREH', 4, '{"title":"第20300551条・五色第四十九","description":"<p>1、雷公问于黄帝曰。五色独决于明堂乎。小子未知其所谓也。黄帝曰。明堂者。鼻也。阙者。眉间也。庭者。颜也。蕃者。颊侧也。蔽者。耳门也。其间欲方大。去之十步。皆见于外。如是者寿。必中百岁。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300551,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '1、雷公问于黄帝曰。五色独决于明堂乎。小子未知其所谓也。黄帝曰。明堂者。鼻也。阙者。眉间也。庭者。颜也。蕃者。颊侧也。蔽者。耳门也。其间欲方大。去之十步。皆见于外。如是者寿。必中百岁。', '2024-09-26T13:54:48.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'NZEymihY36N');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('EElJr4RV2dM', 4, '{"title":"第20300552条・五色第四十九","description":"<p>2、雷公曰。五言之辨。奈何。黄帝曰。明堂骨高以起。平以直。五藏次于中央。六府挟其两侧。首面上于阙庭。王宫在于下极。五藏安于胸中。真色以致。病色不见。明堂润泽以清。五官恶得无辨乎。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300552,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '2、雷公曰。五言之辨。奈何。黄帝曰。明堂骨高以起。平以直。五藏次于中央。六府挟其两侧。首面上于阙庭。王宫在于下极。五藏安于胸中。真色以致。病色不见。明堂润泽以清。五官恶得无辨乎。', '2024-09-26T13:54:48.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'NZEymihY36N');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('rU2x2MEtvke', 4, '{"title":"第20300553条・五色第四十九","description":"<p>3、雷公曰。其不辨者。可得闻乎。黄帝曰。五色之见也。各出其色部。部骨陷者。必不免于病矣。其色部乘袭者。虽病甚。不死矣。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300553,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '3、雷公曰。其不辨者。可得闻乎。黄帝曰。五色之见也。各出其色部。部骨陷者。必不免于病矣。其色部乘袭者。虽病甚。不死矣。', '2024-09-26T13:54:48.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'NZEymihY36N');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('sDLe3ZOxo36', 4, '{"title":"第20300554条・五色第四十九","description":"<p>4、雷公曰。官五色奈何。黄帝曰。青黑为痛。黄赤为热。白为寒。是谓五官。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300554,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '4、雷公曰。官五色奈何。黄帝曰。青黑为痛。黄赤为热。白为寒。是谓五官。', '2024-09-26T13:54:48.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'NZEymihY36N');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('BIwwrqgtfqB', 4, '{"title":"第20300555条・五色第四十九","description":"<p>5、雷公曰。病之益甚。与其方衰。如何。黄帝曰。外内皆在焉。切其脉口。滑小紧以沉者。病益甚。在中。人迎气大紧以浮者。其病益甚。在外。其脉口浮滑者。病日进。人迎沉而滑者。病日损。其脉口滑以沉者。病日进。在内。其人迎脉滑盛以浮者。其病日进。在外。脉之浮沉及人迎与寸口气小大等者。病难已。病之在藏。沉而大者。易已。小为逆。病在府。浮而大者。其病易已。人迎盛坚者。伤于寒。气口盛坚者。伤于食。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300555,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '5、雷公曰。病之益甚。与其方衰。如何。黄帝曰。外内皆在焉。切其脉口。滑小紧以沉者。病益甚。在中。人迎气大紧以浮者。其病益甚。在外。其脉口浮滑者。病日进。人迎沉而滑者。病日损。其脉口滑以沉者。病日进。在内。其人迎脉滑盛以浮者。其病日进。在外。脉之浮沉及人迎与寸口气小大等者。病难已。病之在藏。沉而大者。易已。小为逆。病在府。浮而大者。其病易已。人迎盛坚者。伤于寒。气口盛坚者。伤于食。', '2024-09-26T13:54:48.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'NZEymihY36N');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('W10gglZV0Im', 4, '{"title":"第20300556条・五色第四十九","description":"<p>6、雷公曰。以色言食之间甚。奈何。黄帝曰。其色粗以明。沉夭者为甚。其色上行者。病益甚。其色下行。如云彻散者。病方已。五色各有藏部。有外部有内部也。色从外部走内部者。其病从外走内。其色从内走外者。其病从内走外。病生于内者。先治其阴。后治其阳。反者益甚。其病生于阳者。先治其外。后治其内。反者益甚。其脉滑大。以代而长者。病从外来。目有所见。志有所恶。此阳气之并也。可变而已。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300556,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '6、雷公曰。以色言食之间甚。奈何。黄帝曰。其色粗以明。沉夭者为甚。其色上行者。病益甚。其色下行。如云彻散者。病方已。五色各有藏部。有外部有内部也。色从外部走内部者。其病从外走内。其色从内走外者。其病从内走外。病生于内者。先治其阴。后治其阳。反者益甚。其病生于阳者。先治其外。后治其内。反者益甚。其脉滑大。以代而长者。病从外来。目有所见。志有所恶。此阳气之并也。可变而已。', '2024-09-26T13:54:48.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'NZEymihY36N');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('juCkbMq9qoH', 4, '{"title":"第20300557条・五色第四十九","description":"<p>7、雷公曰。小子闻风者。百病之始也。厥逆者。寒湿之起也。别之奈何。黄帝曰。常候阙中。薄泽为风。冲浊为痹。在地为厥。此其常也。各以其色言其病。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300557,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '7、雷公曰。小子闻风者。百病之始也。厥逆者。寒湿之起也。别之奈何。黄帝曰。常候阙中。薄泽为风。冲浊为痹。在地为厥。此其常也。各以其色言其病。', '2024-09-26T13:54:48.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'NZEymihY36N');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('zYEavW8MVGc', 4, '{"title":"第20300558条・五色第四十九","description":"<p>8、雷公曰。人不病卒死。何以知之。黄帝曰。大气入于藏府者。不病而卒死矣。雷公曰。病小愈而卒死者。何以知之。黄帝曰。赤色出两颧。大如拇指者。病虽小愈。必卒死。黑色出于庭。大如拇指。必不病而卒死。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300558,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '8、雷公曰。人不病卒死。何以知之。黄帝曰。大气入于藏府者。不病而卒死矣。雷公曰。病小愈而卒死者。何以知之。黄帝曰。赤色出两颧。大如拇指者。病虽小愈。必卒死。黑色出于庭。大如拇指。必不病而卒死。', '2024-09-26T13:54:48.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'NZEymihY36N');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('TcDyCTP7jTZ', 4, '{"title":"第20300559条・五色第四十九","description":"<p>9、雷公再拜曰。善哉。其死有期乎。黄帝曰。察色以言其时。雷公曰。善乎。愿卒闻之。黄帝曰。庭者。首面也。阙上者。咽喉也。阙中者。肺也。下极者。心也。直下者。肝也。肝左者。胆也。下者。脾也。方上者。胃也。中央者。大肠也。挟大肠者。肾也。当肾者。脐也。面王以上者。小肠也。面王以下者。膀胱子处也。颧者。肩也。颧后者。臂也。臂下者。手也。目内眦上者。膺乳也。挟绳而上者。背也。循牙车以下者。股也。中央者。膝也。膝以下者。胫也。当胫以下者。足也。巨分者。股里也。巨屈者。膝膑也。此五藏六府肢节之部也。各有部分。有部分。用阴和阳。用阳和阴。当明部分。万举万当。能别左右。是谓大道。男女异位。故曰阴阳。审察泽夭。谓之良工。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300559,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '9、雷公再拜曰。善哉。其死有期乎。黄帝曰。察色以言其时。雷公曰。善乎。愿卒闻之。黄帝曰。庭者。首面也。阙上者。咽喉也。阙中者。肺也。下极者。心也。直下者。肝也。肝左者。胆也。下者。脾也。方上者。胃也。中央者。大肠也。挟大肠者。肾也。当肾者。脐也。面王以上者。小肠也。面王以下者。膀胱子处也。颧者。肩也。颧后者。臂也。臂下者。手也。目内眦上者。膺乳也。挟绳而上者。背也。循牙车以下者。股也。中央者。膝也。膝以下者。胫也。当胫以下者。足也。巨分者。股里也。巨屈者。膝膑也。此五藏六府肢节之部也。各有部分。有部分。用阴和阳。用阳和阴。当明部分。万举万当。能别左右。是谓大道。男女异位。故曰阴阳。审察泽夭。谓之良工。', '2024-09-26T13:54:48.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'NZEymihY36N');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('1P0hlpjWVh9', 4, '{"title":"第20300560条・五色第四十九","description":"<p>10、沉浊为内。浮泽为外。黄赤为风。青黑为痛。白为寒。黄而膏润为脓。赤甚者为血痛。甚为挛。寒甚为皮不仁。五色各见其部。察其浮沉。以知浅深。察其泽夭。以观成败。察其散搏。以知远近。视色上下。以知病处。积神于心。以知往今。故相气不微。不知是非。属意勿去。乃知新故。色明不粗。沉天为甚。不明不泽。其病不甚。其色散。驹驹然。未有聚。其病散而气痛。聚未成也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300560,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '10、沉浊为内。浮泽为外。黄赤为风。青黑为痛。白为寒。黄而膏润为脓。赤甚者为血痛。甚为挛。寒甚为皮不仁。五色各见其部。察其浮沉。以知浅深。察其泽夭。以观成败。察其散搏。以知远近。视色上下。以知病处。积神于心。以知往今。故相气不微。不知是非。属意勿去。乃知新故。色明不粗。沉天为甚。不明不泽。其病不甚。其色散。驹驹然。未有聚。其病散而气痛。聚未成也。', '2024-09-26T13:54:48.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'NZEymihY36N');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('iM4F7jYnv2H', 4, '{"title":"第20300561条・五色第四十九","description":"<p>11、肾乘心。心先病。肾为应。色皆如是。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300561,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '11、肾乘心。心先病。肾为应。色皆如是。', '2024-09-26T13:54:48.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'NZEymihY36N');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('PtzYK38TlXu', 4, '{"title":"第20300562条・五色第四十九","description":"<p>12、男子色在于面王。为小腹痛。下为卵痛。其圜直为茎痛。高为本。下为首。狐疝㿉阴之属也。女子在于面王。为膀胱子处之病。散为痛。搏为聚。方员左右。各如其色形。其随而下至胝。为淫。有润如膏状。为暴食不洁。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300562,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '12、男子色在于面王。为小腹痛。下为卵痛。其圜直为茎痛。高为本。下为首。狐疝㿉阴之属也。女子在于面王。为膀胱子处之病。散为痛。搏为聚。方员左右。各如其色形。其随而下至胝。为淫。有润如膏状。为暴食不洁。', '2024-09-26T13:54:48.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'NZEymihY36N');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('9EIqhVAFwLR', 4, '{"title":"第20300563条・五色第四十九","description":"<p>13、左为左。右为右。其色有邪。聚散而不端。面色所指者也。色者。青黑赤白黄。皆端满有别乡。别乡赤者。其色赤。大如榆荚。在面王为不日。其色上锐。首空上向。下锐下向。在左右如法。以五色命藏。青为肝。赤为心。白为肺。黄为脾。黑为肾。肝合筋。心合脉。肺合皮。脾合肉。肾合骨也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300563,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '13、左为左。右为右。其色有邪。聚散而不端。面色所指者也。色者。青黑赤白黄。皆端满有别乡。别乡赤者。其色赤。大如榆荚。在面王为不日。其色上锐。首空上向。下锐下向。在左右如法。以五色命藏。青为肝。赤为心。白为肺。黄为脾。黑为肾。肝合筋。心合脉。肺合皮。脾合肉。肾合骨也。', '2024-09-26T13:54:48.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'NZEymihY36N');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('1Y0d62q5rQa', 4, '{"title":"第20300564条・论勇第五十","description":"<p>1、黄帝问于少俞曰。有人于此。并行并立。其年之长少等也。衣之厚薄均也。卒然遇烈风暴雨。或病或不病。或皆病。或皆不病。其故何也。少俞曰。帝问何急。黄帝曰。愿尽闻之。少俞曰。春青风夏阳风。秋凉风。冬寒风。凡此四时之风者。其所病各不同形。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300564,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '1、黄帝问于少俞曰。有人于此。并行并立。其年之长少等也。衣之厚薄均也。卒然遇烈风暴雨。或病或不病。或皆病。或皆不病。其故何也。少俞曰。帝问何急。黄帝曰。愿尽闻之。少俞曰。春青风夏阳风。秋凉风。冬寒风。凡此四时之风者。其所病各不同形。', '2024-09-26T13:54:48.000Z', 1, NULL, 'ghBqURJwurj', 'section', '4gouY6m9F04');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('xFX76aHNM5t', 4, '{"title":"第20300565条・论勇第五十","description":"<p>2、黄帝曰。四时之风。病人如何。少俞曰。黄色薄皮弱肉者。不胜春之虚风。白色薄皮弱肉者。不胜夏之虚风。青色薄皮弱肉。不胜秋之虚风。赤色薄皮弱肉。不胜冬之虚风也。黄帝曰。黑色不病乎。少俞曰。黑色而皮厚肉坚。固不伤于四时之风。其皮薄而肉不坚。色不一者。长夏至而有虚风者。病矣。其皮厚而肌肉坚者。长夏至而有虚风。不病矣。其皮厚而肌肉坚者。必重感于寒。外内皆然。乃病。黄帝曰。善。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300565,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '2、黄帝曰。四时之风。病人如何。少俞曰。黄色薄皮弱肉者。不胜春之虚风。白色薄皮弱肉者。不胜夏之虚风。青色薄皮弱肉。不胜秋之虚风。赤色薄皮弱肉。不胜冬之虚风也。黄帝曰。黑色不病乎。少俞曰。黑色而皮厚肉坚。固不伤于四时之风。其皮薄而肉不坚。色不一者。长夏至而有虚风者。病矣。其皮厚而肌肉坚者。长夏至而有虚风。不病矣。其皮厚而肌肉坚者。必重感于寒。外内皆然。乃病。黄帝曰。善。', '2024-09-26T13:54:48.000Z', 1, NULL, 'ghBqURJwurj', 'section', '4gouY6m9F04');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('VIoYZKdObsz', 4, '{"title":"第20300566条・论勇第五十","description":"<p>3、黄帝曰。夫人之忍痛与不忍痛。非勇怯之分也。夫勇士之不忍痛者。见难则前。见痛则止。夫怯士之忍痛者。闻难则恐。遇痛不动。夫勇士之忍痛者。见难不恐。遇痛不动。夫怯士之不忍痛者。见难与痛。目转面盻。恐不能言。失气。惊。颜色变化。乍死乍生。余见其然也。不知其何由。愿闻其故。少俞曰。夫忍痛与不忍痛者。皮肤之薄厚。肌肉之坚脆。缓急之分也。非勇怯之谓也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300566,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '3、黄帝曰。夫人之忍痛与不忍痛。非勇怯之分也。夫勇士之不忍痛者。见难则前。见痛则止。夫怯士之忍痛者。闻难则恐。遇痛不动。夫勇士之忍痛者。见难不恐。遇痛不动。夫怯士之不忍痛者。见难与痛。目转面盻。恐不能言。失气。惊。颜色变化。乍死乍生。余见其然也。不知其何由。愿闻其故。少俞曰。夫忍痛与不忍痛者。皮肤之薄厚。肌肉之坚脆。缓急之分也。非勇怯之谓也。', '2024-09-26T13:54:48.000Z', 1, NULL, 'ghBqURJwurj', 'section', '4gouY6m9F04');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('U7O0P3ugNuR', 4, '{"title":"第20300567条・论勇第五十","description":"<p>4、黄帝曰。愿闻勇怯之所由然。少俞曰。勇士者。目深以固。长冲直扬。三焦理横。其心端直。其肝大以坚。其胆满以傍。怒则气盛而胸张。肝举而胆横。眦裂而目扬。毛起而面苍。此勇士之由然者也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300567,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '4、黄帝曰。愿闻勇怯之所由然。少俞曰。勇士者。目深以固。长冲直扬。三焦理横。其心端直。其肝大以坚。其胆满以傍。怒则气盛而胸张。肝举而胆横。眦裂而目扬。毛起而面苍。此勇士之由然者也。', '2024-09-26T13:54:48.000Z', 1, NULL, 'ghBqURJwurj', 'section', '4gouY6m9F04');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('nZeSlUkEnvy', 4, '{"title":"第20300568条・论勇第五十","description":"<p>5、黄帝曰。愿闻怯士之所由然。少俞曰。怯士者。目大而不减。阴阳相失。其焦理。纵𩩲骬短而小。肝系缓。其胆不满而纵。肠胃挺。胁下空。虽方大怒。气不能满其胸。肝肺虽举。气衰复下。故不能久怒。此怯士之所由然者也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300568,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '5、黄帝曰。愿闻怯士之所由然。少俞曰。怯士者。目大而不减。阴阳相失。其焦理。纵𩩲骬短而小。肝系缓。其胆不满而纵。肠胃挺。胁下空。虽方大怒。气不能满其胸。肝肺虽举。气衰复下。故不能久怒。此怯士之所由然者也。', '2024-09-26T13:54:48.000Z', 1, NULL, 'ghBqURJwurj', 'section', '4gouY6m9F04');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('n4lBt8k0Wr0', 4, '{"title":"第20300569条・论勇第五十","description":"<p>6、黄帝曰。怯士之得酒。怒不避勇士者。何藏使然。少俞曰。酒者。水谷之精。熟谷之液也。其气慓悍。其入于胃中。则胃胀。气上逆。满于胸中。肝浮胆横。当是之时。固比于勇士。气衰则悔。与勇士同类。不知避之。名曰酒悖也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300569,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '6、黄帝曰。怯士之得酒。怒不避勇士者。何藏使然。少俞曰。酒者。水谷之精。熟谷之液也。其气慓悍。其入于胃中。则胃胀。气上逆。满于胸中。肝浮胆横。当是之时。固比于勇士。气衰则悔。与勇士同类。不知避之。名曰酒悖也。', '2024-09-26T13:54:48.000Z', 1, NULL, 'ghBqURJwurj', 'section', '4gouY6m9F04');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('INxIcnzaWJr', 4, '{"title":"第20300570条・背腧第五十一","description":"<p>1、黄帝问于岐伯曰。愿闻五藏之腧。出于背者。岐伯曰。背中大腧。在杼骨之端。肺腧在三焦之间。心腧在五焦之间。膈腧在七焦之间。肝腧在九焦之间。脾腧在十一焦之间。肾腧在十四焦之间。皆挟脊相去三寸所。则欲得而验之。按其处。应在中而痛解。乃其输也。灸之则可刺之则不可。气盛则泻之。虚则补之。以火补者。毋吹其火。须自灭也。以火泻之。疾吹其火。传其艾。须其火灭也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300570,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '1、黄帝问于岐伯曰。愿闻五藏之腧。出于背者。岐伯曰。背中大腧。在杼骨之端。肺腧在三焦之间。心腧在五焦之间。膈腧在七焦之间。肝腧在九焦之间。脾腧在十一焦之间。肾腧在十四焦之间。皆挟脊相去三寸所。则欲得而验之。按其处。应在中而痛解。乃其输也。灸之则可刺之则不可。气盛则泻之。虚则补之。以火补者。毋吹其火。须自灭也。以火泻之。疾吹其火。传其艾。须其火灭也。', '2024-09-26T13:54:48.000Z', 1, NULL, 'ghBqURJwurj', 'section', '3XVS2irp26P');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('1iPIvk3cJOZ', 4, '{"title":"第20300571条・卫气第五十二","description":"<p>1、黄帝曰。五藏者。所以藏精神魂魄者也。六府者。所以受水谷而行化物者也。其气内干五藏。而外络肢节。其浮气之不循经者。为卫气。其精气之行于经者。为营气。阴阳相随。外内相贯。如环之无端。亭亭淳淳乎。孰能窃之。然其分别阴阳。皆有标本虚实所离之处。能别阴阳十二经者。知病之所生。候虚实之所在者。能得病之高下。知六府之气街者。能知解结契绍于门户。能知虚石之坚软者。知补泻之所在。能知六经标本者。可以无惑于天下。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300571,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '1、黄帝曰。五藏者。所以藏精神魂魄者也。六府者。所以受水谷而行化物者也。其气内干五藏。而外络肢节。其浮气之不循经者。为卫气。其精气之行于经者。为营气。阴阳相随。外内相贯。如环之无端。亭亭淳淳乎。孰能窃之。然其分别阴阳。皆有标本虚实所离之处。能别阴阳十二经者。知病之所生。候虚实之所在者。能得病之高下。知六府之气街者。能知解结契绍于门户。能知虚石之坚软者。知补泻之所在。能知六经标本者。可以无惑于天下。', '2024-09-26T13:54:48.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'z7hk136mluJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ZlVTcpWyq12', 4, '{"title":"第20300572条・卫气第五十二","description":"<p>2、岐伯曰。博哉。圣帝之论。臣请尽意悉言之。足太阳之本。在限以上五寸中。标在两络命门。命门者。目也。足少阳之本。在窍阴之间。标在窗笼之前。窗笼者。耳也。足少阴之本。在内踝下上三寸中。标在背输与舌下两脉也。足厥阴之本。在行间上五寸所。标在背腧也。足阳明之本。在厉兑。标在人迎。颊挟颃颡也。足太阴之本。在中封前上四寸之中。标在背腧与舌本也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300572,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '2、岐伯曰。博哉。圣帝之论。臣请尽意悉言之。足太阳之本。在限以上五寸中。标在两络命门。命门者。目也。足少阳之本。在窍阴之间。标在窗笼之前。窗笼者。耳也。足少阴之本。在内踝下上三寸中。标在背输与舌下两脉也。足厥阴之本。在行间上五寸所。标在背腧也。足阳明之本。在厉兑。标在人迎。颊挟颃颡也。足太阴之本。在中封前上四寸之中。标在背腧与舌本也。', '2024-09-26T13:54:48.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'z7hk136mluJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('z1p71jwnipr', 4, '{"title":"第20300573条・卫气第五十二","description":"<p>3、手太阳之本。在外踝之后。标在命门之上一寸也。手少阳之本。在小指次指之间上二寸。标在耳后上角下外眦也。手阳明之本。在肘骨中。上至别阳。标在颜下合钳上也。手太阴之本。在寸口之中。标在腋内动也。手少阴之本。在锐骨之端。标在背腧也。手心主之本。在掌后两筋之间二寸中。标在腋下下三寸也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300573,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '3、手太阳之本。在外踝之后。标在命门之上一寸也。手少阳之本。在小指次指之间上二寸。标在耳后上角下外眦也。手阳明之本。在肘骨中。上至别阳。标在颜下合钳上也。手太阴之本。在寸口之中。标在腋内动也。手少阴之本。在锐骨之端。标在背腧也。手心主之本。在掌后两筋之间二寸中。标在腋下下三寸也。', '2024-09-26T13:54:48.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'z7hk136mluJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ZqLMwvf05BT', 4, '{"title":"第20300574条・卫气第五十二","description":"<p>4、凡候此者。下虚则厥。下盛则热。上虚则眩。上盛则热痛。故石者。绝而止之。虚者。引而起之。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300574,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '4、凡候此者。下虚则厥。下盛则热。上虚则眩。上盛则热痛。故石者。绝而止之。虚者。引而起之。', '2024-09-26T13:54:48.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'z7hk136mluJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('OjK5QDiTEtY', 4, '{"title":"第20300575条・卫气第五十二","description":"<p>5、请言气街。胸气有街。腹气有街。头气有街。胫气有街。故气在头者。止之于脑。气在胸者。止之膺与背腧。气在腹者。止之背腧。与冲脉于脐左右之动脉者。气在胫者。止之于气街。与承山踝上以下。取此者。用毫针。必先按而在久应于手。乃刺而予之。所治者。头痛眩。腹痛中满暴胀。及有新。痛可移者。易已也。积不痛。难已也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300575,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '5、请言气街。胸气有街。腹气有街。头气有街。胫气有街。故气在头者。止之于脑。气在胸者。止之膺与背腧。气在腹者。止之背腧。与冲脉于脐左右之动脉者。气在胫者。止之于气街。与承山踝上以下。取此者。用毫针。必先按而在久应于手。乃刺而予之。所治者。头痛眩。腹痛中满暴胀。及有新。痛可移者。易已也。积不痛。难已也。', '2024-09-26T13:54:48.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'z7hk136mluJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('4JvuuWpfYuR', 4, '{"title":"第20300576条・论痛第五十三","description":"<p>1、黄帝问于少俞曰。筋骨之强弱。肌肉之坚脆。皮肤之厚薄。腠理之疏密。各不同。其于针石火焫之痛何如。肠胃之厚薄坚脆亦不等。其于毒药何如。愿尽闻之。少俞曰。人之骨强。筋弱。肉缓。皮肤厚者。耐痛。其于针石之痛火焫亦然。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300576,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '1、黄帝问于少俞曰。筋骨之强弱。肌肉之坚脆。皮肤之厚薄。腠理之疏密。各不同。其于针石火焫之痛何如。肠胃之厚薄坚脆亦不等。其于毒药何如。愿尽闻之。少俞曰。人之骨强。筋弱。肉缓。皮肤厚者。耐痛。其于针石之痛火焫亦然。', '2024-09-26T13:54:48.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'SkZ49YStY2e');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('v0RYjwK0Gbb', 4, '{"title":"第20300577条・论痛第五十三","description":"<p>2、黄帝曰。其耐火煤者。何以知之。少俞答曰。加以黑色而美骨者。耐火焫。黄帝曰。其不耐针石之痛者。何以知之。少俞曰。坚肉薄皮者。不耐针石之痛。于火焫亦然。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300577,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '2、黄帝曰。其耐火煤者。何以知之。少俞答曰。加以黑色而美骨者。耐火焫。黄帝曰。其不耐针石之痛者。何以知之。少俞曰。坚肉薄皮者。不耐针石之痛。于火焫亦然。', '2024-09-26T13:54:48.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'SkZ49YStY2e');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('5vOd3znytzB', 4, '{"title":"第20300578条・论痛第五十三","description":"<p>3、黄帝曰。人之病。或同时而伤。或易已。或难已。其故何如。少俞曰。同时而伤。其身多热者。易已。多寒者。难已。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300578,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '3、黄帝曰。人之病。或同时而伤。或易已。或难已。其故何如。少俞曰。同时而伤。其身多热者。易已。多寒者。难已。', '2024-09-26T13:54:48.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'SkZ49YStY2e');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('4utk4VC7CMR', 4, '{"title":"第20300579条・论痛第五十三","description":"<p>4、黄帝曰。人之胜毒。何以知之。少俞曰。胃厚。色黑。大骨及肥骨者。皆胜毒。故其瘦而薄胃者。皆不胜毒也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300579,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '4、黄帝曰。人之胜毒。何以知之。少俞曰。胃厚。色黑。大骨及肥骨者。皆胜毒。故其瘦而薄胃者。皆不胜毒也。', '2024-09-26T13:54:48.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'SkZ49YStY2e');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('aFnHwkAIBMH', 4, '{"title":"第20300580条・天年第五十四","description":"<p>1、黄帝问于岐伯曰。愿闻人之始生。何气筑为基。何立而为楯。何失而死。何得而生。岐伯曰。以母为基。以父为楯。失神者死。得神者生也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300580,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '1、黄帝问于岐伯曰。愿闻人之始生。何气筑为基。何立而为楯。何失而死。何得而生。岐伯曰。以母为基。以父为楯。失神者死。得神者生也。', '2024-09-26T13:54:48.000Z', 1, NULL, 'ghBqURJwurj', 'section', '5PEwnSZYMx4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('u5x5M6wv71d', 4, '{"title":"第20300581条・天年第五十四","description":"<p>2、黄帝曰。何者为神。岐伯曰。血气已和。营卫已通。五藏已成。神气舍心。魂魄毕具。乃成为人。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300581,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '2、黄帝曰。何者为神。岐伯曰。血气已和。营卫已通。五藏已成。神气舍心。魂魄毕具。乃成为人。', '2024-09-26T13:54:48.000Z', 1, NULL, 'ghBqURJwurj', 'section', '5PEwnSZYMx4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('03C0aLImeGl', 4, '{"title":"第20300582条・天年第五十四","description":"<p>3、黄帝曰。人之寿夭各不同。或夭寿。或卒死。或病久。愿闻其道。岐伯曰。五藏坚固。血脉和调。肌肉解利。皮肤致密。营卫之行。不失其常。呼吸微徐。气以度行。六府化谷。津液布扬。各如其常。故能长久。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300582,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '3、黄帝曰。人之寿夭各不同。或夭寿。或卒死。或病久。愿闻其道。岐伯曰。五藏坚固。血脉和调。肌肉解利。皮肤致密。营卫之行。不失其常。呼吸微徐。气以度行。六府化谷。津液布扬。各如其常。故能长久。', '2024-09-26T13:54:48.000Z', 1, NULL, 'ghBqURJwurj', 'section', '5PEwnSZYMx4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('2MJHaU9pdHC', 4, '{"title":"第20300583条・天年第五十四","description":"<p>4、黄帝曰。人之寿百岁而死。何以致之。岐伯曰。使道隧以长。基墙高以方。通调营卫。三部三里起。骨高肉满。百岁乃得终。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300583,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '4、黄帝曰。人之寿百岁而死。何以致之。岐伯曰。使道隧以长。基墙高以方。通调营卫。三部三里起。骨高肉满。百岁乃得终。', '2024-09-26T13:54:48.000Z', 1, NULL, 'ghBqURJwurj', 'section', '5PEwnSZYMx4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('CZOqijjuE78', 4, '{"title":"第20300584条・天年第五十四","description":"<p>5、黄帝曰。其气之盛衰。以至其死。可得闻乎。岐伯曰。人生十岁。五藏始定。血气已通。其气在下。故好走。二十岁。血气始盛肌肉方长。故好趋。三十岁。五藏大定。肌肉坚固。血脉盛满。故好步。四十岁。五藏六府十二经脉。皆大盛以平定。腠理始疏。荣华颓落。发颇斑白。平盛不摇。故好坐。五十岁。肝气始衰。肝叶始薄。胆汁始减。目始不明。六十岁。心气始衰。若忧悲。血气懈惰。故好卧。七十岁。脾气虚。皮肤枯。八十岁。肺气衰。魄离。故言善误。九十岁。肾气焦。四藏经脉空虚。百岁。五藏皆虚。神气皆去。形骸独居而终矣。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300584,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '5、黄帝曰。其气之盛衰。以至其死。可得闻乎。岐伯曰。人生十岁。五藏始定。血气已通。其气在下。故好走。二十岁。血气始盛肌肉方长。故好趋。三十岁。五藏大定。肌肉坚固。血脉盛满。故好步。四十岁。五藏六府十二经脉。皆大盛以平定。腠理始疏。荣华颓落。发颇斑白。平盛不摇。故好坐。五十岁。肝气始衰。肝叶始薄。胆汁始减。目始不明。六十岁。心气始衰。若忧悲。血气懈惰。故好卧。七十岁。脾气虚。皮肤枯。八十岁。肺气衰。魄离。故言善误。九十岁。肾气焦。四藏经脉空虚。百岁。五藏皆虚。神气皆去。形骸独居而终矣。', '2024-09-26T13:54:48.000Z', 1, NULL, 'ghBqURJwurj', 'section', '5PEwnSZYMx4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('7q2m3K40Lwe', 4, '{"title":"第20300585条・天年第五十四","description":"<p>6、黄帝曰。其不能终寿而死者。何如。岐伯曰。其五藏皆不坚。使道不长。空外以张。喘息暴疾。又卑基墙薄。脉少血。其肉不石。数中风寒。血气虚。脉不通。真邪相攻。乱而相引。故中寿而尽也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300585,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '6、黄帝曰。其不能终寿而死者。何如。岐伯曰。其五藏皆不坚。使道不长。空外以张。喘息暴疾。又卑基墙薄。脉少血。其肉不石。数中风寒。血气虚。脉不通。真邪相攻。乱而相引。故中寿而尽也。', '2024-09-26T13:54:48.000Z', 1, NULL, 'ghBqURJwurj', 'section', '5PEwnSZYMx4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Xk05kF44rzP', 4, '{"title":"第20300586条・逆顺第五十五","description":"<p>1、黄帝问于伯高曰。余闻气有逆顺。脉有盛衰。刺有大约。可得闻乎。伯高曰。气之逆顺者。所以应天地阴阳四时五行也。脉之盛衰者。所以候血气之虚实有余不足。刺之大约者。必明知病之可刺。与其未可刺。与其已不可刺也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300586,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '1、黄帝问于伯高曰。余闻气有逆顺。脉有盛衰。刺有大约。可得闻乎。伯高曰。气之逆顺者。所以应天地阴阳四时五行也。脉之盛衰者。所以候血气之虚实有余不足。刺之大约者。必明知病之可刺。与其未可刺。与其已不可刺也。', '2024-09-26T13:54:48.000Z', 1, NULL, 'ghBqURJwurj', 'section', '7tuoSLSPtmr');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('OURe1FAr5As', 4, '{"title":"第20300587条・逆顺第五十五","description":"<p>2、黄帝曰。候之奈何。伯高曰。兵法曰无迎逢逢之气。无击堂堂之阵。刺法曰。无刺熇熇之热。无刺漉漉之汗。无刺浑浑之脉。无刺病与脉相逆者。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300587,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '2、黄帝曰。候之奈何。伯高曰。兵法曰无迎逢逢之气。无击堂堂之阵。刺法曰。无刺熇熇之热。无刺漉漉之汗。无刺浑浑之脉。无刺病与脉相逆者。', '2024-09-26T13:54:48.000Z', 1, NULL, 'ghBqURJwurj', 'section', '7tuoSLSPtmr');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('JO3MXNZFnD2', 4, '{"title":"第20300588条・逆顺第五十五","description":"<p>3、黄帝曰。候其可刺奈何。伯高曰。上工。刺其未生者也。其次。刺其未盛者也。其次。刺其已衰者也。下工。刺其方袭者也。与其形之盛者也。与其病之与脉相逆者也。故曰。方其盛也。勿敢毁伤。刺其已衰。事必大昌。故曰。上工治未病。不治已病。此之谓也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300588,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '3、黄帝曰。候其可刺奈何。伯高曰。上工。刺其未生者也。其次。刺其未盛者也。其次。刺其已衰者也。下工。刺其方袭者也。与其形之盛者也。与其病之与脉相逆者也。故曰。方其盛也。勿敢毁伤。刺其已衰。事必大昌。故曰。上工治未病。不治已病。此之谓也。', '2024-09-26T13:54:48.000Z', 1, NULL, 'ghBqURJwurj', 'section', '7tuoSLSPtmr');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('06zC1j41BfX', 4, '{"title":"第20300589条・五味第五十六","description":"<p>1、黄帝曰。愿闻谷气有五味。其入五藏。分别奈何。伯高曰。胃者。五藏六府之海也。水谷皆入于胃。五藏六府。皆禀气于胃。五味各走其所喜。谷味酸。先走肝。谷味苦。先走心。谷味甘。先走脾。谷味辛。先走肺。谷味咸。先走肾。谷气津液已行。营卫大通。乃化糟粕。以次传下。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300589,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '1、黄帝曰。愿闻谷气有五味。其入五藏。分别奈何。伯高曰。胃者。五藏六府之海也。水谷皆入于胃。五藏六府。皆禀气于胃。五味各走其所喜。谷味酸。先走肝。谷味苦。先走心。谷味甘。先走脾。谷味辛。先走肺。谷味咸。先走肾。谷气津液已行。营卫大通。乃化糟粕。以次传下。', '2024-09-26T13:54:48.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'yUivbRN0OzS');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('4zkd5AFjgVd', 4, '{"title":"第20300590条・五味第五十六","description":"<p>2、黄帝曰。营卫之行奈何。伯高曰。谷始入于胃。其精微者。先出于胃之两焦。以溉五藏。别出两行。营卫之道。其大气之搏而不行者。积于胸中。命曰气海。出于肺。循咽喉。故呼则出。吸则入。天地之精气。其大数常出三入一。故谷不入。半日则气衰。一日则气少矣。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300590,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '2、黄帝曰。营卫之行奈何。伯高曰。谷始入于胃。其精微者。先出于胃之两焦。以溉五藏。别出两行。营卫之道。其大气之搏而不行者。积于胸中。命曰气海。出于肺。循咽喉。故呼则出。吸则入。天地之精气。其大数常出三入一。故谷不入。半日则气衰。一日则气少矣。', '2024-09-26T13:54:48.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'yUivbRN0OzS');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('aWfcLH2eFGi', 4, '{"title":"第20300591条・五味第五十六","description":"<p>3、黄帝曰。谷之五味。可得闻乎。伯高曰。请尽言之。五谷。糠米甘。麻酸。大豆咸。麦苦。黄黍辛。五果。枣甘。李酸。栗咸。杏苦。桃辛。五畜。牛甘。犬酸。猪咸。羊苦。鸡辛。五菜。葵甘。韭酸。藿咸。薤苦。葱辛。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300591,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '3、黄帝曰。谷之五味。可得闻乎。伯高曰。请尽言之。五谷。糠米甘。麻酸。大豆咸。麦苦。黄黍辛。五果。枣甘。李酸。栗咸。杏苦。桃辛。五畜。牛甘。犬酸。猪咸。羊苦。鸡辛。五菜。葵甘。韭酸。藿咸。薤苦。葱辛。', '2024-09-26T13:54:48.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'yUivbRN0OzS');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('MxMgNjVpRQ2', 4, '{"title":"第20300592条・五味第五十六","description":"<p>4、五色。黄色宜甘。青色宜酸。黑色宜咸。赤色宜苦。白色宜辛。凡此五者。各有所宜。五宜所言五色者。脾病者。宜食糠米饭。牛肉枣葵。心病者。宜食麦羊肉杏薤。肾病者。宜食大豆黄卷猪肉栗藿。肝病者。宜食麻犬肉李韭。肺病者。宜食黄黍鸡肉桃葱。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300592,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '4、五色。黄色宜甘。青色宜酸。黑色宜咸。赤色宜苦。白色宜辛。凡此五者。各有所宜。五宜所言五色者。脾病者。宜食糠米饭。牛肉枣葵。心病者。宜食麦羊肉杏薤。肾病者。宜食大豆黄卷猪肉栗藿。肝病者。宜食麻犬肉李韭。肺病者。宜食黄黍鸡肉桃葱。', '2024-09-26T13:54:48.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'yUivbRN0OzS');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('1zoiTP3T7EH', 4, '{"title":"第20300593条・五味第五十六","description":"<p>5、五禁。肝病禁辛。心病禁咸。脾病禁酸。肾病禁甘。肺病禁苦。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300593,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '5、五禁。肝病禁辛。心病禁咸。脾病禁酸。肾病禁甘。肺病禁苦。', '2024-09-26T13:54:48.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'yUivbRN0OzS');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('T9NHdDke3H5', 4, '{"title":"第20300594条・五味第五十六","description":"<p>6、肝色青。宜食甘。糠米饭。牛肉。枣。葵皆甘。心色赤。宜食酸。犬肉。麻。李。韭皆酸。脾黄色。宜食咸。大豆。猪肉。栗。藿皆咸。肺白色。宜食苦。麦。羊肉。杏。薤皆苦。肾色黑。宜食辛。黄黍。鸡肉。桃。葱皆辛。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300594,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '6、肝色青。宜食甘。糠米饭。牛肉。枣。葵皆甘。心色赤。宜食酸。犬肉。麻。李。韭皆酸。脾黄色。宜食咸。大豆。猪肉。栗。藿皆咸。肺白色。宜食苦。麦。羊肉。杏。薤皆苦。肾色黑。宜食辛。黄黍。鸡肉。桃。葱皆辛。', '2024-09-26T13:54:48.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'yUivbRN0OzS');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('PXFWgqE9bpN', 4, '{"title":"第20300595条・水胀第五十七","description":"<p>1、黄帝问于岐伯曰。水与肤胀。鼓胀。肠覃。石瘕。石水。何以别之。岐伯曰。水始起也。目窠上微肿。如新卧起之状。其颈脉动。时咳。阴股间寒。足胫肿。腹乃大。其水已成矣。以手按其腹。随手而起。如裹水之状。此其候也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300595,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '1、黄帝问于岐伯曰。水与肤胀。鼓胀。肠覃。石瘕。石水。何以别之。岐伯曰。水始起也。目窠上微肿。如新卧起之状。其颈脉动。时咳。阴股间寒。足胫肿。腹乃大。其水已成矣。以手按其腹。随手而起。如裹水之状。此其候也。', '2024-09-26T13:54:48.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'kZ0nYWDi4q7');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('4GycTdyziFD', 4, '{"title":"第20300596条・水胀第五十七","description":"<p>2、黄帝曰。肤胀何以候之。岐伯曰。肤胀者。寒气客于皮肤之间。冬冬然不坚。腹大。身尽肿。皮厚。按其腹。窅而不起。腹色不变。此其候也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300596,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '2、黄帝曰。肤胀何以候之。岐伯曰。肤胀者。寒气客于皮肤之间。冬冬然不坚。腹大。身尽肿。皮厚。按其腹。窅而不起。腹色不变。此其候也。', '2024-09-26T13:54:48.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'kZ0nYWDi4q7');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('0pQ9KAwGMfk', 4, '{"title":"第20300597条・水胀第五十七","description":"<p>3、鼓胀何如。岐伯曰。腹胀身皆大。大与肤胀等也。色苍黄。腹筋起。此其候也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300597,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '3、鼓胀何如。岐伯曰。腹胀身皆大。大与肤胀等也。色苍黄。腹筋起。此其候也。', '2024-09-26T13:54:48.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'kZ0nYWDi4q7');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('483bSG0qnx0', 4, '{"title":"第20300598条・水胀第五十七","description":"<p>4、肠覃何如。岐伯曰。寒气客于肠外。与卫气相搏。气不得荣。因有所系。癖而内着。恶气乃起。瘜肉乃生。其始生也。大如鸡卵。稍以益大。至其成。如怀子之状。久者离岁。按之则坚。推之则移。月事以时下。此其候也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300598,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '4、肠覃何如。岐伯曰。寒气客于肠外。与卫气相搏。气不得荣。因有所系。癖而内着。恶气乃起。瘜肉乃生。其始生也。大如鸡卵。稍以益大。至其成。如怀子之状。久者离岁。按之则坚。推之则移。月事以时下。此其候也。', '2024-09-26T13:54:48.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'kZ0nYWDi4q7');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('uKfhU8Dv6nQ', 4, '{"title":"第20300599条・水胀第五十七","description":"<p>5、石瘕何如。岐伯曰。石瘕生于胞中。寒气客于子门。子门闭塞。气不得通。恶血当泻不泻。衄以留止。日以益大。状如怀子。月事不以时下。皆生于女子。可导而下。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300599,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '5、石瘕何如。岐伯曰。石瘕生于胞中。寒气客于子门。子门闭塞。气不得通。恶血当泻不泻。衄以留止。日以益大。状如怀子。月事不以时下。皆生于女子。可导而下。', '2024-09-26T13:54:48.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'kZ0nYWDi4q7');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('v26QszmdiM6', 4, '{"title":"第20300600条・水胀第五十七","description":"<p>6、黄帝曰。肤胀鼓胀。可刺邪。岐伯曰。先泻其胀之血络。后调其经。刺去其血血络也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300600,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '6、黄帝曰。肤胀鼓胀。可刺邪。岐伯曰。先泻其胀之血络。后调其经。刺去其血血络也。', '2024-09-26T13:54:48.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'kZ0nYWDi4q7');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('BxYk63vOZ4R', 4, '{"title":"第20300601条・贼风第五十八","description":"<p>1、黄帝曰。夫子言贼风邪气伤人也。令人病焉。今有其不离屏蔽。不出室穴之中。卒然病者。非不离贼风邪气。其故何也。岐伯曰。此皆尝有所伤于湿气。藏于血脉之中。分肉之间。久留而不去。若有所堕坠。恶血在内而不去。卒然喜怒不节。饮食不适。寒温不时。腠理闭而不通。其开而遇风寒。则血气凝结。与故邪相袭。则为寒痹。其有热则汗出。汗出则受风。虽不遇贼风邪气。必有因加而发焉。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300601,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '1、黄帝曰。夫子言贼风邪气伤人也。令人病焉。今有其不离屏蔽。不出室穴之中。卒然病者。非不离贼风邪气。其故何也。岐伯曰。此皆尝有所伤于湿气。藏于血脉之中。分肉之间。久留而不去。若有所堕坠。恶血在内而不去。卒然喜怒不节。饮食不适。寒温不时。腠理闭而不通。其开而遇风寒。则血气凝结。与故邪相袭。则为寒痹。其有热则汗出。汗出则受风。虽不遇贼风邪气。必有因加而发焉。', '2024-09-26T13:54:48.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'd1KvQ72nftO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('fPypX11EMtv', 4, '{"title":"第20300602条・贼风第五十八","description":"<p>2、黄帝曰。今夫子之所言者。皆病人之所自知也。其毋所遇邪气。又毋怵惕之所志。卒然而病者。其故何也。唯有因鬼神之事乎。岐伯曰。此亦有故邪留而未发。因而志有所恶。及有所慕。血气内乱。两气相搏。其所从来者微。视之不见。听而不闻。故似鬼神。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300602,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '2、黄帝曰。今夫子之所言者。皆病人之所自知也。其毋所遇邪气。又毋怵惕之所志。卒然而病者。其故何也。唯有因鬼神之事乎。岐伯曰。此亦有故邪留而未发。因而志有所恶。及有所慕。血气内乱。两气相搏。其所从来者微。视之不见。听而不闻。故似鬼神。', '2024-09-26T13:54:48.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'd1KvQ72nftO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('X6UqqaQ3c5a', 4, '{"title":"第20300603条・贼风第五十八","description":"<p>3、黄帝曰。其祝而已者。其故何也。岐伯曰。先巫者。因知百病之胜。先知其病之所从生者。可祝而已也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300603,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '3、黄帝曰。其祝而已者。其故何也。岐伯曰。先巫者。因知百病之胜。先知其病之所从生者。可祝而已也。', '2024-09-26T13:54:48.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'd1KvQ72nftO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('MFi99rTKfKT', 4, '{"title":"第20300604条・卫气失常第五十九","description":"<p>1、黄帝曰。卫气之留于腹中。搐积不行。菀蕴不得常所。使人支胁胃中满。喘呼逆息者。何以去之。伯高曰。其气积于胸中者。上取之。积于腹中者。下取之。上下皆满者。旁取之。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300604,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '1、黄帝曰。卫气之留于腹中。搐积不行。菀蕴不得常所。使人支胁胃中满。喘呼逆息者。何以去之。伯高曰。其气积于胸中者。上取之。积于腹中者。下取之。上下皆满者。旁取之。', '2024-09-26T13:54:49.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'O2cb2ABJBgS');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('6DPBeP1Uj1b', 4, '{"title":"第20300605条・卫气失常第五十九","description":"<p>2、黄帝曰。取之奈何。伯高对曰。积于上。泻人迎。天突。喉中。积于下者。泻三里与气街。上下皆满者。上下取之。与季胁之下一寸。重者。鸡足取之。诊视其脉大而弦急。及绝不至者。及腹皮急甚者。不可刺也。黄帝曰。善。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300605,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '2、黄帝曰。取之奈何。伯高对曰。积于上。泻人迎。天突。喉中。积于下者。泻三里与气街。上下皆满者。上下取之。与季胁之下一寸。重者。鸡足取之。诊视其脉大而弦急。及绝不至者。及腹皮急甚者。不可刺也。黄帝曰。善。', '2024-09-26T13:54:49.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'O2cb2ABJBgS');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('l20yDQ2Po3H', 4, '{"title":"第20300606条・卫气失常第五十九","description":"<p>3、黄帝问于伯高曰。何以知皮肉气血筋骨之病也。伯高曰。色起两眉薄泽者。病在皮。唇色青黄赤白黑者。病在肌肉。营气濡然者。病在血气。目色青黄赤白黑者。病在筋。耳焦枯受尘垢。病在骨。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300606,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '3、黄帝问于伯高曰。何以知皮肉气血筋骨之病也。伯高曰。色起两眉薄泽者。病在皮。唇色青黄赤白黑者。病在肌肉。营气濡然者。病在血气。目色青黄赤白黑者。病在筋。耳焦枯受尘垢。病在骨。', '2024-09-26T13:54:49.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'O2cb2ABJBgS');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('7KXgkn0yTxB', 4, '{"title":"第20300607条・卫气失常第五十九","description":"<p>4、黄帝曰。病形何如。取之奈何。伯高曰。夫百病变化。不可胜数。然皮有部。肉有桂。血气有输。骨有属。黄帝曰。愿闻其故。伯高曰。皮之部。输于四末。肉之柱。有臂胫诸阳分肉之间。与足少阴分间。血气之输。输于诸络。气血留居。则盛而起。筋部无阴无阳。无左无右。候病所在。骨之属者。骨空之所以受益而益脑者也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300607,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '4、黄帝曰。病形何如。取之奈何。伯高曰。夫百病变化。不可胜数。然皮有部。肉有桂。血气有输。骨有属。黄帝曰。愿闻其故。伯高曰。皮之部。输于四末。肉之柱。有臂胫诸阳分肉之间。与足少阴分间。血气之输。输于诸络。气血留居。则盛而起。筋部无阴无阳。无左无右。候病所在。骨之属者。骨空之所以受益而益脑者也。', '2024-09-26T13:54:49.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'O2cb2ABJBgS');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('msSFN25Uhvz', 4, '{"title":"第20300608条・卫气失常第五十九","description":"<p>5、黄帝曰。取之奈何。伯高曰。夫病变化。浮沉深浅。不可胜究。各在其处。病间者浅之。甚者深之。间者小之。甚者众之。随变而调气。故曰上工。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300608,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '5、黄帝曰。取之奈何。伯高曰。夫病变化。浮沉深浅。不可胜究。各在其处。病间者浅之。甚者深之。间者小之。甚者众之。随变而调气。故曰上工。', '2024-09-26T13:54:49.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'O2cb2ABJBgS');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('KB1XEnSJbcE', 4, '{"title":"第20300609条・卫气失常第五十九","description":"<p>6、黄帝问于伯高曰。人之肥瘦大小温寒。有老壮少小。别之奈何。伯高对曰。人年五十已上为老。二十已上为壮。十八已上为少。六岁已上为小。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300609,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '6、黄帝问于伯高曰。人之肥瘦大小温寒。有老壮少小。别之奈何。伯高对曰。人年五十已上为老。二十已上为壮。十八已上为少。六岁已上为小。', '2024-09-26T13:54:49.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'O2cb2ABJBgS');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('QLBwufID0K5', 4, '{"title":"第20300610条・卫气失常第五十九","description":"<p>7、黄帝曰。何以度知其肥瘦。伯高曰。人有肥。有膏。有肉。黄帝曰。别此奈何。伯高曰。腘肉坚。皮满者。肥。腘肉不坚。皮缓者。膏。皮肉不相离者。肉。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300610,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '7、黄帝曰。何以度知其肥瘦。伯高曰。人有肥。有膏。有肉。黄帝曰。别此奈何。伯高曰。腘肉坚。皮满者。肥。腘肉不坚。皮缓者。膏。皮肉不相离者。肉。', '2024-09-26T13:54:49.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'O2cb2ABJBgS');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('0yOrcUqf73p', 4, '{"title":"第20300611条・卫气失常第五十九","description":"<p>8、黄帝曰。身之寒温何如。伯高。膏者。其肉淖而粗理者。身寒。细理者。身热。脂者。其肉坚。细理者热。粗理者寒。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300611,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '8、黄帝曰。身之寒温何如。伯高。膏者。其肉淖而粗理者。身寒。细理者。身热。脂者。其肉坚。细理者热。粗理者寒。', '2024-09-26T13:54:49.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'O2cb2ABJBgS');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ERzIfXk7jDz', 4, '{"title":"第20300612条・卫气失常第五十九","description":"<p>9、黄帝曰。其肥瘦大小奈何。伯高曰。膏者。多气而皮纵缓。故能纵腹垂腴。肉者。身体容大。脂者。其身收小。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300612,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '9、黄帝曰。其肥瘦大小奈何。伯高曰。膏者。多气而皮纵缓。故能纵腹垂腴。肉者。身体容大。脂者。其身收小。', '2024-09-26T13:54:49.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'O2cb2ABJBgS');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Dk4gvNmQuy3', 4, '{"title":"第20300613条・卫气失常第五十九","description":"<p>10、黄帝曰。三者之气血多少何如。伯高曰。膏者。多气。多气者。热。热者耐寒。肉者。多血则充形。充形则平。脂者。其血清。气滑少。故不能大。此别于众人者也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300613,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '10、黄帝曰。三者之气血多少何如。伯高曰。膏者。多气。多气者。热。热者耐寒。肉者。多血则充形。充形则平。脂者。其血清。气滑少。故不能大。此别于众人者也。', '2024-09-26T13:54:49.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'O2cb2ABJBgS');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('0eoC0kdcYff', 4, '{"title":"第20300614条・卫气失常第五十九","description":"<p>11、黄帝曰。众人奈何。伯高曰。众人皮肉脂膏。不能相加也。血与气。不能相多。故其形不小不大。各自称其身。命曰众人。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300614,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '11、黄帝曰。众人奈何。伯高曰。众人皮肉脂膏。不能相加也。血与气。不能相多。故其形不小不大。各自称其身。命曰众人。', '2024-09-26T13:54:49.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'O2cb2ABJBgS');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('NWaAF0cEUzb', 4, '{"title":"第20300615条・卫气失常第五十九","description":"<p>12、黄帝曰。善。治之奈何。伯高曰。必先别其三形。血之多少。气之清浊。而后调之。治无失常经。是故膏人纵腹垂腴。肉人者。上下容大。脂人者。虽脂不能大者。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300615,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '12、黄帝曰。善。治之奈何。伯高曰。必先别其三形。血之多少。气之清浊。而后调之。治无失常经。是故膏人纵腹垂腴。肉人者。上下容大。脂人者。虽脂不能大者。', '2024-09-26T13:54:49.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'O2cb2ABJBgS');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('05FuWtg0NyR', 4, '{"title":"第20300616条・玉版第六十","description":"<p>1、黄帝曰。余以小针为细物也。夫子乃言上合之于天。下合之于地。中合之于人。余以为过针之意矣。愿闻其故。岐伯曰。何物大于天乎。夫大于针者。惟五兵者焉。死之备也。非生之具。且夫人者。天地之镇也。其不可不参乎。夫治民者。亦唯针焉。夫针之与五兵。其孰小乎。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300616,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '1、黄帝曰。余以小针为细物也。夫子乃言上合之于天。下合之于地。中合之于人。余以为过针之意矣。愿闻其故。岐伯曰。何物大于天乎。夫大于针者。惟五兵者焉。死之备也。非生之具。且夫人者。天地之镇也。其不可不参乎。夫治民者。亦唯针焉。夫针之与五兵。其孰小乎。', '2024-09-26T13:54:49.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'POf1keTAw29');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('75XsrdhPGN1', 4, '{"title":"第20300617条・玉版第六十","description":"<p>2、黄帝曰。病之生时。有喜怒不测。饮食不节。阴气不足。阳气有余。营气不行。乃发为痈疽。阴阳不通。两热相搏。乃化为浓。小针能取之乎。岐伯曰。圣人不能使化者为之。邪不可留也。故两军相当。旗帜相望。白刃陈于中野者。此非一日之谋也。能使其民令行。禁止士卒无白刃之难者。非一日之教也。须臾之得也。夫至使身被痈疽之病。脓血之聚者。不亦离道远乎。夫痈疽之生。脓血之成也。不从天下。不从地出。积微之所生也。故圣人自治于未有形也。愚者遭其已成也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300617,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '2、黄帝曰。病之生时。有喜怒不测。饮食不节。阴气不足。阳气有余。营气不行。乃发为痈疽。阴阳不通。两热相搏。乃化为浓。小针能取之乎。岐伯曰。圣人不能使化者为之。邪不可留也。故两军相当。旗帜相望。白刃陈于中野者。此非一日之谋也。能使其民令行。禁止士卒无白刃之难者。非一日之教也。须臾之得也。夫至使身被痈疽之病。脓血之聚者。不亦离道远乎。夫痈疽之生。脓血之成也。不从天下。不从地出。积微之所生也。故圣人自治于未有形也。愚者遭其已成也。', '2024-09-26T13:54:49.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'POf1keTAw29');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('7cu0xZnb7UC', 4, '{"title":"第20300618条・玉版第六十","description":"<p>3、黄帝曰。其已形。不予遭。脓已成。不予见。为之奈何。岐伯曰。脓已成。十死一生。故圣人弗使已成。而明为良方。着之竹帛。使能者踵而传之后世。无有终时者。为其不予遭也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300618,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '3、黄帝曰。其已形。不予遭。脓已成。不予见。为之奈何。岐伯曰。脓已成。十死一生。故圣人弗使已成。而明为良方。着之竹帛。使能者踵而传之后世。无有终时者。为其不予遭也。', '2024-09-26T13:54:49.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'POf1keTAw29');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('qtj9cOu68YW', 4, '{"title":"第20300619条・玉版第六十","description":"<p>4、黄帝曰。其已有脓血而后遭乎。不导之以小针治乎。岐伯曰。以小治小者。其功小。以大治大者。多害。故其已成脓血者。其唯砭石铍锋之所取也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300619,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '4、黄帝曰。其已有脓血而后遭乎。不导之以小针治乎。岐伯曰。以小治小者。其功小。以大治大者。多害。故其已成脓血者。其唯砭石铍锋之所取也。', '2024-09-26T13:54:49.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'POf1keTAw29');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('NYw14VihzZU', 4, '{"title":"第20300620条・玉版第六十","description":"<p>5、黄帝曰。多害者其不可全乎。岐伯曰。其在逆顺焉。黄帝曰。愿闻逆顺。岐伯曰。以为伤者。其白眼青。黑眼小。是一逆也。内药而呕者。是二逆也。腹痛渴甚。是三逆也。肩项中不便。是四逆也。音嘶色脱。是五逆也。除此五者。为顺矣。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300620,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '5、黄帝曰。多害者其不可全乎。岐伯曰。其在逆顺焉。黄帝曰。愿闻逆顺。岐伯曰。以为伤者。其白眼青。黑眼小。是一逆也。内药而呕者。是二逆也。腹痛渴甚。是三逆也。肩项中不便。是四逆也。音嘶色脱。是五逆也。除此五者。为顺矣。', '2024-09-26T13:54:49.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'POf1keTAw29');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ZgTLIUso1Cf', 4, '{"title":"第20300621条・玉版第六十","description":"<p>6、黄帝曰。诸病皆有逆顺。可得闻乎。岐伯曰。腹胀。身热。脉大。是一逆也。腹鸣而满。四肢清泄。其脉大。是二逆也。衄而不止。脉大。是三逆也。咳而溲血脱形。其脉小劲。是四逆也。咳脱形。身热。脉小以疾。是谓五逆也。如是者。不过十五日而死矣。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300621,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '6、黄帝曰。诸病皆有逆顺。可得闻乎。岐伯曰。腹胀。身热。脉大。是一逆也。腹鸣而满。四肢清泄。其脉大。是二逆也。衄而不止。脉大。是三逆也。咳而溲血脱形。其脉小劲。是四逆也。咳脱形。身热。脉小以疾。是谓五逆也。如是者。不过十五日而死矣。', '2024-09-26T13:54:49.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'POf1keTAw29');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Ul06ec7T17h', 4, '{"title":"第20300622条・玉版第六十","description":"<p>7、其腹大胀。四末清。脱形。泄甚。是一逆也。腹胀便血。其脉大。时绝。是二逆也。咳溲血。形肉脱。脉搏。是三逆也。呕血。胸满引背。脉小而疾。是四逆也。咳呕。腹胀且飧泄。其脉绝。是五逆也。如是者。不及一时而死矣。工不察此者而刺之。是谓逆治。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300622,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '7、其腹大胀。四末清。脱形。泄甚。是一逆也。腹胀便血。其脉大。时绝。是二逆也。咳溲血。形肉脱。脉搏。是三逆也。呕血。胸满引背。脉小而疾。是四逆也。咳呕。腹胀且飧泄。其脉绝。是五逆也。如是者。不及一时而死矣。工不察此者而刺之。是谓逆治。', '2024-09-26T13:54:49.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'POf1keTAw29');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('NthmQxd7K0W', 4, '{"title":"第20300623条・玉版第六十","description":"<p>8、黄帝曰。夫子之言针甚骏。以配天地。上数天文。下度地纪。内别五藏。外次六府。经脉二十八会。尽有周纪。能杀生人。不能起死者。子能反之乎。岐伯曰。能杀生人。不能起死者也。黄帝曰。余闻之。则为不仁。然愿闻其道。弗行于人。岐伯曰。是明道也。其必然也。其如刀剑之可以杀人。如饮酒使人醉也。虽勿诊。犹可知矣。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300623,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '8、黄帝曰。夫子之言针甚骏。以配天地。上数天文。下度地纪。内别五藏。外次六府。经脉二十八会。尽有周纪。能杀生人。不能起死者。子能反之乎。岐伯曰。能杀生人。不能起死者也。黄帝曰。余闻之。则为不仁。然愿闻其道。弗行于人。岐伯曰。是明道也。其必然也。其如刀剑之可以杀人。如饮酒使人醉也。虽勿诊。犹可知矣。', '2024-09-26T13:54:49.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'POf1keTAw29');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('siIkHzhIT1u', 4, '{"title":"第20300624条・玉版第六十","description":"<p>9、黄帝曰。愿卒闻之。岐伯曰。人之所受气者。谷也。谷之所注者。胃也。胃者。水谷气血之海也。海之所行云气者。天下也。胃之所出气血者。经隧也。而隧者。五藏六府之大络也。迎而夺之而已矣。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300624,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '9、黄帝曰。愿卒闻之。岐伯曰。人之所受气者。谷也。谷之所注者。胃也。胃者。水谷气血之海也。海之所行云气者。天下也。胃之所出气血者。经隧也。而隧者。五藏六府之大络也。迎而夺之而已矣。', '2024-09-26T13:54:49.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'POf1keTAw29');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('LwiAIkpsDwK', 4, '{"title":"第20300625条・玉版第六十","description":"<p>10、黄帝曰。上下有数乎。岐伯曰。迎之五里。中道而止。五至而已。五往而藏之气尽矣。故五五二十五。而竭其输矣。此所谓夺其天气者也。非能绝其命而倾其寿者也。黄帝曰。愿卒闻之。岐伯曰。窥门而刺之者。死于家中。入门而刺之者。死于堂上。黄帝曰。善乎方。明哉道。请着之玉版。以为重宝。传之后世。以为刺禁。令民勿敢犯也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300625,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '10、黄帝曰。上下有数乎。岐伯曰。迎之五里。中道而止。五至而已。五往而藏之气尽矣。故五五二十五。而竭其输矣。此所谓夺其天气者也。非能绝其命而倾其寿者也。黄帝曰。愿卒闻之。岐伯曰。窥门而刺之者。死于家中。入门而刺之者。死于堂上。黄帝曰。善乎方。明哉道。请着之玉版。以为重宝。传之后世。以为刺禁。令民勿敢犯也。', '2024-09-26T13:54:49.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'POf1keTAw29');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('05uMlwq4wzB', 4, '{"title":"第20300626条・五禁第六十一","description":"<p>1、黄帝问于岐伯曰。余闻刺有五禁。何谓五禁。岐伯曰。禁其不可刺也。黄帝曰。余闻刺有五夺。岐伯曰。无泻其不可夺者也。黄帝曰。余闻刺有五过。岐伯曰。补泻无过其度。黄帝曰。余闻刺有五逆。岐伯曰。病与脉相逆。命曰五逆。黄帝曰。余闻刺有九宜。岐伯曰。明知九针之论。是谓九谊。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300626,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '1、黄帝问于岐伯曰。余闻刺有五禁。何谓五禁。岐伯曰。禁其不可刺也。黄帝曰。余闻刺有五夺。岐伯曰。无泻其不可夺者也。黄帝曰。余闻刺有五过。岐伯曰。补泻无过其度。黄帝曰。余闻刺有五逆。岐伯曰。病与脉相逆。命曰五逆。黄帝曰。余闻刺有九宜。岐伯曰。明知九针之论。是谓九谊。', '2024-09-26T13:54:49.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'qCDRQVoM33f');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('8ma9UoahBDt', 4, '{"title":"第20300627条・五禁第六十一","description":"<p>2、黄帝曰。何谓五禁。愿闻其不可刺之时。岐伯曰。甲乙日自乘。无刺实。无发蒙于耳内。丙丁日自乘。无振埃于肩喉廉泉。戊己日自乘四季。无刺腹。去爪泻水。庚辛日自乘。无刺关节于股膝。壬癸日自乘。无刺足胫。是谓五禁。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300627,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '2、黄帝曰。何谓五禁。愿闻其不可刺之时。岐伯曰。甲乙日自乘。无刺实。无发蒙于耳内。丙丁日自乘。无振埃于肩喉廉泉。戊己日自乘四季。无刺腹。去爪泻水。庚辛日自乘。无刺关节于股膝。壬癸日自乘。无刺足胫。是谓五禁。', '2024-09-26T13:54:49.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'qCDRQVoM33f');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('D1a1HWzfOF7', 4, '{"title":"第20300628条・五禁第六十一","description":"<p>3、黄帝曰。何谓五夺。岐伯曰。形肉已夺。是一夺也。大夺血之后。是二夺也。大汗出之后。是三夺也。大泄之后。是四夺也。新产及大血之后。是五夺也。此皆不可泻。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300628,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '3、黄帝曰。何谓五夺。岐伯曰。形肉已夺。是一夺也。大夺血之后。是二夺也。大汗出之后。是三夺也。大泄之后。是四夺也。新产及大血之后。是五夺也。此皆不可泻。', '2024-09-26T13:54:49.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'qCDRQVoM33f');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('VGlbnO4YVYC', 4, '{"title":"第20300629条・五禁第六十一","description":"<p>4、黄帝曰。何谓五逆。岐伯曰。热病脉静。汗已出。脉盛躁。是一逆也。病泄。脉洪大。是二逆也。着痹不移䐃肉破。身热。脉偏绝。是三逆也。淫而夺形。身热。色夭然白。乃后下血衄。血衄笃重。是谓四逆也。寒热夺形。脉坚搏。是谓五逆也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300629,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '4、黄帝曰。何谓五逆。岐伯曰。热病脉静。汗已出。脉盛躁。是一逆也。病泄。脉洪大。是二逆也。着痹不移䐃肉破。身热。脉偏绝。是三逆也。淫而夺形。身热。色夭然白。乃后下血衄。血衄笃重。是谓四逆也。寒热夺形。脉坚搏。是谓五逆也。', '2024-09-26T13:54:49.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'qCDRQVoM33f');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ML3nO6EUMDe', 4, '{"title":"第20300630条・动输第六十二","description":"<p>1、黄帝曰。经脉十二。而手太阴。足少阴。阳明。独动不休。何也。岐伯曰。是明胃脉也。胃为五藏六府之海。其清气上注于肺。肺气从太阴而行之。其行也。以息往来。故人一呼。脉再动。一吸脉亦再动。呼吸不已。故动而不止。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300630,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '1、黄帝曰。经脉十二。而手太阴。足少阴。阳明。独动不休。何也。岐伯曰。是明胃脉也。胃为五藏六府之海。其清气上注于肺。肺气从太阴而行之。其行也。以息往来。故人一呼。脉再动。一吸脉亦再动。呼吸不已。故动而不止。', '2024-09-26T13:54:49.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'air3NKEtyis');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('mRbiBSKMlfp', 4, '{"title":"第20300631条・动输第六十二","description":"<p>2、黄帝曰。气之过于寸口也。上十焉息。下八焉伏。何道从还。不知其极。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300631,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '2、黄帝曰。气之过于寸口也。上十焉息。下八焉伏。何道从还。不知其极。', '2024-09-26T13:54:49.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'air3NKEtyis');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('lOUbcN2mogL', 4, '{"title":"第20300632条・动输第六十二","description":"<p>3、岐伯曰。气之离藏也。卒然如弓弩之发。如水之下岸。上于鱼以及衰。其余气衰散以逆上。故其行微。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300632,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '3、岐伯曰。气之离藏也。卒然如弓弩之发。如水之下岸。上于鱼以及衰。其余气衰散以逆上。故其行微。', '2024-09-26T13:54:49.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'air3NKEtyis');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('gi6mxzgGX6h', 4, '{"title":"第20300633条・动输第六十二","description":"<p>4、黄帝曰。足之阳明。何因而动。岐伯曰。胃气上注于肺。其悍气上冲头者。循咽。上走空窍。循眼系。入络脑。出顑。下客主人。循牙车。合阳明。并下人迎。此胃气别走于阳明者也。故阴阳上下。其动也若一。故阳病而阳脉小者。为逆。阴病而阴脉大者。为逆。故阴阳俱静俱动。若引绳相倾者病。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300633,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '4、黄帝曰。足之阳明。何因而动。岐伯曰。胃气上注于肺。其悍气上冲头者。循咽。上走空窍。循眼系。入络脑。出顑。下客主人。循牙车。合阳明。并下人迎。此胃气别走于阳明者也。故阴阳上下。其动也若一。故阳病而阳脉小者。为逆。阴病而阴脉大者。为逆。故阴阳俱静俱动。若引绳相倾者病。', '2024-09-26T13:54:49.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'air3NKEtyis');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('DYPRH4EkcKU', 4, '{"title":"第20300634条・动输第六十二","description":"<p>5、黄帝曰。足少阴何因而动。岐伯曰。冲脉者。十二经之海也。与少阴之大络。起于肾下。出于气街。循阴股内廉。邪入腘中。循胫骨内廉。并少阴之经。下入内踝之后。入足下。其别者。邪入踝。出属附上。入大指之间。注诸络。以温足胫。此脉之常动者也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300634,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '5、黄帝曰。足少阴何因而动。岐伯曰。冲脉者。十二经之海也。与少阴之大络。起于肾下。出于气街。循阴股内廉。邪入腘中。循胫骨内廉。并少阴之经。下入内踝之后。入足下。其别者。邪入踝。出属附上。入大指之间。注诸络。以温足胫。此脉之常动者也。', '2024-09-26T13:54:49.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'air3NKEtyis');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('zFp1Pus4MWU', 4, '{"title":"第20300635条・动输第六十二","description":"<p>6、黄帝曰。营卫之行也。上下相贯。如环之无端。今有其卒然遇邪风。及逢大寒。手足懈惰。其脉阴阳之道。相输之会。行相失也。气何由还。岐伯曰。夫四末阴阳之会者。此气之尤络也。四街者。气之径路也。故络绝则径通。四末解则气从合。相输如环。黄帝曰。善。此所谓如环无端。莫知其纪。终而复始。此之谓也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300635,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '6、黄帝曰。营卫之行也。上下相贯。如环之无端。今有其卒然遇邪风。及逢大寒。手足懈惰。其脉阴阳之道。相输之会。行相失也。气何由还。岐伯曰。夫四末阴阳之会者。此气之尤络也。四街者。气之径路也。故络绝则径通。四末解则气从合。相输如环。黄帝曰。善。此所谓如环无端。莫知其纪。终而复始。此之谓也。', '2024-09-26T13:54:49.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'air3NKEtyis');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Oi2tl6YY3Ql', 4, '{"title":"第20300636条・五味论第六十三","description":"<p>1、黄帝问于少俞曰。五味入于口也。各有所走。各有所病。酸走筋。多食之。令人癃。咸走血。多食之。令人渴。辛走气。多食之。令人洞心。苦走骨。多食之。令人变呕。甘走肉。多食之。令人挽心。余知其然也。不知其何由。愿闻其故。少俞答曰。酸入于胃。其气涩以收。上之两焦。弗能出入也。不出即留于胃中。胃中和温。则下注膀胱。膀胱之胞薄以懦。得酸则缩绻。约而不通。水道不行。故癃。阴者。积筋之所终也。故酸入而走筋矣。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300636,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '1、黄帝问于少俞曰。五味入于口也。各有所走。各有所病。酸走筋。多食之。令人癃。咸走血。多食之。令人渴。辛走气。多食之。令人洞心。苦走骨。多食之。令人变呕。甘走肉。多食之。令人挽心。余知其然也。不知其何由。愿闻其故。少俞答曰。酸入于胃。其气涩以收。上之两焦。弗能出入也。不出即留于胃中。胃中和温。则下注膀胱。膀胱之胞薄以懦。得酸则缩绻。约而不通。水道不行。故癃。阴者。积筋之所终也。故酸入而走筋矣。', '2024-09-26T13:54:49.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'fMcNdtPH6tP');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('swGxHEeE0Ao', 4, '{"title":"第20300637条・五味论第六十三","description":"<p>2、黄帝曰。咸走血。多食之。令人渴。何也。少俞曰。咸入于胃。其气上走中焦。注于脉。则血气走之。血与咸相得。则凝。凝则胃中汁注之。注之则胃中竭。竭则咽路焦。故舌本干而善渴。血脉者。中焦之道也。故咸入而走血矣。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300637,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '2、黄帝曰。咸走血。多食之。令人渴。何也。少俞曰。咸入于胃。其气上走中焦。注于脉。则血气走之。血与咸相得。则凝。凝则胃中汁注之。注之则胃中竭。竭则咽路焦。故舌本干而善渴。血脉者。中焦之道也。故咸入而走血矣。', '2024-09-26T13:54:49.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'fMcNdtPH6tP');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('KO2i07thdUb', 4, '{"title":"第20300638条・五味论第六十三","description":"<p>3、黄帝曰。辛走气。多食之。令人洞心。何也。少俞曰。辛入于胃。其气走于上焦。上焦者。受气而营诸阳者也。姜韭之气熏之。营卫之气。不时受之。久留心下。故洞心。辛与气俱行。故辛入而与汗俱出。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300638,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '3、黄帝曰。辛走气。多食之。令人洞心。何也。少俞曰。辛入于胃。其气走于上焦。上焦者。受气而营诸阳者也。姜韭之气熏之。营卫之气。不时受之。久留心下。故洞心。辛与气俱行。故辛入而与汗俱出。', '2024-09-26T13:54:49.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'fMcNdtPH6tP');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('KPkK364BF2Z', 4, '{"title":"第20300639条・五味论第六十三","description":"<p>4、黄帝曰。「苦走骨。多食之。令人变呕。何也。」少俞曰。苦入于胃。五谷之气。皆不能胜苦。苦入下脘。三焦之道。皆闭而不通。故变呕。齿者。骨之所终也。故苦入而走骨。故入而复出。知其走骨也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300639,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '4、黄帝曰。「苦走骨。多食之。令人变呕。何也。」少俞曰。苦入于胃。五谷之气。皆不能胜苦。苦入下脘。三焦之道。皆闭而不通。故变呕。齿者。骨之所终也。故苦入而走骨。故入而复出。知其走骨也。', '2024-09-26T13:54:49.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'fMcNdtPH6tP');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('R2dsByrKRL7', 4, '{"title":"第20300640条・五味论第六十三","description":"<p>5、黄帝曰。甘走肉。多食之。令人悗心。何也。少俞曰。甘入于胃。其气弱小。不能上至于上焦。而与谷留于胃中者。令人柔润者也。胃柔则缓。缓则虫动。虫动则令人悗心。其气外通于肉。故甘走肉。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300640,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '5、黄帝曰。甘走肉。多食之。令人悗心。何也。少俞曰。甘入于胃。其气弱小。不能上至于上焦。而与谷留于胃中者。令人柔润者也。胃柔则缓。缓则虫动。虫动则令人悗心。其气外通于肉。故甘走肉。', '2024-09-26T13:54:49.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'fMcNdtPH6tP');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('CMgVKvM5htQ', 4, '{"title":"第20300641条・阴阳二十五人第六十四","description":"<p>1、黄帝曰。余闻阴阳之人何如。伯高曰。天地之间。六合之内。不离于五。人亦应之。故五五二十五人之政。而阴阳之人不与焉。其态又不合于众者五。余已知之矣。愿闻二十五人之形。血气之所生。别而以候。从外知内。何如。岐伯曰。「悉乎哉问也。此先师之秘也。虽伯高犹不能明之也。黄帝避席遵循而却曰。余闻之得其人弗教。是谓重失。得而泄之。天将厌之。余愿得而明之。金柜藏之。不敢扬之。岐伯曰。先立五形金木水火土。别其五色。异其五形之人。而二十五人具矣。黄帝曰。愿卒闻之。岐伯曰。慎之慎之。臣请言之。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300641,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '1、黄帝曰。余闻阴阳之人何如。伯高曰。天地之间。六合之内。不离于五。人亦应之。故五五二十五人之政。而阴阳之人不与焉。其态又不合于众者五。余已知之矣。愿闻二十五人之形。血气之所生。别而以候。从外知内。何如。岐伯曰。「悉乎哉问也。此先师之秘也。虽伯高犹不能明之也。黄帝避席遵循而却曰。余闻之得其人弗教。是谓重失。得而泄之。天将厌之。余愿得而明之。金柜藏之。不敢扬之。岐伯曰。先立五形金木水火土。别其五色。异其五形之人。而二十五人具矣。黄帝曰。愿卒闻之。岐伯曰。慎之慎之。臣请言之。', '2024-09-26T13:54:49.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'fWrQ74ZBxCD');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('9do2ULZh8kS', 4, '{"title":"第20300642条・阴阳二十五人第六十四","description":"<p>2、木形之人。比于上角似于苍帝。其为人苍色。小头。长面大肩背直身小。手足好。有才。劳心少力多忧。劳于事。能春夏不能秋冬感而病生。足厥阴。佗佗然。大角之人比于左足少阳。少阳之上遗遗然。左角之人比于右足少阳。少阳之下随随然。钛角之人。比于右足少阳。少阳之上推推然。判角之人比于左足少阳。少阳之下枯枯然。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300642,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '2、木形之人。比于上角似于苍帝。其为人苍色。小头。长面大肩背直身小。手足好。有才。劳心少力多忧。劳于事。能春夏不能秋冬感而病生。足厥阴。佗佗然。大角之人比于左足少阳。少阳之上遗遗然。左角之人比于右足少阳。少阳之下随随然。钛角之人。比于右足少阳。少阳之上推推然。判角之人比于左足少阳。少阳之下枯枯然。', '2024-09-26T13:54:49.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'fWrQ74ZBxCD');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('peB4uHbgjCo', 4, '{"title":"第20300643条・阴阳二十五人第六十四","description":"<p>3、火形之人。比于上征。似于赤帝。其为人赤色广䏖脱面小头。好肩背。髀腹小手足。行安地疾心。行摇肩背肉满。有气轻财少信多虑。见事明好颜。急心不寿暴死。能春夏不能秋冬。秋冬感而病生。手少阴核核然。质征之人。比于左手太阳。太阳之上。肌肌然。少征之人比于右手太阳。太阳之下慆慆然。右征之人比于右手太阳。太阳之上鲛鲛然。质判之人。比于左手太阳。太阳之下支支颐颐然。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300643,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '3、火形之人。比于上征。似于赤帝。其为人赤色广䏖脱面小头。好肩背。髀腹小手足。行安地疾心。行摇肩背肉满。有气轻财少信多虑。见事明好颜。急心不寿暴死。能春夏不能秋冬。秋冬感而病生。手少阴核核然。质征之人。比于左手太阳。太阳之上。肌肌然。少征之人比于右手太阳。太阳之下慆慆然。右征之人比于右手太阳。太阳之上鲛鲛然。质判之人。比于左手太阳。太阳之下支支颐颐然。', '2024-09-26T13:54:49.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'fWrQ74ZBxCD');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('hRXGqbj7OEP', 4, '{"title":"第20300644条・阴阳二十五人第六十四","description":"<p>4、土形之人。比于上宫。似于上古黄帝。其为人黄色圆面。大头。美肩背。大腹。美股胫。小手足。多肉。上下相称行安地。举足浮。安心。好利人不喜权势。善附人也。能秋冬不能春夏。春夏感而病生。足太阴。敦敦然。大宫之人比于左足阳明。阳明之上婉婉然。加宫之人。比于左足阳明。阳明之下坎坎然。少宫之人。比于右足阳明。阳明之上。枢枢然。左宫之人。比于右足阳明。阳明之下。兀兀然。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300644,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '4、土形之人。比于上宫。似于上古黄帝。其为人黄色圆面。大头。美肩背。大腹。美股胫。小手足。多肉。上下相称行安地。举足浮。安心。好利人不喜权势。善附人也。能秋冬不能春夏。春夏感而病生。足太阴。敦敦然。大宫之人比于左足阳明。阳明之上婉婉然。加宫之人。比于左足阳明。阳明之下坎坎然。少宫之人。比于右足阳明。阳明之上。枢枢然。左宫之人。比于右足阳明。阳明之下。兀兀然。', '2024-09-26T13:54:49.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'fWrQ74ZBxCD');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('kDJbmx7egLr', 4, '{"title":"第20300645条・阴阳二十五人第六十四","description":"<p>5、金形之人比于上商。似于白帝。其为人方面白色。小头。小肩背小腹。小手足如骨发踵外。骨轻。身清廉。急心静悍。善为吏。能秋冬。不能春夏。春夏感而病生。手太阴敦敦然。釱商之人比于左手阳明。阳明之上。廉廉然。右商之人。比于左手阳明。阳明之下脱脱然。左商之人比于右手阳明。阳明之上监监然。少商之人。比于右手阳明。阳明之下。严严然。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300645,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '5、金形之人比于上商。似于白帝。其为人方面白色。小头。小肩背小腹。小手足如骨发踵外。骨轻。身清廉。急心静悍。善为吏。能秋冬。不能春夏。春夏感而病生。手太阴敦敦然。釱商之人比于左手阳明。阳明之上。廉廉然。右商之人。比于左手阳明。阳明之下脱脱然。左商之人比于右手阳明。阳明之上监监然。少商之人。比于右手阳明。阳明之下。严严然。', '2024-09-26T13:54:49.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'fWrQ74ZBxCD');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('qsVXMlyNkwJ', 4, '{"title":"第20300646条・阴阳二十五人第六十四","description":"<p>6、水形之人。比于上羽。似于黑帝。其为人。黑色面不平。大头廉颐。小肩大腹动手足。发行摇身下尻长。背延延然。不敬畏善欺绍人。戮死。能秋冬不能春夏。春夏感而病生。足少阴汗汗然。大羽之人。比于右足太阳。太阳之上。颊颊然。少羽之人。比于左足太阳。太阳之下洁洁然。桎之为人。比于左足太阳。太阳之上安安然。是故五形之人二十五变者。众之所以相欺者是也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300646,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '6、水形之人。比于上羽。似于黑帝。其为人。黑色面不平。大头廉颐。小肩大腹动手足。发行摇身下尻长。背延延然。不敬畏善欺绍人。戮死。能秋冬不能春夏。春夏感而病生。足少阴汗汗然。大羽之人。比于右足太阳。太阳之上。颊颊然。少羽之人。比于左足太阳。太阳之下洁洁然。桎之为人。比于左足太阳。太阳之上安安然。是故五形之人二十五变者。众之所以相欺者是也。', '2024-09-26T13:54:49.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'fWrQ74ZBxCD');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('HMN4XjyrlYq', 4, '{"title":"第20300647条・阴阳二十五人第六十四","description":"<p>7、黄帝曰。得其形。不得其色何如。岐伯曰。形胜色。色胜形者。至其胜时年加。感则病行。失则忧矣。形色相得者。富贵大乐。黄帝曰。其形色相当胜之时。年加可知乎。岐伯曰。凡年忌下上之人。大忌常加七岁。十六岁。二十五岁。三十四岁。四十三岁。五十二岁。六十一岁皆人之大忌。不可不自安也。感则病行。失则忧矣。当此之时。无为奸事。是谓年忌。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300647,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '7、黄帝曰。得其形。不得其色何如。岐伯曰。形胜色。色胜形者。至其胜时年加。感则病行。失则忧矣。形色相得者。富贵大乐。黄帝曰。其形色相当胜之时。年加可知乎。岐伯曰。凡年忌下上之人。大忌常加七岁。十六岁。二十五岁。三十四岁。四十三岁。五十二岁。六十一岁皆人之大忌。不可不自安也。感则病行。失则忧矣。当此之时。无为奸事。是谓年忌。', '2024-09-26T13:54:49.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'fWrQ74ZBxCD');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('T36yn3Bo3Ov', 4, '{"title":"第20300648条・阴阳二十五人第六十四","description":"<p>8、黄帝曰。夫子之言脉之上下。血气之候似知形气。奈何。岐伯曰。足阳明之上血气盛则髯美长。血少气多则髯短。故气少血多则髯少。血气皆少则无髯。两吻多画。足阳明之下血气盛则下毛美长至胸。血多气少则下毛美短至脐。行则善高举足。足指少肉足善寒。血少气多则肉而善瘃。血气皆少则无毛有则稀。枯悴。善痿厥。足痹。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300648,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '8、黄帝曰。夫子之言脉之上下。血气之候似知形气。奈何。岐伯曰。足阳明之上血气盛则髯美长。血少气多则髯短。故气少血多则髯少。血气皆少则无髯。两吻多画。足阳明之下血气盛则下毛美长至胸。血多气少则下毛美短至脐。行则善高举足。足指少肉足善寒。血少气多则肉而善瘃。血气皆少则无毛有则稀。枯悴。善痿厥。足痹。', '2024-09-26T13:54:49.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'fWrQ74ZBxCD');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('wHE9EmFenWB', 4, '{"title":"第20300649条・阴阳二十五人第六十四","description":"<p>9、足少阳之上。气血盛则通髯美长。血多气少则通髯美短。血少气多则少髯。血气皆少则无须。感于寒湿则善痹。骨痛爪枯也。足少阳之下。血气盛则胫毛美长。外踝肥。血多气少则胫毛美短。外踝皮坚而厚。血少气多则胻毛少。外踝皮薄而软。血气皆少则无毛。外踝瘦无肉。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300649,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '9、足少阳之上。气血盛则通髯美长。血多气少则通髯美短。血少气多则少髯。血气皆少则无须。感于寒湿则善痹。骨痛爪枯也。足少阳之下。血气盛则胫毛美长。外踝肥。血多气少则胫毛美短。外踝皮坚而厚。血少气多则胻毛少。外踝皮薄而软。血气皆少则无毛。外踝瘦无肉。', '2024-09-26T13:54:49.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'fWrQ74ZBxCD');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('gOCftYalv3U', 4, '{"title":"第20300650条・阴阳二十五人第六十四","description":"<p>10、足太阳之上。血气盛则美眉。眉有毫毛血多气少则恶眉。面多少理。血少气多则面多肉。血气和则美色。足太阳之下。血气盛则肉满。踵坚。气少血多则瘦。跟空。血气皆少则善转筋。踵下痛。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300650,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '10、足太阳之上。血气盛则美眉。眉有毫毛血多气少则恶眉。面多少理。血少气多则面多肉。血气和则美色。足太阳之下。血气盛则肉满。踵坚。气少血多则瘦。跟空。血气皆少则善转筋。踵下痛。', '2024-09-26T13:54:49.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'fWrQ74ZBxCD');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('pVNLS2BVZuI', 4, '{"title":"第20300651条・阴阳二十五人第六十四","description":"<p>11、手阳明之上。血气盛则髭美。血少气多则髭恶。血气皆少则无髭。手阳明之下血气盛则腋下毛美。手鱼肉以温。气血皆少则手瘦以寒。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300651,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '11、手阳明之上。血气盛则髭美。血少气多则髭恶。血气皆少则无髭。手阳明之下血气盛则腋下毛美。手鱼肉以温。气血皆少则手瘦以寒。', '2024-09-26T13:54:49.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'fWrQ74ZBxCD');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('7U635PJFflr', 4, '{"title":"第20300652条・阴阳二十五人第六十四","description":"<p>12、手少阴之上。血气盛则眉美以长。耳色美。血气皆少则耳焦恶色。手少阳之下。血气盛则手卷多肉以温。血气皆少则寒以瘦。气少血多则瘦以多脉。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300652,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '12、手少阴之上。血气盛则眉美以长。耳色美。血气皆少则耳焦恶色。手少阳之下。血气盛则手卷多肉以温。血气皆少则寒以瘦。气少血多则瘦以多脉。', '2024-09-26T13:54:49.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'fWrQ74ZBxCD');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('MeQ0Dh8y83F', 4, '{"title":"第20300653条・阴阳二十五人第六十四","description":"<p>13、手太阳之上。血气盛则多须。面多肉以平。血气皆少则面瘦恶色。手太阳之下。血气盛则掌肉充满。血气皆少则掌瘦以寒。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300653,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '13、手太阳之上。血气盛则多须。面多肉以平。血气皆少则面瘦恶色。手太阳之下。血气盛则掌肉充满。血气皆少则掌瘦以寒。', '2024-09-26T13:54:49.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'fWrQ74ZBxCD');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('R5sXagQvVB0', 4, '{"title":"第20300654条・阴阳二十五人第六十四","description":"<p>14、黄帝曰。二十五人者。刺之有约乎。岐伯曰。美眉者。足太阳之脉。气血多。恶眉者。血气少。其肥而泽者。血气有余。肥而不泽者。气有余。血不足。瘦而无泽者。气血俱不足。审察其形气有余不足而调之。可以知逆顺矣。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300654,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '14、黄帝曰。二十五人者。刺之有约乎。岐伯曰。美眉者。足太阳之脉。气血多。恶眉者。血气少。其肥而泽者。血气有余。肥而不泽者。气有余。血不足。瘦而无泽者。气血俱不足。审察其形气有余不足而调之。可以知逆顺矣。', '2024-09-26T13:54:49.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'fWrQ74ZBxCD');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('vjYeGVWsmsh', 4, '{"title":"第20300655条・阴阳二十五人第六十四","description":"<p>15、黄帝曰。刺其诸阴阳奈何。岐伯曰。按其寸口人迎。以调阴阳。切循其经络之凝涩。结而不通者。此于身皆为痛痹。甚则不行。故凝涩。凝涩者。致气以温之血和乃止。其结络者。脉结血不和。决之乃行。故曰。气有余于上者。导而下之。气不足于上者。推而休之。其稽留不至者。因而迎之。必明于经隧。乃能持之。寒与热争者。导而行之。其宛陈血不结者。则而予之。必先明知二十五人则血气之所在。左右上下。刺约毕也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300655,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '15、黄帝曰。刺其诸阴阳奈何。岐伯曰。按其寸口人迎。以调阴阳。切循其经络之凝涩。结而不通者。此于身皆为痛痹。甚则不行。故凝涩。凝涩者。致气以温之血和乃止。其结络者。脉结血不和。决之乃行。故曰。气有余于上者。导而下之。气不足于上者。推而休之。其稽留不至者。因而迎之。必明于经隧。乃能持之。寒与热争者。导而行之。其宛陈血不结者。则而予之。必先明知二十五人则血气之所在。左右上下。刺约毕也。', '2024-09-26T13:54:49.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'fWrQ74ZBxCD');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('vIF3tXD7dLt', 4, '{"title":"第20300656条・五音五味第六十五","description":"<p>1、右征与少征。调右手太阳二。左商与左征。调左手阳明上。少征与大宫。调左手阳明上。右角与大角。调右手少阳下。大征与少征。调左手太阳上。众羽与少羽。调右足太阳下。少商与右商调右手太阳下。桎羽与众羽。调右足太阳下。少宫与大宫。调右足阳明下。判角与少角。调右足少阳下。釱商与上商。调右足阳明下。釱商与上角。调左足太阳下。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300656,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '1、右征与少征。调右手太阳二。左商与左征。调左手阳明上。少征与大宫。调左手阳明上。右角与大角。调右手少阳下。大征与少征。调左手太阳上。众羽与少羽。调右足太阳下。少商与右商调右手太阳下。桎羽与众羽。调右足太阳下。少宫与大宫。调右足阳明下。判角与少角。调右足少阳下。釱商与上商。调右足阳明下。釱商与上角。调左足太阳下。', '2024-09-26T13:54:49.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'vVu3dNrQWvO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('cTNN2EZhn2G', 4, '{"title":"第20300657条・五音五味第六十五","description":"<p>2、上征与右征同谷麦。畜羊。果杏。手少阴藏心。色赤味苦。时夏。上羽与大羽。同谷大豆。畜彘。果栗。足少阴藏肾。色黑味咸。时冬。上宫与大宫同谷稷。畜牛。果枣。足太阴藏脾。色黄味甘。时季夏。上商与右商同谷黍。畜鸡。果桃。手太阴藏肺。色白味辛。时秋。上角与大角。同谷麻。畜犬。果李。足厥阴藏肝。色青味酸。时春。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300657,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '2、上征与右征同谷麦。畜羊。果杏。手少阴藏心。色赤味苦。时夏。上羽与大羽。同谷大豆。畜彘。果栗。足少阴藏肾。色黑味咸。时冬。上宫与大宫同谷稷。畜牛。果枣。足太阴藏脾。色黄味甘。时季夏。上商与右商同谷黍。畜鸡。果桃。手太阴藏肺。色白味辛。时秋。上角与大角。同谷麻。畜犬。果李。足厥阴藏肝。色青味酸。时春。', '2024-09-26T13:54:49.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'vVu3dNrQWvO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('S4BEaby7JJF', 4, '{"title":"第20300658条・五音五味第六十五","description":"<p>3、大宫与上角。同右足阳明上。左角与大角。同左足阳明上。少羽与大羽同右足太阳下。左商与右商。同左手阳明上。加宫与大宫同左足少阳上。质判与大宫。同左手太阳下。判角与大角同左足少阳下。大羽与大角。同右足太阳上。大角与大宫同右足少阳上。右征。少征。质征。上征。判征。右角。釱角。上角。大角。判角。右商。少商。釱商。上商。左商。少宫。上宫。大宫。加宫。左角宫。众羽。桎羽。上羽。大羽。少羽。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300658,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '3、大宫与上角。同右足阳明上。左角与大角。同左足阳明上。少羽与大羽同右足太阳下。左商与右商。同左手阳明上。加宫与大宫同左足少阳上。质判与大宫。同左手太阳下。判角与大角同左足少阳下。大羽与大角。同右足太阳上。大角与大宫同右足少阳上。右征。少征。质征。上征。判征。右角。釱角。上角。大角。判角。右商。少商。釱商。上商。左商。少宫。上宫。大宫。加宫。左角宫。众羽。桎羽。上羽。大羽。少羽。', '2024-09-26T13:54:49.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'vVu3dNrQWvO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('4jwtkyyZhde', 4, '{"title":"第20300659条・五音五味第六十五","description":"<p>4、黄帝曰。妇人无须者。无血气乎。岐伯曰。冲脉任脉皆起于胞中。上循背里。为经络之海。其浮而外者。循腹右上行。会于咽喉。别而络唇口。血气盛则充肤热肉。血独盛者澹渗皮肤。生毫毛。今妇人之生有余于气。不足于血以其数脱血也。冲任之脉。不荣口唇。故须不生焉。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300659,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '4、黄帝曰。妇人无须者。无血气乎。岐伯曰。冲脉任脉皆起于胞中。上循背里。为经络之海。其浮而外者。循腹右上行。会于咽喉。别而络唇口。血气盛则充肤热肉。血独盛者澹渗皮肤。生毫毛。今妇人之生有余于气。不足于血以其数脱血也。冲任之脉。不荣口唇。故须不生焉。', '2024-09-26T13:54:49.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'vVu3dNrQWvO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('9kUJmE0Dkcd', 4, '{"title":"第20300660条・五音五味第六十五","description":"<p>5、黄帝曰。士人有伤于阴。阴气绝而不起。阴不用。然其须不去。其故何也。宦者独去何也。愿闻其故。岐伯曰。宦者去其宗筋。伤其冲脉。血泻不复。皮肤内结。唇口内荣故须不生。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300660,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '5、黄帝曰。士人有伤于阴。阴气绝而不起。阴不用。然其须不去。其故何也。宦者独去何也。愿闻其故。岐伯曰。宦者去其宗筋。伤其冲脉。血泻不复。皮肤内结。唇口内荣故须不生。', '2024-09-26T13:54:49.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'vVu3dNrQWvO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('nAieE26YF2C', 4, '{"title":"第20300661条・五音五味第六十五","description":"<p>6、黄帝曰。其有天宦者。未尝被伤。不脱于血。然其须不生其故何也。岐伯曰。此天之所不足也。其任冲不盛。宗筋不成。有气无血。唇口不荣。故须不生。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300661,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '6、黄帝曰。其有天宦者。未尝被伤。不脱于血。然其须不生其故何也。岐伯曰。此天之所不足也。其任冲不盛。宗筋不成。有气无血。唇口不荣。故须不生。', '2024-09-26T13:54:49.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'vVu3dNrQWvO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('6Q4ZnSGkNbi', 4, '{"title":"第20300662条・五音五味第六十五","description":"<p>7、黄帝曰。善乎哉。圣人之通万物也。若日月之光影。音声鼓响。闻其声而知其形。其非夫子。孰能明万物之精。是故圣人。视其颜色黄赤者。多热气。青白者少热气。黑色者多血少气。美眉者。太阳多血。通髯极须者。少阳多血。美须者阳明多血。此其时然也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300662,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '7、黄帝曰。善乎哉。圣人之通万物也。若日月之光影。音声鼓响。闻其声而知其形。其非夫子。孰能明万物之精。是故圣人。视其颜色黄赤者。多热气。青白者少热气。黑色者多血少气。美眉者。太阳多血。通髯极须者。少阳多血。美须者阳明多血。此其时然也。', '2024-09-26T13:54:49.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'vVu3dNrQWvO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('8U6YpgQyjhs', 4, '{"title":"第20300663条・五音五味第六十五","description":"<p>8、夫人之常数。太阳常多血少气。少阳常多气少血。阳明常多血多气。厥阴常多气少血。少阴常多血少气。太阴常多血少气。此天之常数也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300663,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '8、夫人之常数。太阳常多血少气。少阳常多气少血。阳明常多血多气。厥阴常多气少血。少阴常多血少气。太阴常多血少气。此天之常数也。', '2024-09-26T13:54:49.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'vVu3dNrQWvO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('IulUvUUZD7J', 4, '{"title":"第20300664条・百病始生第六十六","description":"<p>1、黄帝问于岐伯曰。夫百病之始生也。皆于风雨寒暑。清湿喜怒。喜怒不节则伤藏。风雨则伤上。清湿则伤下。三部之气所伤异类。愿闻其会。岐伯曰。三部之气各不同或起于阴或起于阳请言其方。喜怒不节则伤藏。藏伤则病起于阴也。清湿袭虚。则病起于下。风雨袭虚。则病起于上。是谓三部。至于其淫泆。不可胜数。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300664,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '1、黄帝问于岐伯曰。夫百病之始生也。皆于风雨寒暑。清湿喜怒。喜怒不节则伤藏。风雨则伤上。清湿则伤下。三部之气所伤异类。愿闻其会。岐伯曰。三部之气各不同或起于阴或起于阳请言其方。喜怒不节则伤藏。藏伤则病起于阴也。清湿袭虚。则病起于下。风雨袭虚。则病起于上。是谓三部。至于其淫泆。不可胜数。', '2024-09-26T13:54:49.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'D15tdisxnXI');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('JRW2HcHQ3i1', 4, '{"title":"第20300665条・百病始生第六十六","description":"<p>2、黄帝曰。余固不能数。故问先师愿卒闻其道。岐伯曰。风雨寒热不得虚。邪不能独伤人。卒然逢疾风暴雨而不病者。盖无虚。故邪不能独伤人。此必因虚邪之风。与其身形。两虚相得。乃客其形。两实相逢。众人肉坚。其中于虚邪也因于天时。与其身形。参以虚实。大病乃成。气有定舍。因处为名。上下中外。分为三员。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300665,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '2、黄帝曰。余固不能数。故问先师愿卒闻其道。岐伯曰。风雨寒热不得虚。邪不能独伤人。卒然逢疾风暴雨而不病者。盖无虚。故邪不能独伤人。此必因虚邪之风。与其身形。两虚相得。乃客其形。两实相逢。众人肉坚。其中于虚邪也因于天时。与其身形。参以虚实。大病乃成。气有定舍。因处为名。上下中外。分为三员。', '2024-09-26T13:54:49.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'D15tdisxnXI');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Y7HGXX7UfzW', 4, '{"title":"第20300666条・百病始生第六十六","description":"<p>3、是故虚邪之中人也。始于皮肤。皮肤缓则腠理开。开则邪从毛发入。入则抵深。深则毛发立。毛发立则淅然。故皮肤痛。留而不去。则传舍于络脉。在络之时。痛于肌肉。故痛之时息。大经代去。留而不去。传舍于经。在经之时。洒淅喜惊。留而不去。传舍于俞。在俞之时。六经不通四肢。则肢节痛。腰脊乃强。留而不去。传舍于伏冲之脉。在伏冲之时体重身痛。留而不去。传舍于肠胃。在肠肾之时。贲响腹胀。多寒则肠鸣飧泄。食不化。多热则溏出糜。留而不去。传舍于肠胃之外。募原之间。留着于脉。稽留而不去。息而成积。或着孙脉。或着络脉。或着经脉。或着俞脉。或着于伏冲之脉。或着于膂筋。或着于肠胃之募原。上连于缓筋。邪气淫泆。不可胜论。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300666,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '3、是故虚邪之中人也。始于皮肤。皮肤缓则腠理开。开则邪从毛发入。入则抵深。深则毛发立。毛发立则淅然。故皮肤痛。留而不去。则传舍于络脉。在络之时。痛于肌肉。故痛之时息。大经代去。留而不去。传舍于经。在经之时。洒淅喜惊。留而不去。传舍于俞。在俞之时。六经不通四肢。则肢节痛。腰脊乃强。留而不去。传舍于伏冲之脉。在伏冲之时体重身痛。留而不去。传舍于肠胃。在肠肾之时。贲响腹胀。多寒则肠鸣飧泄。食不化。多热则溏出糜。留而不去。传舍于肠胃之外。募原之间。留着于脉。稽留而不去。息而成积。或着孙脉。或着络脉。或着经脉。或着俞脉。或着于伏冲之脉。或着于膂筋。或着于肠胃之募原。上连于缓筋。邪气淫泆。不可胜论。', '2024-09-26T13:54:49.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'D15tdisxnXI');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Nf9FkSv76GN', 4, '{"title":"第20300667条・百病始生第六十六","description":"<p>4、黄帝曰。愿尽闻其所由然。岐伯曰。其着孙络之脉而成积者。其积往来上下。臂小孙络之居也。浮而缓。不能句积而止之。故往来移行肠胃之间。水凑渗注灌。濯濯有音。有寒则䐜。䐜满雷引。故时切痛。其着于阳明之经则挟脐而居。饱食则益大。饥则益小。其着于缓筋也。似阳明之积。饱食则痛。饥则安。其着于肠胃之募原也。痛而外连于缓筋。饱食则安。饥则痛。其着于伏冲之脉者。揣之应手而动。发手则热气下于两股。如汤沃之状。其着于膂筋。在肠后者饥则积见。饱则积不见。按之不得。其着于输之脉者。闭塞不通。津液不下。孔窍干壅。此邪气之从外入内。从上下也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300667,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '4、黄帝曰。愿尽闻其所由然。岐伯曰。其着孙络之脉而成积者。其积往来上下。臂小孙络之居也。浮而缓。不能句积而止之。故往来移行肠胃之间。水凑渗注灌。濯濯有音。有寒则䐜。䐜满雷引。故时切痛。其着于阳明之经则挟脐而居。饱食则益大。饥则益小。其着于缓筋也。似阳明之积。饱食则痛。饥则安。其着于肠胃之募原也。痛而外连于缓筋。饱食则安。饥则痛。其着于伏冲之脉者。揣之应手而动。发手则热气下于两股。如汤沃之状。其着于膂筋。在肠后者饥则积见。饱则积不见。按之不得。其着于输之脉者。闭塞不通。津液不下。孔窍干壅。此邪气之从外入内。从上下也。', '2024-09-26T13:54:49.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'D15tdisxnXI');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('oQ6OJdKJH1Y', 4, '{"title":"第20300668条・百病始生第六十六","description":"<p>5、黄帝曰。积之始生。至其已成。奈何。岐伯曰。积之始生。得寒乃生。厥乃成积也。黄帝曰。其成积奈何。岐伯曰。厥气生足悗。悗生胫寒。胫寒则血脉凝涩。血脉凝涩则寒气上入于肠胃。入于肠胃则䐜胀。䐜胀则肠外之汁沫迫聚不得散。日以成积。卒然多食饮。则肠满。起居不节。用力过度。则络脉伤。阳络伤则血外溢。血外溢则衄血。阴络伤则血内溢。血内溢则后血。肠胃之络伤则血溢于肠外。肠外有寒。汁沫与血相搏。则并合凝聚不得散。而积成矣。卒然中外于寒。若内伤于忧怒。则气上逆。气上逆则六俞不通。温气不行。凝血蕴里而不散。津液涩渗。着而不去。而积皆成矣。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300668,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '5、黄帝曰。积之始生。至其已成。奈何。岐伯曰。积之始生。得寒乃生。厥乃成积也。黄帝曰。其成积奈何。岐伯曰。厥气生足悗。悗生胫寒。胫寒则血脉凝涩。血脉凝涩则寒气上入于肠胃。入于肠胃则䐜胀。䐜胀则肠外之汁沫迫聚不得散。日以成积。卒然多食饮。则肠满。起居不节。用力过度。则络脉伤。阳络伤则血外溢。血外溢则衄血。阴络伤则血内溢。血内溢则后血。肠胃之络伤则血溢于肠外。肠外有寒。汁沫与血相搏。则并合凝聚不得散。而积成矣。卒然中外于寒。若内伤于忧怒。则气上逆。气上逆则六俞不通。温气不行。凝血蕴里而不散。津液涩渗。着而不去。而积皆成矣。', '2024-09-26T13:54:49.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'D15tdisxnXI');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('0aCgcHjOZvK', 4, '{"title":"第20300669条・百病始生第六十六","description":"<p>6、黄帝曰。其生于阴者。奈何。岐伯曰。忧思伤心。重寒伤肺。忿怒伤肝。醉以入房。汗出当风伤脾。用力过度。若入房汗出浴。则伤肾。此内外三部之所生病者也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300669,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '6、黄帝曰。其生于阴者。奈何。岐伯曰。忧思伤心。重寒伤肺。忿怒伤肝。醉以入房。汗出当风伤脾。用力过度。若入房汗出浴。则伤肾。此内外三部之所生病者也。', '2024-09-26T13:54:49.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'D15tdisxnXI');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('29PZHV6iis0', 4, '{"title":"第20300670条・百病始生第六十六","description":"<p>7、黄帝曰。善治之奈何。岐伯答曰。察其所痛。以知其应。有余不足。当补则补。当泻则泻。毋逆天时。是谓至治。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300670,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '7、黄帝曰。善治之奈何。岐伯答曰。察其所痛。以知其应。有余不足。当补则补。当泻则泻。毋逆天时。是谓至治。', '2024-09-26T13:54:49.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'D15tdisxnXI');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('IHRWlTSp0g5', 4, '{"title":"第20300671条・行针第六十七","description":"<p>1、黄帝问于岐伯曰。余闻九针于夫子。而行之于百姓。百姓之血气。各不同形。或神动而气先针行。或气与针相逢。或针已出。气独行。或数刺乃知。或发针而气逆。或数刺病益剧。凡此六者。各不同形。愿闻其方。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300671,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '1、黄帝问于岐伯曰。余闻九针于夫子。而行之于百姓。百姓之血气。各不同形。或神动而气先针行。或气与针相逢。或针已出。气独行。或数刺乃知。或发针而气逆。或数刺病益剧。凡此六者。各不同形。愿闻其方。', '2024-09-26T13:54:49.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'EpAabzdL0zT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('sFOPD2UrpNx', 4, '{"title":"第20300672条・行针第六十七","description":"<p>2、岐伯曰。重阳之人。其神易动。其气易往也。黄帝曰。何谓重阳之人。岐伯曰。重阳之人。熇熇高高。言语善疾。举足善高。心肺之藏气有余。阳气滑盛而扬。故神动而气先行。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300672,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '2、岐伯曰。重阳之人。其神易动。其气易往也。黄帝曰。何谓重阳之人。岐伯曰。重阳之人。熇熇高高。言语善疾。举足善高。心肺之藏气有余。阳气滑盛而扬。故神动而气先行。', '2024-09-26T13:54:49.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'EpAabzdL0zT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('u0T1XotcZUq', 4, '{"title":"第20300673条・行针第六十七","description":"<p>3、黄帝曰。重阳之人而神不先行者。何也。岐伯曰。此人颇有阴者也。黄帝曰。何以知其颇有阴者也。岐伯曰。多阳者。多喜。多阴者。多怒。数怒者。易解。故曰颇有阴。其阴阳之离合难。故其神不能先行也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300673,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '3、黄帝曰。重阳之人而神不先行者。何也。岐伯曰。此人颇有阴者也。黄帝曰。何以知其颇有阴者也。岐伯曰。多阳者。多喜。多阴者。多怒。数怒者。易解。故曰颇有阴。其阴阳之离合难。故其神不能先行也。', '2024-09-26T13:54:49.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'EpAabzdL0zT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('t33d2Wxq1Hw', 4, '{"title":"第20300674条・行针第六十七","description":"<p>4、黄帝曰。其气与针相逢。奈何。岐伯曰。阴阳和调。而血气淖泽滑利。故针入而气出。疾而相逢也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300674,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '4、黄帝曰。其气与针相逢。奈何。岐伯曰。阴阳和调。而血气淖泽滑利。故针入而气出。疾而相逢也。', '2024-09-26T13:54:49.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'EpAabzdL0zT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('IYrhwLnKQN0', 4, '{"title":"第20300675条・行针第六十七","description":"<p>5、黄帝曰。针已出而气独行者。何气使然。岐伯曰。其阴气多而阳气少。阴气沉而阳气浮者内藏。故针已出。气乃随其后。故独行也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300675,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '5、黄帝曰。针已出而气独行者。何气使然。岐伯曰。其阴气多而阳气少。阴气沉而阳气浮者内藏。故针已出。气乃随其后。故独行也。', '2024-09-26T13:54:49.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'EpAabzdL0zT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('r6oZH9Eb4vv', 4, '{"title":"第20300676条・行针第六十七","description":"<p>6、黄帝曰。数刺乃知。何气使然。岐伯曰。此人之多阴而少阳。其气沉而气往难。故数刺乃知也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300676,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '6、黄帝曰。数刺乃知。何气使然。岐伯曰。此人之多阴而少阳。其气沉而气往难。故数刺乃知也。', '2024-09-26T13:54:49.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'EpAabzdL0zT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('I1pznZqSf5G', 4, '{"title":"第20300677条・行针第六十七","description":"<p>7、黄帝曰。针入而气逆者。何气使然。岐伯曰。其气逆与其数刺病益甚者。非阴阳之气。浮沉之势也。此皆粗之所败。工之所失。其形气无过焉。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300677,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '7、黄帝曰。针入而气逆者。何气使然。岐伯曰。其气逆与其数刺病益甚者。非阴阳之气。浮沉之势也。此皆粗之所败。工之所失。其形气无过焉。', '2024-09-26T13:54:49.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'EpAabzdL0zT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('HXjDjEnQZq1', 4, '{"title":"第20300678条・上膈第六十八","description":"<p>1、黄帝曰。气为上膈者。食饮入而还出。余已知之矣。虫为下膈。下膈者。食焠时乃出。余未得其意。愿卒闻之。岐伯曰。喜怒不适。食饮不节。寒温不时。则寒汁流于肠中。流于肠中则虫寒。虫寒则积聚。守于下管。则肠胃充郭。卫气不营。邪气居之。人食则虫上食。虫上食则下管虚。下管虚则邪气胜之。积聚以留。留则痈成。痈成则下管约。其痈在管内者。即而痛深。其痈在外者。则痈外而痛浮。痈上皮热。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300678,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '1、黄帝曰。气为上膈者。食饮入而还出。余已知之矣。虫为下膈。下膈者。食焠时乃出。余未得其意。愿卒闻之。岐伯曰。喜怒不适。食饮不节。寒温不时。则寒汁流于肠中。流于肠中则虫寒。虫寒则积聚。守于下管。则肠胃充郭。卫气不营。邪气居之。人食则虫上食。虫上食则下管虚。下管虚则邪气胜之。积聚以留。留则痈成。痈成则下管约。其痈在管内者。即而痛深。其痈在外者。则痈外而痛浮。痈上皮热。', '2024-09-26T13:54:49.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'm5QFGn5TUOd');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('b3QWhMc0GUL', 4, '{"title":"第20300679条・上膈第六十八","description":"<p>2、黄帝曰。刺之奈何。岐伯曰。微按其痈。视气所行。先浅刺其傍。稍内益深。逐而刺之。毋过三行。察其沈浮。以为深浅。已刺必熨。令热入中。日使热内。邪气益衰。大痈乃溃。伍以参禁。以除其内。恬憺无为。乃能行气。后以咸苦。化谷乃下矣。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300679,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '2、黄帝曰。刺之奈何。岐伯曰。微按其痈。视气所行。先浅刺其傍。稍内益深。逐而刺之。毋过三行。察其沈浮。以为深浅。已刺必熨。令热入中。日使热内。邪气益衰。大痈乃溃。伍以参禁。以除其内。恬憺无为。乃能行气。后以咸苦。化谷乃下矣。', '2024-09-26T13:54:49.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'm5QFGn5TUOd');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('eYKi8HGTLTR', 4, '{"title":"第20300680条・忧恚无言第六十九","description":"<p>1、黄帝问于少师曰。人之卒然忧恚。而言无音者。何道之塞。何气出行。使音不彰。愿闻其方。少师答曰。咽喉者。水谷之道也。喉咙者。气之所以上下者也。会厌者。声音之户也。口唇者。声音之扇也。舌者。声音之机也。悬壅垂者。声音之关者。颃颡者。分气之所泄也。横骨者。神气所使主发舌者也。故人之鼻洞涕出不收者。颃颡不开。分气失也。是故厌小而疾薄。则发气疾。其开阖利。其出气易。其厌大而厚。则开阖难。其气出迟。故重言也。人卒然无音者。寒气客于厌。则厌不能发。发不能下。至其开阖不致。故无音。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300680,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '1、黄帝问于少师曰。人之卒然忧恚。而言无音者。何道之塞。何气出行。使音不彰。愿闻其方。少师答曰。咽喉者。水谷之道也。喉咙者。气之所以上下者也。会厌者。声音之户也。口唇者。声音之扇也。舌者。声音之机也。悬壅垂者。声音之关者。颃颡者。分气之所泄也。横骨者。神气所使主发舌者也。故人之鼻洞涕出不收者。颃颡不开。分气失也。是故厌小而疾薄。则发气疾。其开阖利。其出气易。其厌大而厚。则开阖难。其气出迟。故重言也。人卒然无音者。寒气客于厌。则厌不能发。发不能下。至其开阖不致。故无音。', '2024-09-26T13:54:49.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'T2YZ6M2cufG');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('udOG473KS2o', 4, '{"title":"第20300681条・忧恚无言第六十九","description":"<p>2、黄帝曰。刺之奈何。岐伯曰。足之少阴。上系于舌。络于横骨。终于会厌。两泻其血脉。浊气乃避。会厌之脉。上络任脉。取之天突。其厌乃发也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300681,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '2、黄帝曰。刺之奈何。岐伯曰。足之少阴。上系于舌。络于横骨。终于会厌。两泻其血脉。浊气乃避。会厌之脉。上络任脉。取之天突。其厌乃发也。', '2024-09-26T13:54:49.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'T2YZ6M2cufG');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ORVE3sUjWvL', 4, '{"title":"第20300682条・寒热第七十","description":"<p>1、黄帝问于岐伯曰。寒热瘰疬在于颈腋者。皆何气使生。岐伯曰。此皆鼠瘘寒热之毒气也。留于脉而不去者也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300682,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '1、黄帝问于岐伯曰。寒热瘰疬在于颈腋者。皆何气使生。岐伯曰。此皆鼠瘘寒热之毒气也。留于脉而不去者也。', '2024-09-26T13:54:49.000Z', 1, NULL, 'ghBqURJwurj', 'section', '6X6qcwJCv4q');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('NsG3W0yavWN', 4, '{"title":"第20300683条・寒热第七十","description":"<p>2、黄帝曰。去之奈何。岐伯曰。鼠瘘之本。皆在于藏。其末上出于颈腋之间。其浮于脉中。而未内着于肌肉。而外为脓血者。易去也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300683,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '2、黄帝曰。去之奈何。岐伯曰。鼠瘘之本。皆在于藏。其末上出于颈腋之间。其浮于脉中。而未内着于肌肉。而外为脓血者。易去也。', '2024-09-26T13:54:49.000Z', 1, NULL, 'ghBqURJwurj', 'section', '6X6qcwJCv4q');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('MuRflmUGjWC', 4, '{"title":"第20300684条・寒热第七十","description":"<p>3、黄帝曰。去之奈何。岐伯曰。请从其本引其末。可使衰去。而绝其寒热。审按其道以予之。徐往徐来以去之。其小如麦者。一刺知。三刺而已。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300684,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '3、黄帝曰。去之奈何。岐伯曰。请从其本引其末。可使衰去。而绝其寒热。审按其道以予之。徐往徐来以去之。其小如麦者。一刺知。三刺而已。', '2024-09-26T13:54:49.000Z', 1, NULL, 'ghBqURJwurj', 'section', '6X6qcwJCv4q');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('9P9TlefUXY8', 4, '{"title":"第20300685条・寒热第七十","description":"<p>4、黄帝曰。决其生死奈何。岐伯曰。反其目视之。其中有赤脉。上下贯瞳子。见一脉。一岁死。见一脉半。一岁半死。见二脉。二岁死。见二脉半。二岁半死。见三脉。三岁而死。见赤脉不下贯瞳子。可治也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300685,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '4、黄帝曰。决其生死奈何。岐伯曰。反其目视之。其中有赤脉。上下贯瞳子。见一脉。一岁死。见一脉半。一岁半死。见二脉。二岁死。见二脉半。二岁半死。见三脉。三岁而死。见赤脉不下贯瞳子。可治也。', '2024-09-26T13:54:49.000Z', 1, NULL, 'ghBqURJwurj', 'section', '6X6qcwJCv4q');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('t6fZh73RTzs', 4, '{"title":"第20300686条・邪客第七十一","description":"<p>1、黄帝问于伯高曰。夫邪气之客人也。或令人目不瞑不卧出者。何气使然。伯高曰。五谷入于胃也。其糟粕津液宗气。分为三隧。故宗气积于胸中。出于喉咙。以贯心脉。而行呼吸焉。营气者。泌其津液。注之于脉。化以为血。以荣四末。内注五藏六府。以应刻数焉。卫气者。出其悍气之慓疾。而先行于四末分肉皮肤之间。而不休者也。昼日行于阳。夜行于阴。常从足少阴之分间。行五藏六府。今厥气客于五藏六府。则卫气独卫其外。行于阳。不得入于阴。行于阳则阳气盛。阳气盛则阳桥陷。不得入于阴。阴虚。故目不瞑。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300686,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '1、黄帝问于伯高曰。夫邪气之客人也。或令人目不瞑不卧出者。何气使然。伯高曰。五谷入于胃也。其糟粕津液宗气。分为三隧。故宗气积于胸中。出于喉咙。以贯心脉。而行呼吸焉。营气者。泌其津液。注之于脉。化以为血。以荣四末。内注五藏六府。以应刻数焉。卫气者。出其悍气之慓疾。而先行于四末分肉皮肤之间。而不休者也。昼日行于阳。夜行于阴。常从足少阴之分间。行五藏六府。今厥气客于五藏六府。则卫气独卫其外。行于阳。不得入于阴。行于阳则阳气盛。阳气盛则阳桥陷。不得入于阴。阴虚。故目不瞑。', '2024-09-26T13:54:49.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'btXQ0MChVuV');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('cd1Y2PipzTS', 4, '{"title":"第20300687条・邪客第七十一","description":"<p>2、黄帝曰。善。治之奈何。伯高曰。补其不足。泻其有余。调其虚实。以通其道。而去其邪。饮以半夏汤一剂。阴阳已通。其卧立至。黄帝曰。善。此所谓决渎壅塞。经络大通。阴阳和得者也。愿闻其方。伯高曰。其汤方以流水千里以外者八升。扬之万遍。取其清五升。煮之。炊以苇薪火。沸置秫米一升。治半夏五合。徐炊。令竭为一升半。去其滓。饮汁一小杯。日三稍益。以知为度。故其病新发者。复杯则卧。汗出则已矣。久者。三饮而已也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300687,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '2、黄帝曰。善。治之奈何。伯高曰。补其不足。泻其有余。调其虚实。以通其道。而去其邪。饮以半夏汤一剂。阴阳已通。其卧立至。黄帝曰。善。此所谓决渎壅塞。经络大通。阴阳和得者也。愿闻其方。伯高曰。其汤方以流水千里以外者八升。扬之万遍。取其清五升。煮之。炊以苇薪火。沸置秫米一升。治半夏五合。徐炊。令竭为一升半。去其滓。饮汁一小杯。日三稍益。以知为度。故其病新发者。复杯则卧。汗出则已矣。久者。三饮而已也。', '2024-09-26T13:54:49.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'btXQ0MChVuV');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('PLz80zWkbkJ', 4, '{"title":"第20300688条・邪客第七十一","description":"<p>3、黄帝问于伯高曰。愿闻人之肢节以应天地奈何。伯高答曰。天圆地方。人头圆足方以应之。天有日月。人有两目。地有九州岛。人有九窍。天有风雨。人有喜怒。天有雷电。人有声音。天有四时。人有四肢。天有五音。人有五藏。天有六律。人有六府。天有冬夏。人有寒热。天有十曰。人有手十指。辰有十二。人有足十指。茎垂以应之。女子不足二节。以抱人形。天有阴阳。人有夫妻。岁有三百六十五日。人有三百六十五节。地有高山。人有肩膝。地有深谷。人有腋腘。地有十二经水。人有十二经脉。地有泉脉。人有卫气。地有草蓂。人有毫毛。天有昼夜。人有卧起。天有列星。人有牙齿。地有小山。人有小节。地有山石。人有高骨。地有林木。人有募筋。地有聚邑。人有腘肉。岁有十二月。人有十二节。地有四时不生草。人有无子。此人与天地相应者也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300688,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '2024-09-26T13:54:49.000Z', '3、黄帝问于伯高曰。愿闻人之肢节以应天地奈何。伯高答曰。天圆地方。人头圆足方以应之。天有日月。人有两目。地有九州岛。人有九窍。天有风雨。人有喜怒。天有雷电。人有声音。天有四时。人有四肢。天有五音。人有五藏。天有六律。人有六府。天有冬夏。人有寒热。天有十曰。人有手十指。辰有十二。人有足十指。茎垂以应之。女子不足二节。以抱人形。天有阴阳。人有夫妻。岁有三百六十五日。人有三百六十五节。地有高山。人有肩膝。地有深谷。人有腋腘。地有十二经水。人有十二经脉。地有泉脉。人有卫气。地有草蓂。人有毫毛。天有昼夜。人有卧起。天有列星。人有牙齿。地有小山。人有小节。地有山石。人有高骨。地有林木。人有募筋。地有聚邑。人有腘肉。岁有十二月。人有十二节。地有四时不生草。人有无子。此人与天地相应者也。', '2024-09-26T13:54:49.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'btXQ0MChVuV');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('YjlNCqFAeFE', 4, '{"title":"第20300689条・邪客第七十一","description":"<p>4、黄帝问于岐伯曰。余愿闻持针之数。内针之理。纵舍之意。扞皮开腠理。奈何。脉之屈折。出入之处。焉至而出。焉至而止。焉至而徐。焉至而疾。焉至而入。六府之输于身者。余愿尽闻其方。岐伯曰。帝之所问。针道毕矣。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300689,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '4、黄帝问于岐伯曰。余愿闻持针之数。内针之理。纵舍之意。扞皮开腠理。奈何。脉之屈折。出入之处。焉至而出。焉至而止。焉至而徐。焉至而疾。焉至而入。六府之输于身者。余愿尽闻其方。岐伯曰。帝之所问。针道毕矣。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'btXQ0MChVuV');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('cT7QtKpTzMw', 4, '{"title":"第20300690条・邪客第七十一","description":"<p>5、黄帝曰。愿卒闻之。岐伯曰。手太阴之脉。出于大指之端。内屈。循白肉际。至本节之后太渊。留以澹。外屈。上于本节下。内屈。与阴诸络会于鱼际。数脉并注。其气滑利。伏行壅骨之下。外屈。出于寸口而行。上至于肘内廉。入于大筋之下。内屈。上行臑阴。入腋下。内屈。走肺。此顺行逆数之屈折也。心主之脉。出于中指之端。内屈。循中指内廉以上。留于掌中。伏行两骨之间。外屈。出两筋之间。上至肘内廉。入于小筋之下。留两骨之会。上入于胸中。内络于心脉。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300690,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '5、黄帝曰。愿卒闻之。岐伯曰。手太阴之脉。出于大指之端。内屈。循白肉际。至本节之后太渊。留以澹。外屈。上于本节下。内屈。与阴诸络会于鱼际。数脉并注。其气滑利。伏行壅骨之下。外屈。出于寸口而行。上至于肘内廉。入于大筋之下。内屈。上行臑阴。入腋下。内屈。走肺。此顺行逆数之屈折也。心主之脉。出于中指之端。内屈。循中指内廉以上。留于掌中。伏行两骨之间。外屈。出两筋之间。上至肘内廉。入于小筋之下。留两骨之会。上入于胸中。内络于心脉。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'btXQ0MChVuV');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('aiZFgrJOj4p', 4, '{"title":"第20300691条・邪客第七十一","description":"<p>6、黄帝曰。手太阴之脉。独无俞。何也。岐伯曰。少阴。心脉也。心者。五藏六府之大主也。精神之所舍也。其藏坚固。邪弗能容也。容之则心伤。心伤则神去。神去则死矣。故诸邪之在于心者。皆在于心之包络。包络者。心主之脉也。故独无俞焉。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300691,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '6、黄帝曰。手太阴之脉。独无俞。何也。岐伯曰。少阴。心脉也。心者。五藏六府之大主也。精神之所舍也。其藏坚固。邪弗能容也。容之则心伤。心伤则神去。神去则死矣。故诸邪之在于心者。皆在于心之包络。包络者。心主之脉也。故独无俞焉。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'btXQ0MChVuV');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('YSdPN04DX9p', 4, '{"title":"第20300692条・邪客第七十一","description":"<p>7、黄帝曰。少阴独无俞者。不病乎。岐伯曰。其外经病而藏不病。故独取其经于掌后锐骨之端。其余脉出入屈折。其行之徐疾。皆如手少阴心主之脉行也。故本俞者。皆因其气之虚实疾徐以取之。是谓因冲而泻。因衰而补。如是者。邪气得去。真气坚固。是谓因天之序。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300692,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '7、黄帝曰。少阴独无俞者。不病乎。岐伯曰。其外经病而藏不病。故独取其经于掌后锐骨之端。其余脉出入屈折。其行之徐疾。皆如手少阴心主之脉行也。故本俞者。皆因其气之虚实疾徐以取之。是谓因冲而泻。因衰而补。如是者。邪气得去。真气坚固。是谓因天之序。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'btXQ0MChVuV');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('EjGay00LYVO', 4, '{"title":"第20300693条・邪客第七十一","description":"<p>8、黄帝曰。持针纵舍奈何。岐伯曰。必先明知十二经脉之本末。皮肤之寒热。脉之盛衰滑涩。其脉滑而盛者。病日进。虚而细者。久以持。大以涩者。为痛痹。阴阳如一者。病难治。其本末尚热者。病尚在。其热以衰者。其病亦去矣。持其尺。察其肉之坚脆。大小滑涩。寒温燥湿。因视目之五色。以知五藏。而决死生。视其血脉。察其色。以知其寒热痛痹。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300693,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '8、黄帝曰。持针纵舍奈何。岐伯曰。必先明知十二经脉之本末。皮肤之寒热。脉之盛衰滑涩。其脉滑而盛者。病日进。虚而细者。久以持。大以涩者。为痛痹。阴阳如一者。病难治。其本末尚热者。病尚在。其热以衰者。其病亦去矣。持其尺。察其肉之坚脆。大小滑涩。寒温燥湿。因视目之五色。以知五藏。而决死生。视其血脉。察其色。以知其寒热痛痹。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'btXQ0MChVuV');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('hKlLJKBtG4C', 4, '{"title":"第20300694条・邪客第七十一","description":"<p>9、黄帝曰。持针纵舍。余未得其意也。岐伯曰。持针之道。欲端以正。安以静。先知虚实而行疾徐。左手执骨。右手循之。无与肉果。泻欲端以正。补必闭肤。辅针导气。邪得淫泆。真气得居。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300694,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '9、黄帝曰。持针纵舍。余未得其意也。岐伯曰。持针之道。欲端以正。安以静。先知虚实而行疾徐。左手执骨。右手循之。无与肉果。泻欲端以正。补必闭肤。辅针导气。邪得淫泆。真气得居。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'btXQ0MChVuV');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('RBCNVxf4Wsh', 4, '{"title":"第20300695条・邪客第七十一","description":"<p>10、黄帝曰。扞皮开腠理奈何。岐伯曰。因其分肉。左别其肤。微内而徐端之。适神不散。邪气得去。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300695,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '10、黄帝曰。扞皮开腠理奈何。岐伯曰。因其分肉。左别其肤。微内而徐端之。适神不散。邪气得去。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'btXQ0MChVuV');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('UP7HDhXj0mr', 4, '{"title":"第20300696条・邪客第七十一","description":"<p>11、黄帝问于岐伯曰。人有八虚。各何以候。岐伯答曰。以候五藏。黄帝曰。候之奈何。岐伯曰。肺心有邪。其气留于两肘。肝有邪。其气流于两腋。脾有邪。其气留于两髀。肾有邪。其气留于两腘。凡此八虚者。皆机关之室。真气之所过。血络之所游。邪气恶血。固不得住留。住留则伤筋络骨节。机关不得屈伸。故痀挛也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300696,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '11、黄帝问于岐伯曰。人有八虚。各何以候。岐伯答曰。以候五藏。黄帝曰。候之奈何。岐伯曰。肺心有邪。其气留于两肘。肝有邪。其气流于两腋。脾有邪。其气留于两髀。肾有邪。其气留于两腘。凡此八虚者。皆机关之室。真气之所过。血络之所游。邪气恶血。固不得住留。住留则伤筋络骨节。机关不得屈伸。故痀挛也。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'btXQ0MChVuV');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ZupmREYNTkr', 4, '{"title":"第20300697条・通天第七十二","description":"<p>1、黄帝问于少师曰。余尝闻人有阴阳。何谓阴人。何谓阳人。少师曰。天地之间。六合之内。不离于五。人亦应之。非徒一阴一阳而已也。而略言耳。口弗能遍明也。黄帝曰。愿略闻其意。有贤人圣人。心能备而行之乎。少师曰。盖有太阴之人。少阴之人。太阳之人。少阳之人。阴阳和平之人。凡五人者。其态不同。其筋骨气血各不等。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300697,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '1、黄帝问于少师曰。余尝闻人有阴阳。何谓阴人。何谓阳人。少师曰。天地之间。六合之内。不离于五。人亦应之。非徒一阴一阳而已也。而略言耳。口弗能遍明也。黄帝曰。愿略闻其意。有贤人圣人。心能备而行之乎。少师曰。盖有太阴之人。少阴之人。太阳之人。少阳之人。阴阳和平之人。凡五人者。其态不同。其筋骨气血各不等。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'z56pj4EcR1X');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('G9zuBJ7vS5o', 4, '{"title":"第20300698条・通天第七十二","description":"<p>2、黄帝曰。其不等者。可得闻乎。少师曰。太阴之人。贪而不仁。下齐湛湛。好内而恶出。心和而不发。不务于时。动而后之。此太阴之人也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300698,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2、黄帝曰。其不等者。可得闻乎。少师曰。太阴之人。贪而不仁。下齐湛湛。好内而恶出。心和而不发。不务于时。动而后之。此太阴之人也。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'z56pj4EcR1X');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Y2hNpLREXcW', 4, '{"title":"第20300699条・通天第七十二","description":"<p>3、少阴之人。小贪而贼心。见人有亡。常若有得。好伤好害。见人有荣。乃反愠怒。心疾而无恩。此少阴之人也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300699,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '3、少阴之人。小贪而贼心。见人有亡。常若有得。好伤好害。见人有荣。乃反愠怒。心疾而无恩。此少阴之人也。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'z56pj4EcR1X');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('458RbZW5D4G', 4, '{"title":"第20300700条・通天第七十二","description":"<p>4、太阳之人。居处于于。好言大事。无能而虚说。志发乎四野。举措不顾是非。为事如常自用。事虽败。而常无悔。此太阳之人也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300700,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '4、太阳之人。居处于于。好言大事。无能而虚说。志发乎四野。举措不顾是非。为事如常自用。事虽败。而常无悔。此太阳之人也。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'z56pj4EcR1X');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('FKCrafrYKbm', 4, '{"title":"第20300701条・通天第七十二","description":"<p>5、少阳之人。諟谛好自责。有小小官。则高自宜。好为外交。而不内附。此少阳之人也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300701,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '5、少阳之人。諟谛好自责。有小小官。则高自宜。好为外交。而不内附。此少阳之人也。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'z56pj4EcR1X');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Xoo6cMdo0It', 4, '{"title":"第20300702条・通天第七十二","description":"<p>6、阴阳和平之人。居处安静。无为惧惧。无为欣欣。婉然从物。或与不争。与时变化。尊则谦谦。谭而不治。是谓至治。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300702,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '6、阴阳和平之人。居处安静。无为惧惧。无为欣欣。婉然从物。或与不争。与时变化。尊则谦谦。谭而不治。是谓至治。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'z56pj4EcR1X');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('mgKX6TRfYXP', 4, '{"title":"第20300703条・通天第七十二","description":"<p>7、古之善用针艾者。视人五态。乃治之。盛者泻之。虚者补之。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300703,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '7、古之善用针艾者。视人五态。乃治之。盛者泻之。虚者补之。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'z56pj4EcR1X');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('KAR5EaS3u1R', 4, '{"title":"第20300704条・通天第七十二","description":"<p>8、黄帝曰。治人之五态奈何。少师曰。太阴之人。多阴而无阳。其阴血浊。其卫气涩。阴阳不和。缓筋而厚皮。不之疾泻。不能移之。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300704,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '8、黄帝曰。治人之五态奈何。少师曰。太阴之人。多阴而无阳。其阴血浊。其卫气涩。阴阳不和。缓筋而厚皮。不之疾泻。不能移之。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'z56pj4EcR1X');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('71yAOgkfeBj', 4, '{"title":"第20300705条・通天第七十二","description":"<p>9、少阴之人。多阴少阳。小胃而大肠。六府不调。其阳明脉小。而太阳脉大。必审调之。其血易脱。其气易败也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300705,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '9、少阴之人。多阴少阳。小胃而大肠。六府不调。其阳明脉小。而太阳脉大。必审调之。其血易脱。其气易败也。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'z56pj4EcR1X');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('V31o9hIQpqs', 4, '{"title":"第20300706条・通天第七十二","description":"<p>10、太阳之人。多阳而少阴。必谨调之。无脱其阴。而泻其阳。阳重脱者易狂。阴阳皆脱者。暴死。不知人也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300706,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '10、太阳之人。多阳而少阴。必谨调之。无脱其阴。而泻其阳。阳重脱者易狂。阴阳皆脱者。暴死。不知人也。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'z56pj4EcR1X');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ndkwTZQKZ4Q', 4, '{"title":"第20300707条・通天第七十二","description":"<p>11、少阳之人。多阳少阴。经小而络大。血在中而气外。实阴而虚阳。独泻其络脉。则强气脱而疾。中气不足。病不起也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300707,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '11、少阳之人。多阳少阴。经小而络大。血在中而气外。实阴而虚阳。独泻其络脉。则强气脱而疾。中气不足。病不起也。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'z56pj4EcR1X');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('up0uZ67NvVy', 4, '{"title":"第20300708条・通天第七十二","description":"<p>12、阴阳和平之人。其阴阳之气和。血脉调。谨诊其阴阳。视其邪正。安容仪。审有余不足。盛则泻之。虚则补之。不盛不虚。以经取之。此所以调阴阳。别五态之人者也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300708,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '12、阴阳和平之人。其阴阳之气和。血脉调。谨诊其阴阳。视其邪正。安容仪。审有余不足。盛则泻之。虚则补之。不盛不虚。以经取之。此所以调阴阳。别五态之人者也。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'z56pj4EcR1X');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('s71Wrqsem7f', 4, '{"title":"第20300709条・通天第七十二","description":"<p>13、黄帝曰。夫五态之人者。相与毋故。卒然新会。未知其行也。何以别之。少师答曰。众人之属。不知五态之人者。故五五二十五人。而五态之人不与焉。五态之人。尤不合于众者也。黄帝曰。别五态之人。奈何。少师曰。太阴之人。其状黮黮然黑色。念然下意。临临然长大。腘然未偻。此太阴之人也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300709,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '13、黄帝曰。夫五态之人者。相与毋故。卒然新会。未知其行也。何以别之。少师答曰。众人之属。不知五态之人者。故五五二十五人。而五态之人不与焉。五态之人。尤不合于众者也。黄帝曰。别五态之人。奈何。少师曰。太阴之人。其状黮黮然黑色。念然下意。临临然长大。腘然未偻。此太阴之人也。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'z56pj4EcR1X');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('avkkEYo8Dw0', 4, '{"title":"第20300710条・通天第七十二","description":"<p>14、少阴之人。其状清然窃然。固以阴贼。立而躁崄。行而似伏。此少阴之人也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300710,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '14、少阴之人。其状清然窃然。固以阴贼。立而躁崄。行而似伏。此少阴之人也。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'z56pj4EcR1X');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Glk2Vet4zKk', 4, '{"title":"第20300711条・通天第七十二","description":"<p>15、太阳之人。其状轩轩储储。反身折腘。此太阳之人也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300711,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '15、太阳之人。其状轩轩储储。反身折腘。此太阳之人也。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'z56pj4EcR1X');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('SGBR7wGcsVd', 4, '{"title":"第20300712条・通天第七十二","description":"<p>16、少阳之人。其状立则好仰。行则好摇。其两臂两肘。则常出于背。此少阳之人也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300712,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '16、少阳之人。其状立则好仰。行则好摇。其两臂两肘。则常出于背。此少阳之人也。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'z56pj4EcR1X');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('WDC5vilt7ga', 4, '{"title":"第20300713条・通天第七十二","description":"<p>17、阴阳和平之人。其状委委然。随随然。颙颙然。愉愉然。䁢䁢然。豆豆然。众人皆曰君子。此阴阳和平之人也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300713,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '17、阴阳和平之人。其状委委然。随随然。颙颙然。愉愉然。䁢䁢然。豆豆然。众人皆曰君子。此阴阳和平之人也。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'z56pj4EcR1X');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('UOumEqcxWfS', 4, '{"title":"第20300714条・官能第七十三","description":"<p>1、黄帝问于岐伯曰。余闻九针于夫子。众多矣不可胜数。余推而论之。以为一纪。余司诵之。子听其理。非则语余。请正其道。令可久传后世无患。得其人乃传。非其人勿言。岐伯稽首再拜曰。请听圣王之道。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300714,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '1、黄帝问于岐伯曰。余闻九针于夫子。众多矣不可胜数。余推而论之。以为一纪。余司诵之。子听其理。非则语余。请正其道。令可久传后世无患。得其人乃传。非其人勿言。岐伯稽首再拜曰。请听圣王之道。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', '2eClkHKJRda');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('BQ2eqI6M7h1', 4, '{"title":"第20300715条・官能第七十三","description":"<p>2、黄帝曰。用针之理。必知形气之所在。左右上下。阴阳表里。血气多少。行之逆顺。出入之合。谋伐有过。知解结。知补虚泻实。上下气门。明通于四海。审其所在。寒热淋露以输异处。审于调气。明于经隧。左右肢络。尽知其会。寒与热争。能合而调之。虚与实邻。知决而通之。左右不调。把而行之。明于逆顺。乃知可治。阴阳不奇。故知起时。审于本末。察其寒热。得邪所在。万刺不殆。知官九针。刺道毕矣。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300715,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2、黄帝曰。用针之理。必知形气之所在。左右上下。阴阳表里。血气多少。行之逆顺。出入之合。谋伐有过。知解结。知补虚泻实。上下气门。明通于四海。审其所在。寒热淋露以输异处。审于调气。明于经隧。左右肢络。尽知其会。寒与热争。能合而调之。虚与实邻。知决而通之。左右不调。把而行之。明于逆顺。乃知可治。阴阳不奇。故知起时。审于本末。察其寒热。得邪所在。万刺不殆。知官九针。刺道毕矣。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', '2eClkHKJRda');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('4GcQu85EsGR', 4, '{"title":"第20300716条・官能第七十三","description":"<p>3、明于五俞徐疾所在。屈伸出入。皆有条理。言阴与阳。合于五行。五藏六府。亦有所藏。四时八风。尽有阴阳。各得其位。合于明堂。各处色部。五藏六府。察其所痛。左右上下。知其寒温。何经所在。审皮肤之寒温滑涩。知其所苦。膈有上下。知其气所在。先得其道。稀而疏之。稍深以留。故能徐入之。大热在上。推而下之。从上下者。引而去之。视前痛者。常先取之。大寒在外。留而补之。入于中者。从合泻之。针所不为。灸之所宜。上气不足。推而扬之。下气不足。积而从之。阴阳皆虚。火自当之。厥而寒甚。骨廉陷下。寒过于膝。下陵三里。阴络所过。得之留止。寒入于中。推而行之。经陷下者。火则当之。结络坚紧。火所治之。不知所苦。两蹻之下。男阴女阳。良工所禁。针论毕矣。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300716,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '3、明于五俞徐疾所在。屈伸出入。皆有条理。言阴与阳。合于五行。五藏六府。亦有所藏。四时八风。尽有阴阳。各得其位。合于明堂。各处色部。五藏六府。察其所痛。左右上下。知其寒温。何经所在。审皮肤之寒温滑涩。知其所苦。膈有上下。知其气所在。先得其道。稀而疏之。稍深以留。故能徐入之。大热在上。推而下之。从上下者。引而去之。视前痛者。常先取之。大寒在外。留而补之。入于中者。从合泻之。针所不为。灸之所宜。上气不足。推而扬之。下气不足。积而从之。阴阳皆虚。火自当之。厥而寒甚。骨廉陷下。寒过于膝。下陵三里。阴络所过。得之留止。寒入于中。推而行之。经陷下者。火则当之。结络坚紧。火所治之。不知所苦。两蹻之下。男阴女阳。良工所禁。针论毕矣。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', '2eClkHKJRda');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('1TiVw1lTPaN', 4, '{"title":"第20300717条・官能第七十三","description":"<p>4、用针之服。必有法则。上视天光。下司八正。以辟奇邪。而观百姓。审于虚实。无犯其邪。是得天之灵。遇岁之虚。救而不胜。反受其殃。故曰必知天忌。乃言针意。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300717,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '4、用针之服。必有法则。上视天光。下司八正。以辟奇邪。而观百姓。审于虚实。无犯其邪。是得天之灵。遇岁之虚。救而不胜。反受其殃。故曰必知天忌。乃言针意。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', '2eClkHKJRda');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('zDI1khwu2SD', 4, '{"title":"第20300718条・官能第七十三","description":"<p>5、法于往古。验于来今。观于窈冥。通于无穷。粗之所不见。良工之所贵。莫知其形。若神髣佛。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300718,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '5、法于往古。验于来今。观于窈冥。通于无穷。粗之所不见。良工之所贵。莫知其形。若神髣佛。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', '2eClkHKJRda');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Jled7rX61p8', 4, '{"title":"第20300719条・官能第七十三","description":"<p>6、邪气之中人也。洒淅动形。正邪之中人也。微先见于色。不知于其身。若有若无。若亡若存。有形无形。莫知其情。是故上工之取气。乃救其萌芽。下工守其已成。因败其形。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300719,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '6、邪气之中人也。洒淅动形。正邪之中人也。微先见于色。不知于其身。若有若无。若亡若存。有形无形。莫知其情。是故上工之取气。乃救其萌芽。下工守其已成。因败其形。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', '2eClkHKJRda');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('dcbikvvLKNX', 4, '{"title":"第20300720条・官能第七十三","description":"<p>7、是故工之用针也。知气之所在。而守其门户。明于调气。补泻所在。徐疾之意。所取之处。泻必用员。切而转之。其气乃行。疾而徐出。邪气乃出。伸而迎之。遥大其穴。气出乃疾。补必用方。外引其皮。令当其门。左引其枢。右推其肤。微旋而徐推之。必端以正。安以静。坚心无解。欲微以留。气下而疾出之。推其皮。盖其外门。真气乃存。用针之要。无忘其神。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300720,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '7、是故工之用针也。知气之所在。而守其门户。明于调气。补泻所在。徐疾之意。所取之处。泻必用员。切而转之。其气乃行。疾而徐出。邪气乃出。伸而迎之。遥大其穴。气出乃疾。补必用方。外引其皮。令当其门。左引其枢。右推其肤。微旋而徐推之。必端以正。安以静。坚心无解。欲微以留。气下而疾出之。推其皮。盖其外门。真气乃存。用针之要。无忘其神。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', '2eClkHKJRda');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('5hcaP6WN2zM', 4, '{"title":"第20300721条・官能第七十三","description":"<p>8、雷公问于黄帝曰。针论曰。得其人乃传。非其人勿言。何以知其可传。黄帝曰。各得其人。任之其能。故能明其事。雷公曰。愿闻官能奈何。黄帝曰。明目者。可使视色。聪耳者。可使听音。捷疾辞语者。可使传论。语徐而安静。手巧而心审谛者。可使行针艾。理血气而调诸逆顺。察阴阳而兼诸方。缓节柔筋而心和调者。可使导引行气。疾毒言语轻人者。可使唾痈呪病。爪苦手毒。为事善伤者。可使按积抑痹。各得其能。方乃可行。其名乃彰。不得其人。其功不成。其师无名。故曰。得其人乃言。非其人勿传。此之谓也。手毒者。可使试按龟。置龟于器下。而按其上。五十日而死矣。手甘者。复生如故也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300721,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '8、雷公问于黄帝曰。针论曰。得其人乃传。非其人勿言。何以知其可传。黄帝曰。各得其人。任之其能。故能明其事。雷公曰。愿闻官能奈何。黄帝曰。明目者。可使视色。聪耳者。可使听音。捷疾辞语者。可使传论。语徐而安静。手巧而心审谛者。可使行针艾。理血气而调诸逆顺。察阴阳而兼诸方。缓节柔筋而心和调者。可使导引行气。疾毒言语轻人者。可使唾痈呪病。爪苦手毒。为事善伤者。可使按积抑痹。各得其能。方乃可行。其名乃彰。不得其人。其功不成。其师无名。故曰。得其人乃言。非其人勿传。此之谓也。手毒者。可使试按龟。置龟于器下。而按其上。五十日而死矣。手甘者。复生如故也。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', '2eClkHKJRda');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('6Hlb79XoT8s', 4, '{"title":"第20300722条・论疾诊尺第七十四","description":"<p>1、黄帝问岐伯曰。余欲无视色持脉。独调其尺。以言其病。从外知内。为之奈何。岐伯曰。审其尺之缓急小大滑涩。肉之坚脆。而病形定矣。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300722,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '1、黄帝问岐伯曰。余欲无视色持脉。独调其尺。以言其病。从外知内。为之奈何。岐伯曰。审其尺之缓急小大滑涩。肉之坚脆。而病形定矣。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', '2UuTy22rmEc');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('b8TPV7hPSze', 4, '{"title":"第20300723条・论疾诊尺第七十四","description":"<p>2、视人之目窠上微痈。如新卧起状。其颈脉动。时咳。按其手足上。窅而不起者。风水肤胀也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300723,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2、视人之目窠上微痈。如新卧起状。其颈脉动。时咳。按其手足上。窅而不起者。风水肤胀也。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', '2UuTy22rmEc');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('3oHxVxXzEbI', 4, '{"title":"第20300724条・论疾诊尺第七十四","description":"<p>3、尺肤滑。其淖泽者。风也。尺肉弱者。解并。安卧脱肉者。寒热。不治。尺肤滑而泽脂者。风也。尺肤涩者。风痹也。尺肤粗如枯鱼之鳞者。水泆饮也。尺肤热甚。脉盛躁者。病温也。其脉甚而滑者。病且出也。尺肤寒。其脉小者。泄。少气。尺肤炬然。先热后寒者。寒热也。尺肤先寒。久大之而热者。亦寒热也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300724,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '3、尺肤滑。其淖泽者。风也。尺肉弱者。解并。安卧脱肉者。寒热。不治。尺肤滑而泽脂者。风也。尺肤涩者。风痹也。尺肤粗如枯鱼之鳞者。水泆饮也。尺肤热甚。脉盛躁者。病温也。其脉甚而滑者。病且出也。尺肤寒。其脉小者。泄。少气。尺肤炬然。先热后寒者。寒热也。尺肤先寒。久大之而热者。亦寒热也。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', '2UuTy22rmEc');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('OGUQMNG8Jc8', 4, '{"title":"第20300725条・论疾诊尺第七十四","description":"<p>4、肘所独热者。腰以上热。手所独热者。腰以下热。肘前独热者。膺前热。肘后独热者。肩背热。臂中独热者。腰腹热。肘后粗以下三四寸热者。肠中有虫。掌中热者。腹中热。掌中寒者。腹中寒。鱼上白肉有青血脉者。胃中有寒。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300725,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '4、肘所独热者。腰以上热。手所独热者。腰以下热。肘前独热者。膺前热。肘后独热者。肩背热。臂中独热者。腰腹热。肘后粗以下三四寸热者。肠中有虫。掌中热者。腹中热。掌中寒者。腹中寒。鱼上白肉有青血脉者。胃中有寒。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', '2UuTy22rmEc');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('eTmJfXjpkoM', 4, '{"title":"第20300726条・论疾诊尺第七十四","description":"<p>5、尺炬然热。人迎大者。当本血。尺坚大。脉小甚。少气。免有加。立死。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300726,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '5、尺炬然热。人迎大者。当本血。尺坚大。脉小甚。少气。免有加。立死。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', '2UuTy22rmEc');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('37KQtqwm2WS', 4, '{"title":"第20300727条・论疾诊尺第七十四","description":"<p>6、目赤色者病在心。白在肺。青在肝。黄在脾。黑在肾。黄色不可名者。病在胸中。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300727,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '6、目赤色者病在心。白在肺。青在肝。黄在脾。黑在肾。黄色不可名者。病在胸中。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', '2UuTy22rmEc');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('5BHsFyIuyj5', 4, '{"title":"第20300728条・论疾诊尺第七十四","description":"<p>7、诊目痛。赤脉从上下者。太阳病。从下上者。阳明病。从外走内者。少阳病。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300728,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '7、诊目痛。赤脉从上下者。太阳病。从下上者。阳明病。从外走内者。少阳病。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', '2UuTy22rmEc');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ov792akd892', 4, '{"title":"第20300729条・论疾诊尺第七十四","description":"<p>8、诊寒热。赤脉上下至瞳子。见一脉一岁死。见一脉半。一岁半死。见二脉。二岁死。见二脉半。二岁半死。见三脉。三岁死。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300729,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '8、诊寒热。赤脉上下至瞳子。见一脉一岁死。见一脉半。一岁半死。见二脉。二岁死。见二脉半。二岁半死。见三脉。三岁死。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', '2UuTy22rmEc');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('3dC6d3tFNbo', 4, '{"title":"第20300730条・论疾诊尺第七十四","description":"<p>9、诊龋齿痛。按其阳之来。有过者独热。在左左热。在右右热。在上上热。在下下热。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300730,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '9、诊龋齿痛。按其阳之来。有过者独热。在左左热。在右右热。在上上热。在下下热。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', '2UuTy22rmEc');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Gzfjes46AdD', 4, '{"title":"第20300731条・论疾诊尺第七十四","description":"<p>10、诊血脉者。多赤多热。多青多痛。多黑为久痹。多赤。多黑。多青皆见者。寒热。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300731,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '10、诊血脉者。多赤多热。多青多痛。多黑为久痹。多赤。多黑。多青皆见者。寒热。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', '2UuTy22rmEc');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('NkeL74S169r', 4, '{"title":"第20300732条・论疾诊尺第七十四","description":"<p>11、身痛而色微黄。齿垢黄。爪甲上黄。黄疸也。安卧小便黄赤。脉小而涩者不嗜食。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300732,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '11、身痛而色微黄。齿垢黄。爪甲上黄。黄疸也。安卧小便黄赤。脉小而涩者不嗜食。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', '2UuTy22rmEc');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('NJRrKKhgjyU', 4, '{"title":"第20300733条・论疾诊尺第七十四","description":"<p>12、人病。其寸口之脉。与人迎之脉小大等。及其浮沉等者。病难已也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300733,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '12、人病。其寸口之脉。与人迎之脉小大等。及其浮沉等者。病难已也。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', '2UuTy22rmEc');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('sQ16ZokNKxK', 4, '{"title":"第20300734条・论疾诊尺第七十四","description":"<p>13、女子手少阴脉动甚者妊子。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300734,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '13、女子手少阴脉动甚者妊子。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', '2UuTy22rmEc');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('3N1ImTgxVIo', 4, '{"title":"第20300735条・论疾诊尺第七十四","description":"<p>14、婴儿病。其头毛皆逆上者必死。耳间青脉起者掣痛。大便赤瓣飧泄。脉小者。手足寒。难已。飧泄。脉小。手足温。泄易也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300735,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '14、婴儿病。其头毛皆逆上者必死。耳间青脉起者掣痛。大便赤瓣飧泄。脉小者。手足寒。难已。飧泄。脉小。手足温。泄易也。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', '2UuTy22rmEc');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('wedeqSiFMW5', 4, '{"title":"第20300736条・论疾诊尺第七十四","description":"<p>15、四时之变。寒暑之胜。重阴必阳。重阳必阴。故阴主寒。阳主热。故寒甚则热。热甚则寒。故曰寒生热。热生寒。此阴阳之变也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300736,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '15、四时之变。寒暑之胜。重阴必阳。重阳必阴。故阴主寒。阳主热。故寒甚则热。热甚则寒。故曰寒生热。热生寒。此阴阳之变也。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', '2UuTy22rmEc');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Dzkymj2RoBe', 4, '{"title":"第20300737条・论疾诊尺第七十四","description":"<p>16、故曰。冬伤于寒。春生病热。春伤于风。夏生飧泄肠僻。夏伤于暑。秋生疟。秋伤于湿。冬生咳嗽。是谓四时之序也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300737,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '16、故曰。冬伤于寒。春生病热。春伤于风。夏生飧泄肠僻。夏伤于暑。秋生疟。秋伤于湿。冬生咳嗽。是谓四时之序也。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', '2UuTy22rmEc');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('8NSqx8pzVJJ', 4, '{"title":"第20300738条・刺节真邪第七十五","description":"<p>1、黄帝问于岐伯曰。余闻刺有五卫。奈何。岐伯曰。固有五卫。一曰振埃。二曰发蒙。三曰去爪。四曰彻衣。五曰解惑。黄帝曰。夫子言五卫。余未知其意。岐伯曰。振埃者。刺外经去阳病也。发蒙者。刺府俞。去府病也。去爪者。刺关节肢络也。彻衣者。尽刺诸阳之奇俞也。解惑者。尽知调阴阳。补泻有余不足。相倾移也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300738,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '1、黄帝问于岐伯曰。余闻刺有五卫。奈何。岐伯曰。固有五卫。一曰振埃。二曰发蒙。三曰去爪。四曰彻衣。五曰解惑。黄帝曰。夫子言五卫。余未知其意。岐伯曰。振埃者。刺外经去阳病也。发蒙者。刺府俞。去府病也。去爪者。刺关节肢络也。彻衣者。尽刺诸阳之奇俞也。解惑者。尽知调阴阳。补泻有余不足。相倾移也。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'TZwBUc10zqj');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('FNzq4c62lEC', 4, '{"title":"第20300739条・刺节真邪第七十五","description":"<p>2、黄帝曰。刺卫言振埃。夫子乃言刺外经。去阳病。余不知其所谓也。愿卒闻之。岐伯曰。振埃者。阳气大逆。上满于胸中。愤瞋肩息。大气逆上。喘喝坐伏。病恶埃烟。饲不得息。请言振埃。尚疾于振埃。黄帝曰。善。取之何如。岐伯曰。取之天容。黄帝曰。其咳上气穷拙胸痛者。取之奈何。岐伯曰。取之廉泉。黄帝曰。取之有数乎。岐伯曰。取天容者。无过一里。取廉泉者。血变而止。帝曰。善哉。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300739,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2、黄帝曰。刺卫言振埃。夫子乃言刺外经。去阳病。余不知其所谓也。愿卒闻之。岐伯曰。振埃者。阳气大逆。上满于胸中。愤瞋肩息。大气逆上。喘喝坐伏。病恶埃烟。饲不得息。请言振埃。尚疾于振埃。黄帝曰。善。取之何如。岐伯曰。取之天容。黄帝曰。其咳上气穷拙胸痛者。取之奈何。岐伯曰。取之廉泉。黄帝曰。取之有数乎。岐伯曰。取天容者。无过一里。取廉泉者。血变而止。帝曰。善哉。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'TZwBUc10zqj');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('DmJ666FRiz4', 4, '{"title":"第20300740条・刺节真邪第七十五","description":"<p>3、黄帝曰。刺卫言发蒙。余不得其意。夫发蒙者。耳无所闻。目无所见。夫子乃言刺府俞。去府病。何输使然。愿闻其故。岐伯曰。妙乎哉问也。此刺之大约。针之极也。神明之类也。口说书卷。犹不能及也。请言发蒙耳。尚疾于发蒙也。黄帝曰。善。愿卒闻之。岐伯曰。刺此者。必于日中。刺其听宫。中其眸子。声闻于耳。此其输也。黄帝曰。善。何谓声闻于耳。岐伯曰。刺邪以手坚按其两鼻窍。而疾偃其声。必应于针也。黄帝曰。善。此所谓弗见为之。而无目视。见而取之。神明相得者也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300740,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '3、黄帝曰。刺卫言发蒙。余不得其意。夫发蒙者。耳无所闻。目无所见。夫子乃言刺府俞。去府病。何输使然。愿闻其故。岐伯曰。妙乎哉问也。此刺之大约。针之极也。神明之类也。口说书卷。犹不能及也。请言发蒙耳。尚疾于发蒙也。黄帝曰。善。愿卒闻之。岐伯曰。刺此者。必于日中。刺其听宫。中其眸子。声闻于耳。此其输也。黄帝曰。善。何谓声闻于耳。岐伯曰。刺邪以手坚按其两鼻窍。而疾偃其声。必应于针也。黄帝曰。善。此所谓弗见为之。而无目视。见而取之。神明相得者也。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'TZwBUc10zqj');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('G5wMIasvpDH', 4, '{"title":"第20300741条・刺节真邪第七十五","description":"<p>4、黄帝曰。刺卫言去爪。夫子乃言刺关节肢络。愿卒闻之。岐伯曰。腰脊者。身之大关节也。肢胫者。人之管以趋翔也。茎垂者。身中之机。阴精之候。津液之道也。故饮食不节。喜怒不时。津液内溢。乃下留于睪。血道不通。日大不休。俛仰不便。趋翔不能。此病荣然有水。不上不下。铍石所取。形不可匿。常不得蔽。故命曰去爪。帝曰。善。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300741,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '4、黄帝曰。刺卫言去爪。夫子乃言刺关节肢络。愿卒闻之。岐伯曰。腰脊者。身之大关节也。肢胫者。人之管以趋翔也。茎垂者。身中之机。阴精之候。津液之道也。故饮食不节。喜怒不时。津液内溢。乃下留于睪。血道不通。日大不休。俛仰不便。趋翔不能。此病荣然有水。不上不下。铍石所取。形不可匿。常不得蔽。故命曰去爪。帝曰。善。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'TZwBUc10zqj');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('7U5Mvk0cvPC', 4, '{"title":"第20300742条・刺节真邪第七十五","description":"<p>5、黄帝曰。刺卫言彻衣。夫子乃言尽刺诸阳之奇俞。未有常处也。愿卒闻之。岐伯曰。是阳气有余。而阴气不足。阴气不足则内热。阳气有余则外热。内热相搏。热于怀炭。外畏绵帛近。不可近身。又不可近席。腠理闭塞。则汗不出。舌焦唇槁。腊干益燥。饮食不让美恶。黄帝曰。善。取之奈何。岐伯曰。取之于其天府大杼三痕。又刺中膂。以去其热。补足手太阴。以去其汗。热去汗稀。疾于彻衣。黄帝曰。善。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300742,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '5、黄帝曰。刺卫言彻衣。夫子乃言尽刺诸阳之奇俞。未有常处也。愿卒闻之。岐伯曰。是阳气有余。而阴气不足。阴气不足则内热。阳气有余则外热。内热相搏。热于怀炭。外畏绵帛近。不可近身。又不可近席。腠理闭塞。则汗不出。舌焦唇槁。腊干益燥。饮食不让美恶。黄帝曰。善。取之奈何。岐伯曰。取之于其天府大杼三痕。又刺中膂。以去其热。补足手太阴。以去其汗。热去汗稀。疾于彻衣。黄帝曰。善。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'TZwBUc10zqj');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('1z4aV1sLjYX', 4, '{"title":"第20300743条・刺节真邪第七十五","description":"<p>6、黄帝曰。刺卫言解惑。夫子乃言尽知调阴阳。补泻有余不足。相倾移也。惑何以解之。岐伯曰。大风在身。血脉偏虚。虚者不足。实者有余。轻重不得。倾侧宛伏。不知东西。不知南北。乍上乍下。乍反乍复。颠倒无常。甚于迷惑。黄帝曰。善。取之奈何。岐伯曰。泻其有余。补其不足。阴阳平复。用针若此。疾于解惑。黄帝曰。善。请藏之灵兰之室。不敢妄出也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300743,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '6、黄帝曰。刺卫言解惑。夫子乃言尽知调阴阳。补泻有余不足。相倾移也。惑何以解之。岐伯曰。大风在身。血脉偏虚。虚者不足。实者有余。轻重不得。倾侧宛伏。不知东西。不知南北。乍上乍下。乍反乍复。颠倒无常。甚于迷惑。黄帝曰。善。取之奈何。岐伯曰。泻其有余。补其不足。阴阳平复。用针若此。疾于解惑。黄帝曰。善。请藏之灵兰之室。不敢妄出也。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'TZwBUc10zqj');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Qkj9i7pIaDV', 4, '{"title":"第20300744条・刺节真邪第七十五","description":"<p>7、黄帝曰。余闻刺有五邪。何谓五邪。岐伯曰。病有持痈者。有容大者。有狭小者。有热者。有寒者。是谓五邪。黄帝曰。刺五邪奈何。岐伯曰。凡刺五邪之方。不过五章。瘅热消灭。肿聚散亡。寒痹益温。小者益阳。大者必去。请道其方。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300744,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '7、黄帝曰。余闻刺有五邪。何谓五邪。岐伯曰。病有持痈者。有容大者。有狭小者。有热者。有寒者。是谓五邪。黄帝曰。刺五邪奈何。岐伯曰。凡刺五邪之方。不过五章。瘅热消灭。肿聚散亡。寒痹益温。小者益阳。大者必去。请道其方。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'TZwBUc10zqj');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('M5T9h4CGrKI', 4, '{"title":"第20300745条・刺节真邪第七十五","description":"<p>8、凡刺痈邪。无迎陇。易俗移性。不得脓。脆道更行。去其乡。不安处所乃散亡。诸阴阳过痈者。取之其输泻之。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300745,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '8、凡刺痈邪。无迎陇。易俗移性。不得脓。脆道更行。去其乡。不安处所乃散亡。诸阴阳过痈者。取之其输泻之。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'TZwBUc10zqj');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('317Yyx1RTfN', 4, '{"title":"第20300746条・刺节真邪第七十五","description":"<p>9、凡刺大邪。日以小。泄夺其有余。乃益虚。剽其通。针其邪。肌肉亲视之。毋有反其真。刺诸阳分肉间。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300746,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '9、凡刺大邪。日以小。泄夺其有余。乃益虚。剽其通。针其邪。肌肉亲视之。毋有反其真。刺诸阳分肉间。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'TZwBUc10zqj');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('HHUgnpvu44i', 4, '{"title":"第20300747条・刺节真邪第七十五","description":"<p>10、凡刺小邪。日以大。补其不足。乃无害。视其所在。迎之界。远近尽至。其不得外侵而行之。乃自费。刺分肉间。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300747,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '10、凡刺小邪。日以大。补其不足。乃无害。视其所在。迎之界。远近尽至。其不得外侵而行之。乃自费。刺分肉间。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'TZwBUc10zqj');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('oe1pgw5VaRn', 4, '{"title":"第20300748条・刺节真邪第七十五","description":"<p>11、凡刺热邪。越而苍。出游不归。乃无病。为开通。辟门户。使邪得出。病乃已。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300748,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '11、凡刺热邪。越而苍。出游不归。乃无病。为开通。辟门户。使邪得出。病乃已。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'TZwBUc10zqj');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('2Mr0C8uzxRA', 4, '{"title":"第20300749条・刺节真邪第七十五","description":"<p>12、凡刺寒邪。日以温。徐往徐来。致其神。门户已闭。气不分。虚实得调。其气存也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300749,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '12、凡刺寒邪。日以温。徐往徐来。致其神。门户已闭。气不分。虚实得调。其气存也。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'TZwBUc10zqj');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('pggbKU9RBzn', 4, '{"title":"第20300750条・刺节真邪第七十五","description":"<p>13、黄帝曰。官针奈何。岐伯曰。刺痈者。用铍针。刺大者。用锋针。刺小者。用员利针。刺热者。用纔针。刺寒者。用毫针也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300750,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '13、黄帝曰。官针奈何。岐伯曰。刺痈者。用铍针。刺大者。用锋针。刺小者。用员利针。刺热者。用纔针。刺寒者。用毫针也。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'TZwBUc10zqj');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ELUTHVJf15G', 4, '{"title":"第20300751条・刺节真邪第七十五","description":"<p>14、请言解论。与天地相应。与四时相副。人参天地。故可为解。下有渐洳。上生苇蒲。此所以知形气之多少也。阴阳者。寒暑也。热则滋雨而在上。根茎少汁。人气在外。皮肤缓。腠理开。血气减。汗大泄。皮淖泽。寒则地冻水冰。人气在中。皮肤致。腠理闭。汗不出。血气强。肉坚涩。当是之时。善行水者。不能往冰。善穿地者。不能击冻。善用针者。亦不能取四厥。血脉凝结。坚搏不往来者。亦未可即柔。故行水者。必待天温。冰释冻解。而水可行。地可穿也。人脉犹是也。治厥者。必先熨调和其经。掌与腋。肘与脚。项与脊以调之。火气已通。血脉乃行。然后视其病。脉淖泽者。刺而平之。坚紧者。破而散之。气下乃止。此所谓以解结者也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300751,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '14、请言解论。与天地相应。与四时相副。人参天地。故可为解。下有渐洳。上生苇蒲。此所以知形气之多少也。阴阳者。寒暑也。热则滋雨而在上。根茎少汁。人气在外。皮肤缓。腠理开。血气减。汗大泄。皮淖泽。寒则地冻水冰。人气在中。皮肤致。腠理闭。汗不出。血气强。肉坚涩。当是之时。善行水者。不能往冰。善穿地者。不能击冻。善用针者。亦不能取四厥。血脉凝结。坚搏不往来者。亦未可即柔。故行水者。必待天温。冰释冻解。而水可行。地可穿也。人脉犹是也。治厥者。必先熨调和其经。掌与腋。肘与脚。项与脊以调之。火气已通。血脉乃行。然后视其病。脉淖泽者。刺而平之。坚紧者。破而散之。气下乃止。此所谓以解结者也。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'TZwBUc10zqj');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('oGwB5kp48ck', 4, '{"title":"第20300752条・刺节真邪第七十五","description":"<p>15、用针之类。在于调气。气积于胃。以通营卫。各行其道。宗气留于海。其下者。注于气街。其上者。走于息道。故厥在于足。宗气不下。脉中之血。凝而留止。弗之火调。弗能取之。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300752,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '15、用针之类。在于调气。气积于胃。以通营卫。各行其道。宗气留于海。其下者。注于气街。其上者。走于息道。故厥在于足。宗气不下。脉中之血。凝而留止。弗之火调。弗能取之。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'TZwBUc10zqj');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('TgYaColgOFE', 4, '{"title":"第20300753条・刺节真邪第七十五","description":"<p>16、用针者。必先察其经络之实虚。切而循之。按而弹之。视其应动者。乃后取之而下之。六经调者。谓之不病。虽病。谓之自已也。一经上实下虚而不通者。此必有横络盛加于大经。令之不通。视而泻之。此所谓解结也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300753,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '16、用针者。必先察其经络之实虚。切而循之。按而弹之。视其应动者。乃后取之而下之。六经调者。谓之不病。虽病。谓之自已也。一经上实下虚而不通者。此必有横络盛加于大经。令之不通。视而泻之。此所谓解结也。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'TZwBUc10zqj');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('yliu8tAjIoc', 4, '{"title":"第20300754条・刺节真邪第七十五","description":"<p>17、上寒下热。先刺其项太阳。久留之。已刺则熨项与肩胛。令热下合乃止。此所谓推而上之者也。上热下寒。视其虚脉而陷之于经络者。取之。气下乃止。此所谓引而下之者也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300754,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '17、上寒下热。先刺其项太阳。久留之。已刺则熨项与肩胛。令热下合乃止。此所谓推而上之者也。上热下寒。视其虚脉而陷之于经络者。取之。气下乃止。此所谓引而下之者也。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'TZwBUc10zqj');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ot3B88Q0XI0', 4, '{"title":"第20300755条・刺节真邪第七十五","description":"<p>18、大热遍身。狂而妄见妄闻妄言。视足阳明及大络取之。虚者补之。血而实者泻之。因其偃卧。居其头前。以两手四指挟按颈动脉。久持之。卷而切。推下至缺盆中。而复止如前。热去乃止。此所谓推而散之者也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300755,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '18、大热遍身。狂而妄见妄闻妄言。视足阳明及大络取之。虚者补之。血而实者泻之。因其偃卧。居其头前。以两手四指挟按颈动脉。久持之。卷而切。推下至缺盆中。而复止如前。热去乃止。此所谓推而散之者也。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'TZwBUc10zqj');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('vmfXx6ezBAg', 4, '{"title":"第20300756条・刺节真邪第七十五","description":"<p>19、黄帝曰。有一脉生数十病者。或痛。或痈。或热。或寒。或痒。或痹。或不仁。变化无穷。其故何也。岐伯曰。此皆邪气之所生也。黄帝曰。余闻气者。有真气。有正气。有邪气。何谓真气。岐伯曰。真气者。所受于天。与谷气并而充身也。正气者。正风也。从一方来。非实风。又非虚风也。邪气者。虚风之贼伤人也。其中人也深。不能自去。正风者。其中人也浅。合而自去。其气来柔弱。不能胜真气。故自去。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300756,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '19、黄帝曰。有一脉生数十病者。或痛。或痈。或热。或寒。或痒。或痹。或不仁。变化无穷。其故何也。岐伯曰。此皆邪气之所生也。黄帝曰。余闻气者。有真气。有正气。有邪气。何谓真气。岐伯曰。真气者。所受于天。与谷气并而充身也。正气者。正风也。从一方来。非实风。又非虚风也。邪气者。虚风之贼伤人也。其中人也深。不能自去。正风者。其中人也浅。合而自去。其气来柔弱。不能胜真气。故自去。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'TZwBUc10zqj');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Cg9gSaw0xxL', 4, '{"title":"第20300757条・刺节真邪第七十五","description":"<p>20、虚邪之中人也。洒晰动形。起毫毛而发腠理。其入深。内搏于骨。则为骨痹。搏于筋。则为筋挛。搏于脉中。则为血闭。不通则为痈。搏于肉。与卫气相搏。阳胜者。则为热。阴胜者。则为寒。寒则真气去。去则虚。虚则寒搏于皮肤之间。其气外发。腠理开。毫毛摇。气往来行。则为痒。留而不去。则痹。卫气不行。则为不仁。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300757,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '20、虚邪之中人也。洒晰动形。起毫毛而发腠理。其入深。内搏于骨。则为骨痹。搏于筋。则为筋挛。搏于脉中。则为血闭。不通则为痈。搏于肉。与卫气相搏。阳胜者。则为热。阴胜者。则为寒。寒则真气去。去则虚。虚则寒搏于皮肤之间。其气外发。腠理开。毫毛摇。气往来行。则为痒。留而不去。则痹。卫气不行。则为不仁。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'TZwBUc10zqj');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('y2GwHzUgcfG', 4, '{"title":"第20300758条・刺节真邪第七十五","description":"<p>21、虚邪偏容于身半。其入深。内居荣卫。荣卫稍衰。则真气去。邪气独留。发为偏枯。其邪气浅者。脉偏痛。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300758,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '21、虚邪偏容于身半。其入深。内居荣卫。荣卫稍衰。则真气去。邪气独留。发为偏枯。其邪气浅者。脉偏痛。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'TZwBUc10zqj');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('P104bZo8NrV', 4, '{"title":"第20300759条・刺节真邪第七十五","description":"<p>22、虚邪之入于身也深。寒与热相搏。久留而内着。寒胜其热。则骨疼肉枯。热胜其寒。则烂肉腐肌为脓。内伤骨。内伤骨为骨蚀。有所疾前筋。筋屈不得伸。邪气居其间而不反。发为筋溜。有所结。气归之。卫气留之。不得反。津液久留。合而为肠溜。久者。数岁乃成。以手按之柔。已有所结。气归之。津液留之。邪气中之。凝结日以易甚。连以聚居。为昔瘤。以手按之坚。有所结。深中骨。气因于骨。骨与气并。日以益大。则为骨疽。有所结。中于肉。宗气归之。邪留而不去。有热则化而为脓。无热则为肉疽。凡此数气者。其发无常处。而有常名也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300759,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '22、虚邪之入于身也深。寒与热相搏。久留而内着。寒胜其热。则骨疼肉枯。热胜其寒。则烂肉腐肌为脓。内伤骨。内伤骨为骨蚀。有所疾前筋。筋屈不得伸。邪气居其间而不反。发为筋溜。有所结。气归之。卫气留之。不得反。津液久留。合而为肠溜。久者。数岁乃成。以手按之柔。已有所结。气归之。津液留之。邪气中之。凝结日以易甚。连以聚居。为昔瘤。以手按之坚。有所结。深中骨。气因于骨。骨与气并。日以益大。则为骨疽。有所结。中于肉。宗气归之。邪留而不去。有热则化而为脓。无热则为肉疽。凡此数气者。其发无常处。而有常名也。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'TZwBUc10zqj');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('YZUGp4lv9pz', 4, '{"title":"第20300760条・卫气行第七十六","description":"<p>1、黄帝问于岐伯曰。愿闻卫气之行。出入之合。何如。岐伯曰。岁有十二月。日有十二辰。子午为经。卯酉为纬。天周二十八宿。而一面七星。四七二十八星。房昴为纬。虚张为经。是故房至毕为阳。昴至心为阴。阳主昼。阴主夜。故卫气之行。一日一夜五十周于身。昼日行于阳二十五周。夜行于阴二十五周。周于五藏。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300760,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '1、黄帝问于岐伯曰。愿闻卫气之行。出入之合。何如。岐伯曰。岁有十二月。日有十二辰。子午为经。卯酉为纬。天周二十八宿。而一面七星。四七二十八星。房昴为纬。虚张为经。是故房至毕为阳。昴至心为阴。阳主昼。阴主夜。故卫气之行。一日一夜五十周于身。昼日行于阳二十五周。夜行于阴二十五周。周于五藏。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'sbvK7xTIuhO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('3iUwPQALuiU', 4, '{"title":"第20300761条・卫气行第七十六","description":"<p>2、是故平旦阴尽。阳气出于目。目张则气上行于头。循项下足太阳。循背下至小指之端。其散者。别于目锐眦。下手太阳。下至手小指之间外侧。其散者。别于目锐眦。下足少阳。注小指次指之间。以上循手少阳之分侧。下至小指之间。别者以上至耳前。合于颔脉。注足阳明以下行。至跗上。入五指之间。其散者。从耳下下手阳明。入大指之间。入掌中。其至于足也。入足心。出内踝。下行阴分。复合于目。故为一周。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300761,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2、是故平旦阴尽。阳气出于目。目张则气上行于头。循项下足太阳。循背下至小指之端。其散者。别于目锐眦。下手太阳。下至手小指之间外侧。其散者。别于目锐眦。下足少阳。注小指次指之间。以上循手少阳之分侧。下至小指之间。别者以上至耳前。合于颔脉。注足阳明以下行。至跗上。入五指之间。其散者。从耳下下手阳明。入大指之间。入掌中。其至于足也。入足心。出内踝。下行阴分。复合于目。故为一周。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'sbvK7xTIuhO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('hVGnRQQ2Z3S', 4, '{"title":"第20300762条・卫气行第七十六","description":"<p>3、是故日行一舍。人气行一周与十分身之八。日行二舍。人气行三周于身与十分身之六。日行三舍。人气行于身五周与十分身之四。日行四舍。人气行于身七周与十分身之二。日行五舍。人气行于身九周。日行六舍。人气行于身十周与十分身之八。日行七舍。人气行于身十二周在身与十分身之六。日行十四舍。人气二十五周于身有奇分与十分身之二。阳尽于阴。阴受气矣。其始入于阴。常从足少阴注于肾。肾注于心。心注于肺。肺注于肝。肝注于脾。脾复注于肾为周。是故夜行一舍。人气行于阴藏一周与十分藏之八。亦如阳行之二十五周。而复合于目。阴阳一日一夜。合有奇分十分身之四。与十分藏之二。是故人之所以卧起之时。有早晏者。奇分不尽故也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300762,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '3、是故日行一舍。人气行一周与十分身之八。日行二舍。人气行三周于身与十分身之六。日行三舍。人气行于身五周与十分身之四。日行四舍。人气行于身七周与十分身之二。日行五舍。人气行于身九周。日行六舍。人气行于身十周与十分身之八。日行七舍。人气行于身十二周在身与十分身之六。日行十四舍。人气二十五周于身有奇分与十分身之二。阳尽于阴。阴受气矣。其始入于阴。常从足少阴注于肾。肾注于心。心注于肺。肺注于肝。肝注于脾。脾复注于肾为周。是故夜行一舍。人气行于阴藏一周与十分藏之八。亦如阳行之二十五周。而复合于目。阴阳一日一夜。合有奇分十分身之四。与十分藏之二。是故人之所以卧起之时。有早晏者。奇分不尽故也。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'sbvK7xTIuhO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('LR6czUXoYO3', 4, '{"title":"第20300763条・卫气行第七十六","description":"<p>4、黄帝曰。卫气之在于身也。上下往来不以期。候气而刺之。奈何。伯高曰。分有多少。日有长短。春秋冬夏。各有分理。然后常以平旦为纪。以夜尽为始。是故一日一夜。水下百刻。二十五刻者。半日之度也。常如是毋已。日入而止。随日之长短。各以为纪而刺之。谨候其时。病可与期。失时反候者。百病不治。故曰。刺实者。刺其来也。刺虚者。刺其去也。此言气存亡之时。以候虚实而刺之。是故谨候气之所在而刺之。是谓逢时。在于三阳。必候其气在于阳而刺之。病在于三阴。必候其气在阴分而刺之。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300763,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '4、黄帝曰。卫气之在于身也。上下往来不以期。候气而刺之。奈何。伯高曰。分有多少。日有长短。春秋冬夏。各有分理。然后常以平旦为纪。以夜尽为始。是故一日一夜。水下百刻。二十五刻者。半日之度也。常如是毋已。日入而止。随日之长短。各以为纪而刺之。谨候其时。病可与期。失时反候者。百病不治。故曰。刺实者。刺其来也。刺虚者。刺其去也。此言气存亡之时。以候虚实而刺之。是故谨候气之所在而刺之。是谓逢时。在于三阳。必候其气在于阳而刺之。病在于三阴。必候其气在阴分而刺之。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'sbvK7xTIuhO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('CMvh2aM2mAg', 4, '{"title":"第20300764条・卫气行第七十六","description":"<p>5、水下一刻。人气在太阳。水下二刻。人气在少阳。水下三刻。人气在阳明。水下四刻。人气在阴分。水下五刻。人气在太阳。水下六刻。人气在少阳。水下七刻。人气在阳明。水下八刻。人气在阴分。水下九刻。人气在太阳。水下十刻。人气在少阳。水下十一刻。人气在阳明。水下十二刻。人气在阴分。水下十三刻。人气在太阳。水下十四刻。人气在少阳。水下十五刻。人气在阳明。水下十六刻。人气在阴分。水下十七刻。人气在太阳。水下十八刻。人气在少阳。水下十九刻。人气在阳明。水下二十刻。人气在阴分。水下二十一刻。人气在太阳。水下二十二刻。人气在少阳。水下二十三刻。人气在阳明。水下二十四刻。人气在阴分。水下二十五刻。人气在太阳。此半日之度也。从房至毕一十四舍水下五十刻。日行半度。回行一舍。水下三刻与七分刻之四。大要曰。常以日之加于宿上也。人气在太阳。是故日行一舍。人气行三阳行与阴分。常如是无已。天与地同纪。纷纷纷纷。终而复始。一日一夜水下百刻而尽矣。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300764,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '5、水下一刻。人气在太阳。水下二刻。人气在少阳。水下三刻。人气在阳明。水下四刻。人气在阴分。水下五刻。人气在太阳。水下六刻。人气在少阳。水下七刻。人气在阳明。水下八刻。人气在阴分。水下九刻。人气在太阳。水下十刻。人气在少阳。水下十一刻。人气在阳明。水下十二刻。人气在阴分。水下十三刻。人气在太阳。水下十四刻。人气在少阳。水下十五刻。人气在阳明。水下十六刻。人气在阴分。水下十七刻。人气在太阳。水下十八刻。人气在少阳。水下十九刻。人气在阳明。水下二十刻。人气在阴分。水下二十一刻。人气在太阳。水下二十二刻。人气在少阳。水下二十三刻。人气在阳明。水下二十四刻。人气在阴分。水下二十五刻。人气在太阳。此半日之度也。从房至毕一十四舍水下五十刻。日行半度。回行一舍。水下三刻与七分刻之四。大要曰。常以日之加于宿上也。人气在太阳。是故日行一舍。人气行三阳行与阴分。常如是无已。天与地同纪。纷纷纷纷。终而复始。一日一夜水下百刻而尽矣。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'sbvK7xTIuhO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('1LwqJLF7rWr', 4, '{"title":"第20300765条・九宫八风第七十七","description":"<p>1、太一常以冬至之日。居叶蛰之宫四十六日。明日居天留四十六日。明日居仓门四十六日。明日居阴洛四十五日。明日居天宫四十六日。明日居玄委四十六日。明日居仓果四十六日。明日居新洛四十五日。明日复居叶蛰之宫。曰冬至矣。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300765,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '1、太一常以冬至之日。居叶蛰之宫四十六日。明日居天留四十六日。明日居仓门四十六日。明日居阴洛四十五日。明日居天宫四十六日。明日居玄委四十六日。明日居仓果四十六日。明日居新洛四十五日。明日复居叶蛰之宫。曰冬至矣。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'kOfW6V2VYa7');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('7WrdlZ5AMgL', 4, '{"title":"第20300766条・九宫八风第七十七","description":"<p>2、太一日游。以冬至之日。居叶蛰之宫。数所在日。从一处至九日。复返于一。常如是无已。终而复始。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300766,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2、太一日游。以冬至之日。居叶蛰之宫。数所在日。从一处至九日。复返于一。常如是无已。终而复始。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'kOfW6V2VYa7');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('AYE6c6BDoWJ', 4, '{"title":"第20300767条・九宫八风第七十七","description":"<p>3、太一移日。天必应之以风雨。以其日风雨则吉。岁美民安少病矣。先之则多雨。后之则多汗。太一在冬至之日有变。占在君。太一在春分之日有变。占在相。太一在中宫之日有变。占在吏。太一在秋分之日有变。占在将。太一在夏至之日有变。占在百姓。所谓有变者。太一居五宫之日。病风折树木。扬沙石。各以其所主。占贵贱。因视风所从来而占之。风从其所居之乡来为实风。主生。长养万物。从其冲后来为虚风。伤人者也。主杀。主害者。谨候虚风而避之。故圣人日避虚邪之道。如避矢石然。邪弗能害。此之谓也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300767,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '3、太一移日。天必应之以风雨。以其日风雨则吉。岁美民安少病矣。先之则多雨。后之则多汗。太一在冬至之日有变。占在君。太一在春分之日有变。占在相。太一在中宫之日有变。占在吏。太一在秋分之日有变。占在将。太一在夏至之日有变。占在百姓。所谓有变者。太一居五宫之日。病风折树木。扬沙石。各以其所主。占贵贱。因视风所从来而占之。风从其所居之乡来为实风。主生。长养万物。从其冲后来为虚风。伤人者也。主杀。主害者。谨候虚风而避之。故圣人日避虚邪之道。如避矢石然。邪弗能害。此之谓也。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'kOfW6V2VYa7');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('bQqVdycn10B', 4, '{"title":"第20300768条・九宫八风第七十七","description":"<p>4、是故太一入徙立于中宫。乃朝八风。以占吉凶也。风从南方来。名曰大弱风。其伤人也。内舍于心。外在于脉。气主热。风从西南方来。名曰谋风。其伤人也。内舍于脾。外在于肌。其气主为弱。风从西方来。名曰刚风。其伤人也。内舍于肺。外在于皮肤。其气主为燥。风从西北方来。名曰折风。其伤人也。内舍于小肠。外在于手太阳脉。脉绝则溢。脉闭则结不通。善暴死。风从北方来。名曰大刚风。其伤人也。内舍于肾。外在于骨与肩背之膂筋。其气主为寒也。风从东北方来。名曰凶风。其伤人也。内舍于大肠。外在于两胁腋骨下及肢节。风从东方来。名曰婴兀风。其伤人也。内舍于肝。外在于筋纽。其气主为身湿。风从东南方来。名曰弱风。其伤人也。内舍于胃。外在肌肉。其气主体重。此八风皆从其虚之乡来。乃能病人。三虚相搏。则为暴病卒死。两实一虚。病则为淋露寒热。犯其两湿之地。则为痿。故圣人避风。如避矢石焉。其有三虚而偏中于邪风。则为仆偏枯矣。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300768,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '4、是故太一入徙立于中宫。乃朝八风。以占吉凶也。风从南方来。名曰大弱风。其伤人也。内舍于心。外在于脉。气主热。风从西南方来。名曰谋风。其伤人也。内舍于脾。外在于肌。其气主为弱。风从西方来。名曰刚风。其伤人也。内舍于肺。外在于皮肤。其气主为燥。风从西北方来。名曰折风。其伤人也。内舍于小肠。外在于手太阳脉。脉绝则溢。脉闭则结不通。善暴死。风从北方来。名曰大刚风。其伤人也。内舍于肾。外在于骨与肩背之膂筋。其气主为寒也。风从东北方来。名曰凶风。其伤人也。内舍于大肠。外在于两胁腋骨下及肢节。风从东方来。名曰婴兀风。其伤人也。内舍于肝。外在于筋纽。其气主为身湿。风从东南方来。名曰弱风。其伤人也。内舍于胃。外在肌肉。其气主体重。此八风皆从其虚之乡来。乃能病人。三虚相搏。则为暴病卒死。两实一虚。病则为淋露寒热。犯其两湿之地。则为痿。故圣人避风。如避矢石焉。其有三虚而偏中于邪风。则为仆偏枯矣。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'kOfW6V2VYa7');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('7Qrju3dTAj3', 4, '{"title":"第20300769条・九针论第七十八","description":"<p>1、黄帝曰。余闻九针于夫子。众多博大矣。余犹不能寤。敢问九针焉生。何因而有名。岐伯曰。九针者。天地之大数也。始于一而终于九。故曰。一以法天。二以法地。三以法人。四以法时。五以法音。六以法律。七以法星。八以法风。九以法野。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300769,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '1、黄帝曰。余闻九针于夫子。众多博大矣。余犹不能寤。敢问九针焉生。何因而有名。岐伯曰。九针者。天地之大数也。始于一而终于九。故曰。一以法天。二以法地。三以法人。四以法时。五以法音。六以法律。七以法星。八以法风。九以法野。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'bc4V6IH91w4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('S0zQ16oc6a4', 4, '{"title":"第20300770条・九针论第七十八","description":"<p>2、黄帝曰。以针应九之数。奈何。岐伯曰。夫圣人之起天地之数也。一而九之。故以立九野。九而九之。九九八十一。以起黄钟数焉。以针应数也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300770,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2、黄帝曰。以针应九之数。奈何。岐伯曰。夫圣人之起天地之数也。一而九之。故以立九野。九而九之。九九八十一。以起黄钟数焉。以针应数也。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'bc4V6IH91w4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('TQg4LRvlGRl', 4, '{"title":"第20300771条・九针论第七十八","description":"<p>3、一者。天也。天者。阳也。五藏之应天者肺。肺者。五藏六府之盖也。皮者。肺之合也。人之阳也。故为之治针。必以大其头而锐其末。令无得深入而阳气出。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300771,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '3、一者。天也。天者。阳也。五藏之应天者肺。肺者。五藏六府之盖也。皮者。肺之合也。人之阳也。故为之治针。必以大其头而锐其末。令无得深入而阳气出。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'bc4V6IH91w4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('k2hxvLpR4uj', 4, '{"title":"第20300772条・九针论第七十八","description":"<p>4、二者。地也。人之所以应土者。肉也。故为之治针。必筩其身而员其末。令无得伤肉分。伤则气得竭。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300772,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '4、二者。地也。人之所以应土者。肉也。故为之治针。必筩其身而员其末。令无得伤肉分。伤则气得竭。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'bc4V6IH91w4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('JlU3kfaybc1', 4, '{"title":"第20300773条・九针论第七十八","description":"<p>5、三者。人也。人之所以成生者。血脉也。故为之治针。必大其身而员其末。令可以按脉物陷。以致其气。令邪气独出。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300773,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '5、三者。人也。人之所以成生者。血脉也。故为之治针。必大其身而员其末。令可以按脉物陷。以致其气。令邪气独出。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'bc4V6IH91w4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('6TVum7VAct9', 4, '{"title":"第20300774条・九针论第七十八","description":"<p>6、四者。时也。时者。四时八风之客于经络之中。为瘤病者也。故为之治针。必筩其身而锋其末。令可以泻热出血。而痼病竭。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300774,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '6、四者。时也。时者。四时八风之客于经络之中。为瘤病者也。故为之治针。必筩其身而锋其末。令可以泻热出血。而痼病竭。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'bc4V6IH91w4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('KMRhzY0Pq5V', 4, '{"title":"第20300775条・九针论第七十八","description":"<p>7、五者。音也。音者。冬夏之分。分于子午。阴与阳别。寒与热争。两气相搏。合为痈脓者也。故为之治针。必令其末如剑锋。可以取大脓。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300775,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '7、五者。音也。音者。冬夏之分。分于子午。阴与阳别。寒与热争。两气相搏。合为痈脓者也。故为之治针。必令其末如剑锋。可以取大脓。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'bc4V6IH91w4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('P9bKHrtLLBb', 4, '{"title":"第20300776条・九针论第七十八","description":"<p>8、六者。律也。律者。调阴阳四时而合十二经脉。虚邪客于经络而为暴痹者也。故为之治针。必令尖如厘。且员其锐。中身微大。以取暴气。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300776,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '8、六者。律也。律者。调阴阳四时而合十二经脉。虚邪客于经络而为暴痹者也。故为之治针。必令尖如厘。且员其锐。中身微大。以取暴气。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'bc4V6IH91w4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('zJjo0VvLmdA', 4, '{"title":"第20300777条・九针论第七十八","description":"<p>9、七者。星也。星者。人之七窍。邪之所客于经。而为痛痹。合于经络者也。故为之治针。令尖如蚊虻喙。静以徐往。微以久留。正气因之。真邪俱往。出针而养者也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300777,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '9、七者。星也。星者。人之七窍。邪之所客于经。而为痛痹。合于经络者也。故为之治针。令尖如蚊虻喙。静以徐往。微以久留。正气因之。真邪俱往。出针而养者也。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'bc4V6IH91w4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('fhjZIXG3Jj9', 4, '{"title":"第20300778条・九针论第七十八","description":"<p>10、八者。风也。风者。人之股肱八节也。八正之虚风。八风伤人。内舍于骨解腰脊节腠理之间为深痹也。故为之治针。必长其身。锋其末。可以取深邪远痹。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300778,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '10、八者。风也。风者。人之股肱八节也。八正之虚风。八风伤人。内舍于骨解腰脊节腠理之间为深痹也。故为之治针。必长其身。锋其末。可以取深邪远痹。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'bc4V6IH91w4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('H92omHIDpSc', 4, '{"title":"第20300779条・九针论第七十八","description":"<p>11、九者。野也。野者。人之节解皮肤之间也。淫邪流溢于身。如风水之状。而留不能过于机关大节者也。故为之治针。令尖如挺。其锋微员。以取大气之不能过于关节者也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300779,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '11、九者。野也。野者。人之节解皮肤之间也。淫邪流溢于身。如风水之状。而留不能过于机关大节者也。故为之治针。令尖如挺。其锋微员。以取大气之不能过于关节者也。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'bc4V6IH91w4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('g2xQPZp08DA', 4, '{"title":"第20300780条・九针论第七十八","description":"<p>12、黄帝曰。针之长短有数乎。岐伯曰。一曰铁针者。取法于巾针。去末寸半。卒锐之。长一寸六分。主热在头身也。二曰员针。取法于絮针。其身而卵其锋。长一寸六分。主治分间气。三曰提针。取法于黍粟之锐。长三寸半。主按脉取气。令邪出。四曰锋针。取法于絮针。其身。锋其末。长一寸六分。主痈热出血。五曰铍针。取法于剑锋。广二分半。长四寸。主大痈脓。两热争者也。六曰员利针。取法于厘针。微大其末。反小其身。令可深内也。长一寸六分。主取痈痹者也。七曰毫针。取注于毫毛。长一寸六分。主寒热痛痹在络者也。八曰长针。取法于綦针。长七寸。主取深邪远痹者也。九曰大针。取法于锋针。其锋微员。长四寸。主取大气不出关节者也。针形毕矣。此九针大小长短法也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300780,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '12、黄帝曰。针之长短有数乎。岐伯曰。一曰铁针者。取法于巾针。去末寸半。卒锐之。长一寸六分。主热在头身也。二曰员针。取法于絮针。其身而卵其锋。长一寸六分。主治分间气。三曰提针。取法于黍粟之锐。长三寸半。主按脉取气。令邪出。四曰锋针。取法于絮针。其身。锋其末。长一寸六分。主痈热出血。五曰铍针。取法于剑锋。广二分半。长四寸。主大痈脓。两热争者也。六曰员利针。取法于厘针。微大其末。反小其身。令可深内也。长一寸六分。主取痈痹者也。七曰毫针。取注于毫毛。长一寸六分。主寒热痛痹在络者也。八曰长针。取法于綦针。长七寸。主取深邪远痹者也。九曰大针。取法于锋针。其锋微员。长四寸。主取大气不出关节者也。针形毕矣。此九针大小长短法也。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'bc4V6IH91w4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('1ntNO6i1nvT', 4, '{"title":"第20300781条・九针论第七十八","description":"<p>13、黄帝曰。愿闻身形。应九野。奈何。岐伯曰。请言身形之应九野也。左足应立春。其日戊寅己丑。左胁应春分。其日乙卯。左手应立夏。其日戊辰己巳。膺喉首头应夏至。其日丙午。右手应立秋。其中戊申己末。右胁应秋分。其日辛酉。右足应立冬。其日戊戌己亥。腰尻下窍应冬至。其日壬子。六府下三藏应中州。其大禁。大禁太一所在之日。及诸戊己。凡此九者。善候八正所在之处。所主左右上下身体有痈肿者。欲治之。无以其所直之日溃治之。是谓天忌日也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300781,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '13、黄帝曰。愿闻身形。应九野。奈何。岐伯曰。请言身形之应九野也。左足应立春。其日戊寅己丑。左胁应春分。其日乙卯。左手应立夏。其日戊辰己巳。膺喉首头应夏至。其日丙午。右手应立秋。其中戊申己末。右胁应秋分。其日辛酉。右足应立冬。其日戊戌己亥。腰尻下窍应冬至。其日壬子。六府下三藏应中州。其大禁。大禁太一所在之日。及诸戊己。凡此九者。善候八正所在之处。所主左右上下身体有痈肿者。欲治之。无以其所直之日溃治之。是谓天忌日也。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'bc4V6IH91w4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Z78yfpPXi8N', 4, '{"title":"第20300782条・九针论第七十八","description":"<p>14、形东志苦。病生于脉。治之于灸刺。形苦志东。病生于筋。治之以熨引。形东志东。病生于肉。治之以针石。形苦志苦。病生于咽喝。治之以甘药。形数惊恐。筋脉不通。病生于不仁。治之以按摩谬药。是谓形。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300782,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '14、形东志苦。病生于脉。治之于灸刺。形苦志东。病生于筋。治之以熨引。形东志东。病生于肉。治之以针石。形苦志苦。病生于咽喝。治之以甘药。形数惊恐。筋脉不通。病生于不仁。治之以按摩谬药。是谓形。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'bc4V6IH91w4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Whb264yR0yE', 4, '{"title":"第20300783条・九针论第七十八","description":"<p>15、五藏气。心主噫。肺主咳。肝主语。脾主吞。肾主欠。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300783,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '15、五藏气。心主噫。肺主咳。肝主语。脾主吞。肾主欠。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'bc4V6IH91w4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('VEnqoMJg4hn', 4, '{"title":"第20300784条・九针论第七十八","description":"<p>16、六府气。胆为怒。胃为气逆秽。大肠小肠为泄。膀胱不约为遗溺。下焦溢为水。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300784,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '16、六府气。胆为怒。胃为气逆秽。大肠小肠为泄。膀胱不约为遗溺。下焦溢为水。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'bc4V6IH91w4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ommiso1Op4J', 4, '{"title":"第20300785条・九针论第七十八","description":"<p>17、五味。酸入肝。辛入肺。苦入心。甘入脾。咸入肾。淡入胃。是谓五味。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300785,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '17、五味。酸入肝。辛入肺。苦入心。甘入脾。咸入肾。淡入胃。是谓五味。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'bc4V6IH91w4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('cu57AiUHPrl', 4, '{"title":"第20300786条・九针论第七十八","description":"<p>18、五并。精气并肝则忧。并心则喜。并肺则悲。并肾则恐。并脾则畏。是谓五精之气。并于藏也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300786,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '18、五并。精气并肝则忧。并心则喜。并肺则悲。并肾则恐。并脾则畏。是谓五精之气。并于藏也。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'bc4V6IH91w4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('05sVNiSHDR1', 4, '{"title":"第20300787条・九针论第七十八","description":"<p>19、五恶。肝恶风。心恶热。肺恶寒。肾恶燥。脾恶湿。此五藏气所恶也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300787,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '19、五恶。肝恶风。心恶热。肺恶寒。肾恶燥。脾恶湿。此五藏气所恶也。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'bc4V6IH91w4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Ou7WrBMwgC0', 4, '{"title":"第20300788条・九针论第七十八","description":"<p>20、五液。心主汗。肝主泣。肺主涕。肾主唾。脾主液。此五液所出也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300788,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '20、五液。心主汗。肝主泣。肺主涕。肾主唾。脾主液。此五液所出也。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'bc4V6IH91w4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('f9kmwNhJ2Vq', 4, '{"title":"第20300789条・九针论第七十八","description":"<p>21、五劳。久视伤血。久卧伤气。久坐伤肉。久立伤骨。久行伤筋。此五久劳所病也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300789,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '21、五劳。久视伤血。久卧伤气。久坐伤肉。久立伤骨。久行伤筋。此五久劳所病也。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'bc4V6IH91w4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('iViDXUkcgOy', 4, '{"title":"第20300790条・九针论第七十八","description":"<p>22、五走。酸走筋。辛走气。苦走血。咸走骨。甘走肉。是谓五走也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300790,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '22、五走。酸走筋。辛走气。苦走血。咸走骨。甘走肉。是谓五走也。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'bc4V6IH91w4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('AzhS7c101wq', 4, '{"title":"第20300791条・九针论第七十八","description":"<p>23、五裁。病在筋。无食酸。病在气。无食辛。病在骨。无食咸。病在血。无食苦。病在肉。无食甘。口嗜而欲食之。不可多也。必自裁也。命曰五裁。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300791,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '23、五裁。病在筋。无食酸。病在气。无食辛。病在骨。无食咸。病在血。无食苦。病在肉。无食甘。口嗜而欲食之。不可多也。必自裁也。命曰五裁。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'bc4V6IH91w4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('YoVJS2ex40g', 4, '{"title":"第20300792条・九针论第七十八","description":"<p>24、五发。阴病发于骨。阳病发于血。阴病发于肉。阳病发于冬。阴病发于夏。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300792,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '24、五发。阴病发于骨。阳病发于血。阴病发于肉。阳病发于冬。阴病发于夏。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'bc4V6IH91w4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('uk1DiQZ3BAa', 4, '{"title":"第20300793条・九针论第七十八","description":"<p>25、五邪。邪入于阳。则为狂。邪入于阴。则为血瘅。邪入于阳。转则为癫疾。邪入于阴。转则为瘖。阳入于阴。病静。阴出之于阳。病喜怒。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300793,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '25、五邪。邪入于阳。则为狂。邪入于阴。则为血瘅。邪入于阳。转则为癫疾。邪入于阴。转则为瘖。阳入于阴。病静。阴出之于阳。病喜怒。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'bc4V6IH91w4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Z9bixB1rBeb', 4, '{"title":"第20300794条・九针论第七十八","description":"<p>26、五藏。心藏神。肺藏魄。肝藏魂。脾藏意。肾藏精志也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300794,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '26、五藏。心藏神。肺藏魄。肝藏魂。脾藏意。肾藏精志也。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'bc4V6IH91w4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('HzCDMZTki6L', 4, '{"title":"第20300795条・九针论第七十八","description":"<p>27、五主。心主脉。肺主皮。肝主筋。脾主肌。肾主骨。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300795,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '27、五主。心主脉。肺主皮。肝主筋。脾主肌。肾主骨。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'bc4V6IH91w4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('uMJgKJ1afZD', 4, '{"title":"第20300796条・九针论第七十八","description":"<p>28、阳明多血多气。太阳多血少气。少阳多气少血。太阴多血少气。厥阴多血少气。少阴多气少血。故曰刺阳明出血气。刺太阳出血恶气。刺少阳出气恶血。刺太阴出血恶气。刺厥阴出血恶气。刺少阴出气恶血也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300796,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '28、阳明多血多气。太阳多血少气。少阳多气少血。太阴多血少气。厥阴多血少气。少阴多气少血。故曰刺阳明出血气。刺太阳出血恶气。刺少阳出气恶血。刺太阴出血恶气。刺厥阴出血恶气。刺少阴出气恶血也。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'bc4V6IH91w4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('XskBotZ7JVf', 4, '{"title":"第20300797条・九针论第七十八","description":"<p>29、足阳明太阴为里表。少阳厥阴为表里。太阳少阴为表里。是谓足之阴阳也。手阳明太阴为表里。少阳心主为表里。太阳少阴为表里。是谓手之阴阳也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300797,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '29、足阳明太阴为里表。少阳厥阴为表里。太阳少阴为表里。是谓足之阴阳也。手阳明太阴为表里。少阳心主为表里。太阳少阴为表里。是谓手之阴阳也。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'bc4V6IH91w4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('43DG1RBl6Md', 4, '{"title":"第20300798条・岁露论第七十九","description":"<p>1、黄帝问于岐伯曰。经言夏日伤暑。秋病疟。疟之发以时。其故何也。岐伯对曰。邪客于风府。病循膂而下。卫气一日一夜。常大会于风府。其明日日下一节。故其日作晏。此其先客于脊背也。故每至于风府则腠理开。腠理开则邪气入。邪气入则病作。此所以日作尚晏也。卫气之行风府。日下一节。二十一日下至尾底。二十二日入脊内。注于伏冲之脉。其行九日。出于缺盆之中。其气上行。故其病稍益至。其内搏于五藏。横连募原。其道远。其气深。其行迟。不能日作。故次日乃蓄积而作焉。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300798,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '1、黄帝问于岐伯曰。经言夏日伤暑。秋病疟。疟之发以时。其故何也。岐伯对曰。邪客于风府。病循膂而下。卫气一日一夜。常大会于风府。其明日日下一节。故其日作晏。此其先客于脊背也。故每至于风府则腠理开。腠理开则邪气入。邪气入则病作。此所以日作尚晏也。卫气之行风府。日下一节。二十一日下至尾底。二十二日入脊内。注于伏冲之脉。其行九日。出于缺盆之中。其气上行。故其病稍益至。其内搏于五藏。横连募原。其道远。其气深。其行迟。不能日作。故次日乃蓄积而作焉。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'Hv941DEVS9h');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('LLYv2XVQrq0', 4, '{"title":"第20300799条・岁露论第七十九","description":"<p>2、黄帝曰。卫气每至于风府。腠理乃发。发则邪入焉。其卫气日下一节。则不当风府。奈何。岐伯曰。风府无常。卫气之所应。必开其腠理。气之所舍节。则其府也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300799,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2、黄帝曰。卫气每至于风府。腠理乃发。发则邪入焉。其卫气日下一节。则不当风府。奈何。岐伯曰。风府无常。卫气之所应。必开其腠理。气之所舍节。则其府也。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'Hv941DEVS9h');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('hm5z6Vp22va', 4, '{"title":"第20300800条・岁露论第七十九","description":"<p>3、黄帝曰。善。夫风之与疟也。相与同类。而风常在。而疟特以时休。何也。岐伯曰。风气留其处。疟气随经络。沉以内搏。故卫气应。乃作也。帝曰。善。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300800,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '3、黄帝曰。善。夫风之与疟也。相与同类。而风常在。而疟特以时休。何也。岐伯曰。风气留其处。疟气随经络。沉以内搏。故卫气应。乃作也。帝曰。善。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'Hv941DEVS9h');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('txw6qd69CxZ', 4, '{"title":"第20300801条・岁露论第七十九","description":"<p>4、黄帝问于少师曰。余闻四时八风之中人也。故有寒暑。寒则皮肤急而腠理闭。暑则皮肤缓而腠理开。贼风邪气。因得以入乎。将必须八正虚邪。乃能伤人乎。少师答曰。不然。贼风邪气之中人也。不得以时。然必因其开也。其入深。其内极病。其病人也。卒暴。因其闭也。其入浅以留。其病也。徐以迟。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300801,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '4、黄帝问于少师曰。余闻四时八风之中人也。故有寒暑。寒则皮肤急而腠理闭。暑则皮肤缓而腠理开。贼风邪气。因得以入乎。将必须八正虚邪。乃能伤人乎。少师答曰。不然。贼风邪气之中人也。不得以时。然必因其开也。其入深。其内极病。其病人也。卒暴。因其闭也。其入浅以留。其病也。徐以迟。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'Hv941DEVS9h');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('E2Eq3ircPWA', 4, '{"title":"第20300802条・岁露论第七十九","description":"<p>5、黄帝曰。有寒温和适。腠理不开。然有卒病者。其故何也。少师答曰。帝弗知邪入乎。虽平居其腠理开闭缓急。其故常有时也。黄帝曰。可得闻乎。少师曰。人与天地相参也。与日月相应也。故月满则海水西盛。人血气积。肌肉充。皮肤致。毛发坚。腠理郗。烟垢着。当是之时。虽遇贼风。其入浅不深。至其月郭空。则海水东盛。人气血虚。其卫气去。形独居。肌肉减。皮肤纵。腠理开。毛发残。胶理薄。烟垢落。当是之时。遇贼风则其入深。其病人也。卒暴。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300802,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '5、黄帝曰。有寒温和适。腠理不开。然有卒病者。其故何也。少师答曰。帝弗知邪入乎。虽平居其腠理开闭缓急。其故常有时也。黄帝曰。可得闻乎。少师曰。人与天地相参也。与日月相应也。故月满则海水西盛。人血气积。肌肉充。皮肤致。毛发坚。腠理郗。烟垢着。当是之时。虽遇贼风。其入浅不深。至其月郭空。则海水东盛。人气血虚。其卫气去。形独居。肌肉减。皮肤纵。腠理开。毛发残。胶理薄。烟垢落。当是之时。遇贼风则其入深。其病人也。卒暴。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'Hv941DEVS9h');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('xY107ecFGCK', 4, '{"title":"第20300803条・岁露论第七十九","description":"<p>6、黄帝曰。其有卒然暴死暴病者。何也。少师答曰。三虚者。其死暴疾也。得三实者邪不能伤人也。黄帝曰。愿闻三虚。少师曰。乘年之衰。逢月之空。失时之和。因为贼风所伤。是谓三虚。故论不知三虚。工反为粗。帝曰。愿闻三实。少师曰。逢年之盛。遇月之满。得时之和。虽有贼风邪气。不能危之也。黄帝曰。善乎哉论。明乎哉道。请藏之金匮。命曰三实。然。此一夫之论也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300803,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '6、黄帝曰。其有卒然暴死暴病者。何也。少师答曰。三虚者。其死暴疾也。得三实者邪不能伤人也。黄帝曰。愿闻三虚。少师曰。乘年之衰。逢月之空。失时之和。因为贼风所伤。是谓三虚。故论不知三虚。工反为粗。帝曰。愿闻三实。少师曰。逢年之盛。遇月之满。得时之和。虽有贼风邪气。不能危之也。黄帝曰。善乎哉论。明乎哉道。请藏之金匮。命曰三实。然。此一夫之论也。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'Hv941DEVS9h');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('20k7EC4mJ23', 4, '{"title":"第20300804条・岁露论第七十九","description":"<p>7、黄帝曰。愿闻岁之所以皆同病者。何因而然。少师曰。此八正之候也。黄帝曰。候之奈何。少师曰。候此者。常以冬至之日。太一立于叶蛰之宫。其至也。天必应之以风雨者矣。风雨从南方来者。为虚风。贼伤人者也。其以夜半至也。万民皆卧而弗犯也。故其岁民少病。其以昼至者。万民懈惰而皆中于虚风。故万民多病。虚邪入客于骨而不发于外。至其立春。阳气大发。腠理开。因立春之日。风从西方来。万民又皆中于虚风。此两邪相搏。经气结代者矣。故诸逢其风而遇其雨者。命曰遇岁露焉。因岁之和。而少贼风者。民少病而少死。岁多贼风邪气。寒温不和。则民多病而死矣。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300804,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '7、黄帝曰。愿闻岁之所以皆同病者。何因而然。少师曰。此八正之候也。黄帝曰。候之奈何。少师曰。候此者。常以冬至之日。太一立于叶蛰之宫。其至也。天必应之以风雨者矣。风雨从南方来者。为虚风。贼伤人者也。其以夜半至也。万民皆卧而弗犯也。故其岁民少病。其以昼至者。万民懈惰而皆中于虚风。故万民多病。虚邪入客于骨而不发于外。至其立春。阳气大发。腠理开。因立春之日。风从西方来。万民又皆中于虚风。此两邪相搏。经气结代者矣。故诸逢其风而遇其雨者。命曰遇岁露焉。因岁之和。而少贼风者。民少病而少死。岁多贼风邪气。寒温不和。则民多病而死矣。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'Hv941DEVS9h');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('KdzRNM7AxVE', 4, '{"title":"第20300805条・岁露论第七十九","description":"<p>8、黄帝曰。虚邪之风。其所伤贵贱何如。候之奈何。少师答曰。正月朔日。太一居天留之宫。其日西北风。不雨。人多死矣。正月朔日。平旦北风。春。民多死。正月朔日。平旦北风行。民病多者。十有三也。正月朔日。日中北风。夏。民多死。正月朔日。夕时北风。秋。民多死。终日北风。大病死者十有六。正月朔日。风从南方来。命曰旱乡。从西方来。命曰白骨。将国有殃。人多死亡。正月朔日。风从东方来。发屋。扬沙石。国有大灾也。正月朔日。风从东南方行。春有死亡。正月朔日。天和温不风粜贱。民不病。天寒而风。粜贵。民多病。此所谓候岁之风。残伤人者也。二月丑不风。民多心腹病。三月戌不温。民多寒热。四月已不暑。民多瘅病。十月申不寒。民多暴死。诸所谓风者。皆发屋。折树木。扬沙石起毫毛。发腠理者也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300805,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '8、黄帝曰。虚邪之风。其所伤贵贱何如。候之奈何。少师答曰。正月朔日。太一居天留之宫。其日西北风。不雨。人多死矣。正月朔日。平旦北风。春。民多死。正月朔日。平旦北风行。民病多者。十有三也。正月朔日。日中北风。夏。民多死。正月朔日。夕时北风。秋。民多死。终日北风。大病死者十有六。正月朔日。风从南方来。命曰旱乡。从西方来。命曰白骨。将国有殃。人多死亡。正月朔日。风从东方来。发屋。扬沙石。国有大灾也。正月朔日。风从东南方行。春有死亡。正月朔日。天和温不风粜贱。民不病。天寒而风。粜贵。民多病。此所谓候岁之风。残伤人者也。二月丑不风。民多心腹病。三月戌不温。民多寒热。四月已不暑。民多瘅病。十月申不寒。民多暴死。诸所谓风者。皆发屋。折树木。扬沙石起毫毛。发腠理者也。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'Hv941DEVS9h');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('AiZwhLmLyOP', 4, '{"title":"第20300806条・大惑论第八十","description":"<p>1、黄帝问于岐伯曰。余尝上于清冷之台。中阶而顾。匍匐而前。则惑。余私异之。窃内怪之。独瞑独视。安心定气。久而不解。独博独眩。披发长跪。俛而视之。后久之不已也。卒然自上。何气使然。岐伯对曰。五藏六府之精气。皆上注于目而为之精。精之窠为眼。骨之精为瞳子。筋之精为黑眼。血之精为络。其窠气之精为白眼。肌肉之精为约束。裹撷筋骨血气之精。而与脉并为系。上属于脑。后出于项中。故邪中于项。因逢其身之虚。其入深。则随眼系以入于脑。入于脑则脑转。脑转则引目系急。目系急则目眩以转矣。邪其精。其精所中不相比也。则精散。精散则视歧。视歧见两物。目者。五藏六府之精也。营卫魂魄之所常营也。神气之所生也。故神劳则魂魄散。志意乱。是故瞳子黑眼法于阴。白眼赤脉法于阳也。故阴阳合传而精明也。目者。心使也。心者。神之舍也。故神精乱而不转。卒然见非常处精神魂魄。散不相得。故曰惑也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300806,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '1、黄帝问于岐伯曰。余尝上于清冷之台。中阶而顾。匍匐而前。则惑。余私异之。窃内怪之。独瞑独视。安心定气。久而不解。独博独眩。披发长跪。俛而视之。后久之不已也。卒然自上。何气使然。岐伯对曰。五藏六府之精气。皆上注于目而为之精。精之窠为眼。骨之精为瞳子。筋之精为黑眼。血之精为络。其窠气之精为白眼。肌肉之精为约束。裹撷筋骨血气之精。而与脉并为系。上属于脑。后出于项中。故邪中于项。因逢其身之虚。其入深。则随眼系以入于脑。入于脑则脑转。脑转则引目系急。目系急则目眩以转矣。邪其精。其精所中不相比也。则精散。精散则视歧。视歧见两物。目者。五藏六府之精也。营卫魂魄之所常营也。神气之所生也。故神劳则魂魄散。志意乱。是故瞳子黑眼法于阴。白眼赤脉法于阳也。故阴阳合传而精明也。目者。心使也。心者。神之舍也。故神精乱而不转。卒然见非常处精神魂魄。散不相得。故曰惑也。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', '2JwtNXGLo1U');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('9BbssdO89es', 4, '{"title":"第20300807条・大惑论第八十","description":"<p>2、黄帝曰。余疑其然。余每之东苑。未曾不惑。去之则复。余唯独为东苑劳神乎。何其异也。岐伯曰。不然也。心有所喜。神有所恶。卒然相惑。则精气乱。视误。故惑。神移乃复。是故间者为迷。甚者为惑。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300807,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2、黄帝曰。余疑其然。余每之东苑。未曾不惑。去之则复。余唯独为东苑劳神乎。何其异也。岐伯曰。不然也。心有所喜。神有所恶。卒然相惑。则精气乱。视误。故惑。神移乃复。是故间者为迷。甚者为惑。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', '2JwtNXGLo1U');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('niU8OpAQheg', 4, '{"title":"第20300808条・大惑论第八十","description":"<p>3、黄帝曰。人之善忘者。何气使然。岐伯曰。上气不足。下气有余。肠胃实而心肺虚。虚则营卫留于下。久之不以时上。故善忘也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300808,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '3、黄帝曰。人之善忘者。何气使然。岐伯曰。上气不足。下气有余。肠胃实而心肺虚。虚则营卫留于下。久之不以时上。故善忘也。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', '2JwtNXGLo1U');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('bKpUT0B4dOr', 4, '{"title":"第20300809条・大惑论第八十","description":"<p>4、黄帝曰。人之善饥而不嗜食者。何气使然。岐伯曰。精气并于脾。热气留于胃。胃热则消谷。谷消故善饥。胃气逆上。则胃脘寒。故不嗜食也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300809,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '4、黄帝曰。人之善饥而不嗜食者。何气使然。岐伯曰。精气并于脾。热气留于胃。胃热则消谷。谷消故善饥。胃气逆上。则胃脘寒。故不嗜食也。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', '2JwtNXGLo1U');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('yZ8m3FHfUhi', 4, '{"title":"第20300810条・大惑论第八十","description":"<p>5、黄帝曰。病而不得卧者。何气使然。岐伯曰。卫气不得入于阴。常留于阳。留于阳则阳气满。阳气满则阳蹻盛。不得入于阴则阴气虚。故目不瞑矣。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300810,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '5、黄帝曰。病而不得卧者。何气使然。岐伯曰。卫气不得入于阴。常留于阳。留于阳则阳气满。阳气满则阳蹻盛。不得入于阴则阴气虚。故目不瞑矣。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', '2JwtNXGLo1U');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('dfjICBByiId', 4, '{"title":"第20300811条・大惑论第八十","description":"<p>6、黄帝曰。病目而不得视者。何气使然。岐伯曰。卫气留于阴。不得行于阳。留于阴则阴气盛。阴气盛则阴蹻满。不得入于阳则阳气虚。故目闭也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300811,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '6、黄帝曰。病目而不得视者。何气使然。岐伯曰。卫气留于阴。不得行于阳。留于阴则阴气盛。阴气盛则阴蹻满。不得入于阳则阳气虚。故目闭也。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', '2JwtNXGLo1U');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('He07dG7Xb0m', 4, '{"title":"第20300812条・大惑论第八十","description":"<p>7、黄帝曰。人之多卧者。何气使然。岐伯曰。此人肠胃大而皮肤湿。而分肉不解焉。肠胃大则卫气留久。皮肤湿则分肉不解。其行迟。夫卫气者。昼日常行于阳。夜行于阴。故阳气尽则卧。阴气尽则寤。故肠胃大。则卫气行留久。皮肤湿。分肉不解。则行迟。留于阴也久。其气不清。则欲瞑。故多卧矣。其肠胃小。皮肤滑以缓。分肉解利。卫气之留于阳也久。故少瞑焉。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300812,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '7、黄帝曰。人之多卧者。何气使然。岐伯曰。此人肠胃大而皮肤湿。而分肉不解焉。肠胃大则卫气留久。皮肤湿则分肉不解。其行迟。夫卫气者。昼日常行于阳。夜行于阴。故阳气尽则卧。阴气尽则寤。故肠胃大。则卫气行留久。皮肤湿。分肉不解。则行迟。留于阴也久。其气不清。则欲瞑。故多卧矣。其肠胃小。皮肤滑以缓。分肉解利。卫气之留于阳也久。故少瞑焉。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', '2JwtNXGLo1U');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('793R52vx7fI', 4, '{"title":"第20300813条・大惑论第八十","description":"<p>8、黄帝曰。其非常经也。卒然多卧者。何气使然。岐伯曰。邪气留于上焦。上焦闭而不通。已食若饮汤。卫气留久于阴而不行。故卒然多卧焉。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300813,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '8、黄帝曰。其非常经也。卒然多卧者。何气使然。岐伯曰。邪气留于上焦。上焦闭而不通。已食若饮汤。卫气留久于阴而不行。故卒然多卧焉。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', '2JwtNXGLo1U');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('L1ZRWaPaSSR', 4, '{"title":"第20300814条・大惑论第八十","description":"<p>9、黄帝曰。善。治此诸邪。奈何。岐伯曰。先其藏府。诛其小过。后调其气。盛者泻之。虚者补之。必先明知其形志之苦乐。定乃取之。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300814,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '9、黄帝曰。善。治此诸邪。奈何。岐伯曰。先其藏府。诛其小过。后调其气。盛者泻之。虚者补之。必先明知其形志之苦乐。定乃取之。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', '2JwtNXGLo1U');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('odIr0MqvJKR', 4, '{"title":"第20300815条・痈疽第八十一","description":"<p>1、黄帝曰。余闻肠胃受谷。上焦出气。以温分肉。而养骨节。通腠理。中焦出气如露。上注溪谷。而渗孙脉。津液和调。变化而赤为血。血和则孙脉先满溢。乃注于络脉。皆盈。乃注于经脉。阴阳已张。因息乃行。行有经纪。周有道理。与天合同。不得休止。切而调之。从虚去实。泻则不足。疾则气减。留则先后。从实去虚。补则有余。血气已调。形气乃持。余已知血气之平与不平。未知痈疽之所从生。成败之时。死生之期。有远近。何以度之。可得闻乎。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300815,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '1、黄帝曰。余闻肠胃受谷。上焦出气。以温分肉。而养骨节。通腠理。中焦出气如露。上注溪谷。而渗孙脉。津液和调。变化而赤为血。血和则孙脉先满溢。乃注于络脉。皆盈。乃注于经脉。阴阳已张。因息乃行。行有经纪。周有道理。与天合同。不得休止。切而调之。从虚去实。泻则不足。疾则气减。留则先后。从实去虚。补则有余。血气已调。形气乃持。余已知血气之平与不平。未知痈疽之所从生。成败之时。死生之期。有远近。何以度之。可得闻乎。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'rpNQpu2cyL2');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('0kgK34t6aw0', 4, '{"title":"第20300816条・痈疽第八十一","description":"<p>2、岐伯曰。经脉留行不止。与天同度。与地合纪。故天宿失度。日月薄蚀。地经失纪。水道流溢。草萓不成。五谷不殖。径路不通。民不往来。巷聚邑居。则别离异处。血气犹然。请言其故。夫血脉营卫。周流不休。上应星宿。下应经数。寒邪客于经络之中。则血泣。血泣则不通。不通则卫气归之。不得复反。故痈肿。寒气化为热。热胜则腐肉。肉腐则为脓。脓不泻则烂筋。筋烂则伤骨。骨伤则髓消。不当骨空。不得泄泻。血枯空虚。则筋骨肌肉不相荣。经脉败漏。熏于五藏。藏伤故死矣。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300816,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2、岐伯曰。经脉留行不止。与天同度。与地合纪。故天宿失度。日月薄蚀。地经失纪。水道流溢。草萓不成。五谷不殖。径路不通。民不往来。巷聚邑居。则别离异处。血气犹然。请言其故。夫血脉营卫。周流不休。上应星宿。下应经数。寒邪客于经络之中。则血泣。血泣则不通。不通则卫气归之。不得复反。故痈肿。寒气化为热。热胜则腐肉。肉腐则为脓。脓不泻则烂筋。筋烂则伤骨。骨伤则髓消。不当骨空。不得泄泻。血枯空虚。则筋骨肌肉不相荣。经脉败漏。熏于五藏。藏伤故死矣。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'rpNQpu2cyL2');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('64E3JqOkVxa', 4, '{"title":"第20300817条・痈疽第八十一","description":"<p>3、黄帝曰。愿尽闻痈疽之形。与忌曰名。岐伯曰。痈发于嗌中。名曰猛疽。猛疽不治。化为脓。脓不泻。塞咽。半日死。其化为脓者。泻则合豕膏。冷食。三日而已。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300817,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '3、黄帝曰。愿尽闻痈疽之形。与忌曰名。岐伯曰。痈发于嗌中。名曰猛疽。猛疽不治。化为脓。脓不泻。塞咽。半日死。其化为脓者。泻则合豕膏。冷食。三日而已。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'rpNQpu2cyL2');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ODsNjulz5ya', 4, '{"title":"第20300818条・痈疽第八十一","description":"<p>4、发于颈。名曰夭疽。其痈大以赤黑。不急治。则热气下入渊腋。前伤任脉。内熏肝肺。熏肝肺。十余日而死矣。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300818,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '4、发于颈。名曰夭疽。其痈大以赤黑。不急治。则热气下入渊腋。前伤任脉。内熏肝肺。熏肝肺。十余日而死矣。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'rpNQpu2cyL2');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('4ah4U25mo6c', 4, '{"title":"第20300819条・痈疽第八十一","description":"<p>5、阳留大发。消脑留项。名曰脑烁。其色不乐。项痛而如刺以针。烦心者。死不可治。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300819,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '2024-09-26T13:54:50.000Z', '5、阳留大发。消脑留项。名曰脑烁。其色不乐。项痛而如刺以针。烦心者。死不可治。', '2024-09-26T13:54:50.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'rpNQpu2cyL2');
